{
  "name": "Geometry Dash Spam Wave Test",
  "description": "Test your clicking speed and precision with the ultimate Geometry Dash Spam Wave Simulator. Survive the difficulty levels from Easy to Extreme Demon!"
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Difficulty {
  Easy = 'Easy',
  Hard = 'Hard',
  Insane = 'Insane',
  EasyDemon = 'Easy Demon',
  ExtremeDemon = 'Extreme Demon'
}

export interface DifficultyConfig {
  id: Difficulty;
  label: string;
  speed: number;
  gap: number; // in pixels
  color: string; // Hex code for the neon line
  secondaryColor: string; // For background/particles
  description: string;
}

export enum GameStatus {
  Idle = 'Idle',
  Playing = 'Playing',
  Won = 'Won',
  Lost = 'Lost'
}

export interface GameState {
  status: GameStatus;
  elapsedTime: number;
  bestTime: number;
}

import { Difficulty, DifficultyConfig } from './types';

export const WIN_TIME_MS = 15000; // 15 seconds to win
export const FPS = 60;
export const GRAVITY = 0.6; // For wave movement physics (constant speed up/down)
export const WAVE_SPEED_Y = 5; // Vertical speed of the wave

export const DIFFICULTY_CONFIGS: Record<Difficulty, DifficultyConfig> = {
  [Difficulty.Easy]: {
    id: Difficulty.Easy,
    label: 'Easy',
    speed: 3,
    gap: 120,
    color: '#22c55e', // Green
    secondaryColor: '#14532d',
    description: 'Wide gap. Good for warming up.',
  },
  [Difficulty.Hard]: {
    id: Difficulty.Hard,
    label: 'Hard',
    speed: 5,
    gap: 90,
    color: '#eab308', // Yellow
    secondaryColor: '#713f12',
    description: 'Faster with a tighter gap.',
  },
  [Difficulty.Insane]: {
    id: Difficulty.Insane,
    label: 'Insane',
    speed: 7,
    gap: 70,
    color: '#f97316', // Orange
    secondaryColor: '#7c2d12',
    description: 'High speed. fast reactions needed.',
  },
  [Difficulty.EasyDemon]: {
    id: Difficulty.EasyDemon,
    label: 'Easy Demon',
    speed: 9,
    gap: 50,
    color: '#ef4444', // Red
    secondaryColor: '#7f1d1d',
    description: 'Requires consistent spamming.',
  },
  [Difficulty.ExtremeDemon]: {
    id: Difficulty.ExtremeDemon,
    label: 'Extreme Demon',
    speed: 12,
    gap: 35,
    color: '#a855f7', // Purple/Pink
    secondaryColor: '#581c87',
    description: 'GOD-LIKE SPAM REQUIRED. Very tight.',
  },
};

import React from 'react';
import { Difficulty, DifficultyConfig } from '../types';
import { DIFFICULTY_CONFIGS } from '../constants';

interface DifficultySelectorProps {
  currentDifficulty: Difficulty;
  onSelect: (difficulty: Difficulty) => void;
  disabled: boolean;
}

const DifficultySelector: React.FC<DifficultySelectorProps> = ({ currentDifficulty, onSelect, disabled }) => {
  return (
    <div className="w-full max-w-4xl mx-auto mb-6">
      <div className="grid grid-cols-2 md:grid-cols-5 gap-2 md:gap-4 p-2 bg-slate-800/50 rounded-xl backdrop-blur-sm border border-slate-700">
        {Object.values(DIFFICULTY_CONFIGS).map((config: DifficultyConfig) => {
          const isSelected = currentDifficulty === config.id;

          return (
            <button
              key={config.id}
              onClick={() => onSelect(config.id)}
              disabled={disabled}
              className={`
                relative px-2 py-3 rounded-lg font-bold text-sm md:text-base transition-all duration-200
                flex flex-col items-center justify-center gap-1
                ${disabled ? 'opacity-50 cursor-not-allowed' : 'hover:scale-105 active:scale-95'}
                ${isSelected 
                  ? 'text-white shadow-[0_0_15px_rgba(0,0,0,0.5)] transform scale-105 border-2' 
                  : 'text-slate-400 hover:text-white bg-slate-900/50 border border-transparent'}
              `}
              style={{
                backgroundColor: isSelected ? config.secondaryColor : undefined,
                borderColor: isSelected ? config.color : undefined,
                boxShadow: isSelected ? `0 0 10px ${config.color}40` : undefined
              }}
            >
              <span className="z-10">{config.label}</span>
              {isSelected && (
                <div 
                  className="absolute inset-0 rounded-lg opacity-20"
                  style={{ backgroundColor: config.color }}
                />
              )}
            </button>
          );
        })}
      </div>
      <div className="text-center mt-2 h-6">
        <p className="text-slate-400 text-sm">
          {DIFFICULTY_CONFIGS[currentDifficulty].description} 
          <span className="ml-2 text-xs opacity-70">
            (Speed: {DIFFICULTY_CONFIGS[currentDifficulty].speed}, Gap: {DIFFICULTY_CONFIGS[currentDifficulty].gap}px)
          </span>
        </p>
      </div>
    </div>
  );
};

export default DifficultySelector;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Game State Refs (avoiding re-renders during loop)
  const gameState = useRef({
    playerY: 200,
    playerX: 100, // Fixed horizontal position
    velocityY: 0,
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    lastFrameTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0
  });

  const requestRef = useRef<number>();

  // Helper to spawn obstacles
  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 20;
    // Calculate max available space for the gap
    const availableSpace = canvasHeight - difficulty.gap - (minWall * 2);
    // Random top height
    const topHeight = Math.random() * availableSpace + minWall;

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), // Width scales slightly with speed
      topHeight: topHeight,
      bottomY: topHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      isHolding: false,
      obstacles: [],
      particles: [],
      trail: [],
      startTime: 0,
      lastFrameTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0
    };

    // Initial clear
    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate]);

  const createExplosion = (x: number, y: number, color: string) => {
    for (let i = 0; i < 20; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 5 + 2;
      gameState.current.particles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color
      });
    }
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Time management
    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    // Check Win
    if (elapsed >= WIN_TIME_MS) {
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    // Clear Canvas
    ctx.fillStyle = '#0f172a'; // Match bg-slate-900
    ctx.fillRect(0, 0, width, height);

    // --- PHYSICS ---

    // Update Player (Wave Physics: Constant speed up or down)
    // Geometry Dash wave moves at 45 degrees visually, so Y speed relates to X speed (game speed)
    // But for gameplay feel, we usually set a fixed efficient Y speed
    const waveSpeed = 6; // Pixels per frame vertical
    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    // Boundary collision
    if (gameState.current.playerY < 0 || gameState.current.playerY > height) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
      onStatusChange(GameStatus.Lost);
      return;
    }

    // Trail logic
    gameState.current.trail.push({ x: gameState.current.playerX, y: gameState.current.playerY });
    // Move trail points left to simulate forward movement
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    // Obstacle Logic
    const spawnDistance = 250; // Distance between obstacles
    if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
        // Only spawn if the last one has moved far enough left
        spawnObstacle(width, height, width + 50);
    }

    // Move & Cull Obstacles
    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      // Collision Detection
      // Player is a point/small circle at (playerX, playerY)
      // Obstacle has top rect and bottom rect
      const playerRadius = 4;

      // Horizontal overlap check
      if (gameState.current.playerX + playerRadius > obs.x && gameState.current.playerX - playerRadius < obs.x + obs.width) {
        // Vertical collision (hit top block OR hit bottom block)
        if (gameState.current.playerY - playerRadius < obs.topHeight || gameState.current.playerY + playerRadius > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
           onStatusChange(GameStatus.Lost);
           return;
        }
      }

      // Remove off-screen
      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // --- DRAWING ---

    // Draw Floor/Ceiling lines
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(width, 0);
    ctx.moveTo(0, height); ctx.lineTo(width, height);
    ctx.stroke();

    // Draw Obstacles
    ctx.fillStyle = '#1e293b'; // Slate-800
    ctx.strokeStyle = difficulty.color; // Neon color
    ctx.lineWidth = 2;

    gameState.current.obstacles.forEach(obs => {
      // Top Block
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);

      // Bottom Block
      const bottomH = height - obs.bottomY;
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);
      ctx.strokeRect(obs.x, obs.bottomY, obs.width, bottomH);

      // Glow effect inside gap
      ctx.fillStyle = difficulty.color;
      ctx.globalAlpha = 0.1;
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);
      ctx.globalAlpha = 1.0;
    });

    // Draw Trail
    if (gameState.current.trail.length > 1) {
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.shadowBlur = 10;
      ctx.shadowColor = difficulty.color;
      ctx.stroke();
      ctx.shadowBlur = 0; // Reset
    }

    // Draw Player Head
    ctx.beginPath();
    ctx.arc(gameState.current.playerX, gameState.current.playerY, 6, 0, Math.PI * 2);
    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = difficulty.color;
    ctx.stroke();

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle]);

  // Particle Loop (runs even when game stopped for explosion effect)
  const particleLoop = useCallback(() => {
    if (status === GameStatus.Playing) return; // Handled in main loop if playing

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    // Only clear if not playing (otherwise main loop clears)
    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, width, height);

        // Redraw obstacles static
        ctx.fillStyle = '#1e293b';
        ctx.strokeStyle = '#334155'; // dimmed
        gameState.current.obstacles.forEach(obs => {
            ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            const bottomH = height - obs.bottomY;
            ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, bottomH);
        });
    }

    // Update Particles
    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.02;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      ctx.beginPath();
      ctx.arc(p.x, p.y, 3 * p.life, 0, Math.PI * 2);
      ctx.fillStyle = p.color;
      ctx.globalAlpha = p.life;
      ctx.fill();
      ctx.globalAlpha = 1.0;
    }

    if (gameState.current.particles.length > 0) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status]);

  // Input Handlers
  const handleStart = () => {
    gameState.current.isHolding = true;
  };

  const handleEnd = () => {
    gameState.current.isHolding = false;
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        if (status === GameStatus.Idle || status === GameStatus.Lost || status === GameStatus.Won) {
           // Prevent auto-restart on spacebar if not intended, handled by UI button usually
           // but for convenience:
           if (status !== GameStatus.Playing) {
             // Optional: Allow space to start
           }
        }
        gameState.current.isHolding = true;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        gameState.current.isHolding = false;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [status]);

  // Main Loop Effect
  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  // Particle Loop Effect (for death animation)
  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  // Reset on Mount or Status change to Idle
  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]); // Also reset if difficulty changes

  // Canvas Sizing
  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              // If resizing during idle, redraw scene
              if (status === GameStatus.Idle) {
                   resetGame();
              }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div className="relative w-full max-w-4xl h-[400px] bg-slate-900 rounded-xl overflow-hidden shadow-2xl border-2 border-slate-700 mx-auto select-none touch-none" ref={containerRef}>
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer"
        onMouseDown={handleStart}
        onMouseUp={handleEnd}
        onMouseLeave={handleEnd}
        onTouchStart={(e) => { e.preventDefault(); handleStart(); }}
        onTouchEnd={(e) => { e.preventDefault(); handleEnd(); }}
      />

      {/* Overlays */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm z-10">
          <h2 className="text-3xl font-display font-bold text-white mb-4" style={{ color: difficulty.color }}>
            {difficulty.label}
          </h2>
          <p className="text-slate-300 mb-6 max-w-md text-center">
            Click, Tap, or Hold SPACE to fly. Avoid the obstacles for 15 seconds.
          </p>
          <button
            onClick={() => onStatusChange(GameStatus.Playing)}
            className="group relative px-8 py-4 bg-white text-black font-bold text-xl rounded-full hover:scale-105 transition-transform flex items-center gap-2"
          >
            <Play className="w-6 h-6 fill-black" />
            START GAME
            <div className="absolute inset-0 rounded-full bg-white opacity-0 group-hover:opacity-20 animate-pulse"></div>
          </button>
        </div>
      )}

      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 backdrop-blur-sm z-10">
          <AlertTriangle className="w-16 h-16 text-red-500 mb-4" />
          <h2 className="text-4xl font-display font-bold text-red-500 mb-2">CRASHED!</h2>
          <p className="text-slate-300 mb-6">You didn't survive the spam.</p>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="px-8 py-3 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded-lg flex items-center gap-2 transition-colors border border-slate-500"
          >
            <RotateCcw className="w-5 h-5" />
            TRY AGAIN
          </button>
        </div>
      )}

      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 backdrop-blur-sm z-10">
          <Trophy className="w-20 h-20 text-yellow-400 mb-4 animate-bounce" />
          <h2 className="text-4xl font-display font-bold text-yellow-400 mb-2">LEVEL COMPLETE!</h2>
          <p className="text-slate-300 mb-6">You conquered the {difficulty.label} spam!</p>
          <div className="flex gap-4">
             <button
              onClick={() => onStatusChange(GameStatus.Idle)}
              className="px-8 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold rounded-lg transition-colors"
            >
              PLAY AGAIN
            </button>
          </div>
        </div>
      )}

      {/* HUD */}
      <div className="absolute top-4 right-4 pointer-events-none">
          <div className="font-display font-bold text-4xl text-white drop-shadow-lg tabular-nums">
              {status === GameStatus.Playing || status === GameStatus.Lost ? (gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00") : "0.00"}s
          </div>
          <div className="text-right text-xs text-slate-400 font-bold uppercase tracking-wider">Survival Time</div>
      </div>

       <div className="absolute top-4 left-4 pointer-events-none">
          <div className="px-3 py-1 rounded bg-black/40 border border-white/10 text-xs font-bold text-slate-300 uppercase tracking-widest">
              {difficulty.label} Mode
          </div>
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useState, useEffect } from 'react';
import { Difficulty, GameStatus } from './types';
import { DIFFICULTY_CONFIGS } from './constants';
import DifficultySelector from './components/DifficultySelector';
import GameCanvas from './components/GameCanvas';
import { Zap, Activity, Info } from 'lucide-react';

export default function App() {
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.Easy);
  const [gameStatus, setGameStatus] = useState<GameStatus>(GameStatus.Idle);
  const [currentTime, setCurrentTime] = useState(0);

  // When selecting difficulty, if playing, stop game. Ideally, the prompt says "update variables immediately without reloading".
  // To achieve the "without reloading" feel for the user while resetting logic:
  // We'll set status to Idle to force a clean slate for the new physics parameters.
  const handleDifficultySelect = (newDiff: Difficulty) => {
    setDifficulty(newDiff);
    setGameStatus(GameStatus.Idle);
    setCurrentTime(0);
  };

  const currentConfig = DIFFICULTY_CONFIGS[difficulty];

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 selection:bg-cyan-500/30">
      {/* Background Grid Effect */}
      <div className="fixed inset-0 bg-[linear-gradient(to_right,#1e293b_1px,transparent_1px),linear-gradient(to_bottom,#1e293b_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_0%,#000_70%,transparent_100%)] opacity-20 pointer-events-none"></div>

      <div className="relative z-10 max-w-6xl mx-auto px-4 py-8 flex flex-col min-h-screen">

        {/* Header */}
        <header className="text-center mb-8 space-y-2">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-slate-900/80 border border-slate-700 text-cyan-400 text-xs font-bold tracking-widest uppercase mb-4 shadow-lg backdrop-blur-md">
            <Zap className="w-3 h-3" />
            Geometry Dash Spam Test
          </div>
          <h1 className="text-4xl md:text-6xl font-display font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-[0_0_15px_rgba(56,189,248,0.3)]">
            WAVE SIMULATOR
          </h1>
          <p className="text-slate-400 max-w-2xl mx-auto">
            Test your wave skills and spam consistency. Select a difficulty below and survive for 15 seconds.
          </p>
        </header>

        {/* Game Controls */}
        <main className="flex-grow flex flex-col items-center w-full">
          <DifficultySelector 
            currentDifficulty={difficulty} 
            onSelect={handleDifficultySelect} 
            disabled={gameStatus === GameStatus.Playing}
          />

          <GameCanvas 
            difficulty={currentConfig}
            status={gameStatus}
            onStatusChange={setGameStatus}
            onTimeUpdate={setCurrentTime}
          />

          {/* Instructions / Key Info */}
          <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-4 w-full max-w-4xl">
            <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800 flex items-start gap-3">
              <div className="p-2 bg-slate-800 rounded-lg text-cyan-400"><Activity className="w-5 h-5" /></div>
              <div>
                <h3 className="font-bold text-slate-200">Mechanics</h3>
                <p className="text-sm text-slate-400 mt-1">Hold <kbd className="bg-slate-700 px-1 rounded text-white font-mono">SPACE</kbd> or Click/Touch to move up. Release to move down.</p>
              </div>
