import React, { useState, useEffect, useRef } from 'react';
import { MousePointer2, RotateCcw, Timer } from 'lucide-react';

const CpsTest: React.FC = () => {
  const [active, setActive] = useState(false);
  const [finished, setFinished] = useState(false);
  const [clicks, setClicks] = useState(0);
  const [timeLeft, setTimeLeft] = useState(10.00);
  const timerRef = useRef<number | null>(null);

  const startTest = () => {
    setActive(true);
    setFinished(false);
    setClicks(1); // Count first click
    setTimeLeft(10.00);
  };

  const handleClick = () => {
    if (finished) return;
    if (!active) {
      startTest();
      return;
    }
    setClicks(c => c + 1);
  };

  const reset = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setActive(false);
    setFinished(false);
    setClicks(0);
    setTimeLeft(10.00);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  useEffect(() => {
    if (active && !finished) {
      const startTime = Date.now();
      timerRef.current = window.setInterval(() => {
        const elapsed = (Date.now() - startTime) / 1000;
        const remaining = Math.max(0, 10 - elapsed);
        setTimeLeft(remaining);

        if (remaining <= 0) {
          setFinished(true);
          setActive(false);
          if (timerRef.current) clearInterval(timerRef.current);
        }
      }, 10);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [active, finished]);

  const cps = finished ? (clicks / 10).toFixed(2) : (active ? (clicks / (10 - timeLeft)).toFixed(1) : "0.00");

  return (
    <div className="w-full max-w-4xl mx-auto animate-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-stretch">

        {/* Click Area */}
        <div className="relative aspect-square md:aspect-auto md:h-[400px]">
          <button
            onMouseDown={handleClick}
            className={`
              w-full h-full rounded-2xl border-2 flex flex-col items-center justify-center transition-all duration-100 active:scale-[0.98] select-none
              ${finished 
                ? 'bg-slate-900 border-slate-700 cursor-default opacity-50' 
                : 'bg-gradient-to-br from-blue-600 to-blue-800 border-blue-400 shadow-[0_0_40px_rgba(37,99,235,0.3)] hover:shadow-[0_0_60px_rgba(37,99,235,0.5)] cursor-pointer'
              }
            `}
          >
            {!active && !finished && (
              <>
                <MousePointer2 className="w-16 h-16 text-white mb-4 animate-bounce" />
                <span className="text-3xl font-display font-bold text-white tracking-widest">CLICK TO START</span>
                <span className="text-blue-200 mt-2 font-mono text-sm">10 SECOND TEST</span>
              </>
            )}

            {active && (
              <>
                <span className="text-8xl font-display font-black text-white drop-shadow-lg scale-110 transition-transform">{clicks}</span>
                <span className="text-blue-200 mt-4 font-mono uppercase tracking-widest">Clicks</span>
              </>
            )}

            {finished && (
               <span className="text-2xl font-display font-bold text-slate-400">TEST COMPLETE</span>
            )}
          </button>
        </div>

        {/* Stats Panel */}
        <div className="flex flex-col gap-4">
           {/* Timer */}
           <div className="bg-slate-900/50 backdrop-blur border border-white/10 p-6 rounded-2xl flex items-center justify-between">
              <div className="flex items-center gap-3">
                 <div className="p-3 rounded-lg bg-slate-800 text-blue-400">
                    <Timer className="w-6 h-6" />
                 </div>
                 <div>
                    <h3 className="text-slate-400 text-xs font-bold uppercase tracking-widest">Time Remaining</h3>
                    <p className="text-3xl font-mono font-bold text-white tabular-nums">{timeLeft.toFixed(2)}s</p>
                 </div>
              </div>
              <div className="h-12 w-12 rounded-full border-4 border-slate-700 flex items-center justify-center relative">
                 <svg className="absolute inset-0 transform -rotate-90 w-full h-full">
                    <circle cx="22" cy="22" r="18" stroke="currentColor" strokeWidth="4" fill="transparent" className="text-blue-600" strokeDasharray={113} strokeDashoffset={113 * (1 - timeLeft/10)} />
                 </svg>
              </div>
           </div>

           {/* Result Main */}
           <div className="flex-grow bg-slate-900/50 backdrop-blur border border-white/10 p-8 rounded-2xl flex flex-col items-center justify-center text-center relative overflow-hidden group">
               <div className="absolute inset-0 bg-blue-600/5 group-hover:bg-blue-600/10 transition-colors"></div>
               <h3 className="text-slate-400 font-bold uppercase tracking-widest mb-2 relative z-10">Your Speed</h3>
               <div className="text-7xl font-display font-black text-white mb-2 text-glow relative z-10">{finished ? cps : (active ? cps : '0.00')}</div>
               <div className="text-xl text-blue-400 font-mono relative z-10">CPS</div>

               {finished && (
                 <div className="mt-8 animate-in fade-in zoom-in duration-300 relative z-10">
                   <button 
                    onClick={reset}
                    className="px-8 py-3 bg-white text-blue-900 font-bold rounded-lg flex items-center gap-2 hover:bg-blue-50 transition-colors shadow-lg"
                   >
                     <RotateCcw className="w-5 h-5" /> TRY AGAIN
                   </button>
                 </div>
               )}
           </div>
        </div>
      </div>
    </div>
  );
};

export default CpsTest;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Keyboard, RotateCcw, Zap } from 'lucide-react';

const SpacebarCounter: React.FC = () => {
  const [active, setActive] = useState(false);
  const [finished, setFinished] = useState(false);
  const [count, setCount] = useState(0);
  const [timeLeft, setTimeLeft] = useState(10.00);
  const [isPressed, setIsPressed] = useState(false);
  const timerRef = useRef<number | null>(null);

  const startTest = useCallback(() => {
    setActive(true);
    setFinished(false);
    setCount(1);
    setTimeLeft(10.00);
  }, []);

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.code === 'Space') {
      e.preventDefault(); // Prevent scrolling
      if (e.repeat) return; // Ignore holding down

      setIsPressed(true);

      if (finished) return;

      if (!active) {
        startTest();
        return;
      }
      setCount(c => c + 1);
    }
  }, [active, finished, startTest]);

  const handleKeyUp = useCallback((e: KeyboardEvent) => {
    if (e.code === 'Space') {
      setIsPressed(false);
    }
  }, []);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [handleKeyDown, handleKeyUp]);

  useEffect(() => {
    if (active && !finished) {
      const startTime = Date.now();
      timerRef.current = window.setInterval(() => {
        const elapsed = (Date.now() - startTime) / 1000;
        const remaining = Math.max(0, 10 - elapsed);
        setTimeLeft(remaining);

        if (remaining <= 0) {
          setFinished(true);
          setActive(false);
          if (timerRef.current) clearInterval(timerRef.current);
        }
      }, 10);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [active, finished]);

  const reset = () => {
    setActive(false);
    setFinished(false);
    setCount(0);
    setTimeLeft(10.00);
  };

  return (
    <div className="w-full max-w-4xl mx-auto animate-in slide-in-from-bottom-4 duration-500">

      {/* Main Display */}
      <div className="relative bg-slate-900/60 backdrop-blur-md border border-white/10 rounded-2xl p-12 text-center overflow-hidden mb-8">

        <div className="relative z-10">
          <div className="mb-12">
            <h2 className="text-slate-400 font-bold uppercase tracking-[0.2em] mb-4">Spacebar Presses</h2>
            <div className="text-8xl md:text-9xl font-display font-black text-white tracking-tighter drop-shadow-2xl">
              {count}
            </div>
          </div>

          {/* Visual Spacebar */}
          <div className="flex justify-center mb-8">
            <div 
              className={`
                w-full max-w-md h-24 rounded-lg border-b-8 transition-all duration-75 flex items-center justify-center
                ${isPressed 
                  ? 'bg-purple-500 border-purple-700 translate-y-2 shadow-none' 
                  : 'bg-slate-200 border-slate-400 shadow-[0_10px_20px_rgba(0,0,0,0.5)] translate-y-0'
                }
              `}
            >
              <span className={`font-bold text-xl uppercase tracking-widest ${isPressed ? 'text-white' : 'text-slate-500'}`}>Space</span>
            </div>
          </div>

          {!active && !finished && (
            <p className="text-purple-400 animate-pulse font-mono">Press SPACE to Start 10s Timer</p>
          )}

          {active && (
            <p className="text-slate-500 font-mono">Time Remaining: <span className="text-white font-bold">{timeLeft.toFixed(2)}s</span></p>
          )}

          {finished && (
             <div className="animate-in fade-in zoom-in duration-300">
                <p className="text-xl text-white font-bold mb-4">Time's Up! Speed: <span className="text-purple-400">{(count / 10).toFixed(2)} CPS</span></p>
                <button 
                  onClick={reset}
                  className="px-8 py-3 bg-purple-600 hover:bg-purple-500 text-white font-bold rounded-lg inline-flex items-center gap-2 transition-colors shadow-lg"
                >
                  <RotateCcw className="w-5 h-5" /> RESET COUNTER
                </button>
             </div>
          )}
        </div>

        {/* Background Decorative */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] bg-purple-600/10 rounded-full blur-3xl pointer-events-none"></div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="bg-slate-900/40 p-6 rounded-xl border border-white/5 flex flex-col items-center">
             <Keyboard className="w-8 h-8 text-purple-500 mb-2" />
             <span className="text-slate-400 text-xs uppercase">Key</span>
             <span className="text-white font-bold">SPACEBAR</span>
          </div>
          <div className="bg-slate-900/40 p-6 rounded-xl border border-white/5 flex flex-col items-center">
             <Zap className="w-8 h-8 text-yellow-500 mb-2" />
             <span className="text-slate-400 text-xs uppercase">Speed (CPS)</span>
             <span className="text-white font-bold">{finished ? (count / 10).toFixed(2) : (active && timeLeft < 10 ? (count / (10 - timeLeft)).toFixed(2) : '0.00')}</span>
          </div>
          <div className="bg-slate-900/40 p-6 rounded-xl border border-white/5 flex flex-col items-center">
             <RotateCcw className="w-8 h-8 text-blue-500 mb-2 cursor-pointer hover:rotate-180 transition-transform" onClick={reset} />
             <span className="text-slate-400 text-xs uppercase">Reset</span>
             <span className="text-white font-bold">MANUAL</span>
          </div>
      </div>
    </div>
  );
};

export default SpacebarCounter;

import React, { useState, useRef } from 'react';
import { Timer, AlertCircle, Play } from 'lucide-react';

type TestState = 'idle' | 'waiting' | 'ready' | 'result' | 'early';

const ReactionTest: React.FC = () => {
  const [state, setState] = useState<TestState>('idle');
  const [result, setResult] = useState(0);
  const timeoutRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0);

  const startTest = () => {
    setState('waiting');
    const delay = Math.floor(Math.random() * 3000) + 2000; // 2-5 seconds

    timeoutRef.current = window.setTimeout(() => {
      setState('ready');
      startTimeRef.current = Date.now();
    }, delay);
  };

  const handleClick = () => {
    if (state === 'idle') {
      startTest();
    } else if (state === 'waiting') {
      // Clicked too early
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      setState('early');
    } else if (state === 'ready') {
      // Success
      const endTime = Date.now();
      setResult(endTime - startTimeRef.current);
      setState('result');
    } else if (state === 'result' || state === 'early') {
      startTest();
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto animate-in slide-in-from-bottom-4 duration-500">
      <div 
        onMouseDown={handleClick}
        className={`
          relative w-full h-[400px] rounded-2xl cursor-pointer transition-all duration-200 select-none flex flex-col items-center justify-center p-8 text-center shadow-2xl
          ${state === 'idle' ? 'bg-slate-800 hover:bg-slate-700 border-4 border-slate-600' : ''}
          ${state === 'waiting' ? 'bg-red-600 border-4 border-red-800' : ''}
          ${state === 'ready' ? 'bg-green-500 border-4 border-green-700' : ''}
          ${state === 'result' ? 'bg-slate-800 border-4 border-slate-600' : ''}
          ${state === 'early' ? 'bg-yellow-600 border-4 border-yellow-800' : ''}
        `}
      >

        {state === 'idle' && (
          <>
            <Play className="w-20 h-20 text-slate-400 mb-4" />
            <h2 className="text-4xl font-display font-bold text-white mb-2">Reaction Time Test</h2>
            <p className="text-slate-300 text-lg">Click anywhere to start.</p>
            <p className="text-slate-500 mt-4 text-sm">When the red box turns green, click as fast as you can.</p>
          </>
        )}

        {state === 'waiting' && (
          <>
             <div className="w-20 h-20 rounded-full border-4 border-white/20 border-t-white animate-spin mb-6"></div>
             <h2 className="text-5xl font-display font-bold text-white drop-shadow-lg">WAIT FOR GREEN...</h2>
          </>
        )}

        {state === 'ready' && (
           <>
             <Timer className="w-24 h-24 text-white mb-4 animate-ping" />
             <h2 className="text-6xl font-display font-black text-white drop-shadow-xl">CLICK!</h2>
           </>
        )}

        {state === 'result' && (
          <>
            <div className="text-8xl font-display font-black text-white mb-2 text-glow">{result} ms</div>
            <p className="text-slate-300 text-xl mb-8">Your reaction time</p>
            <div className="px-6 py-3 bg-slate-700 rounded-full text-white font-bold hover:bg-slate-600 transition-colors">
              Click to Try Again
            </div>
          </>
        )}

        {state === 'early' && (
          <>
            <AlertCircle className="w-20 h-20 text-white mb-4" />
            <h2 className="text-4xl font-display font-bold text-white mb-2">TOO SOON!</h2>
            <p className="text-white/80 text-lg">You clicked before it turned green.</p>
            <p className="mt-8 text-white/60 font-mono">Click to restart</p>
          </>
        )}
      </div>

      <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6 text-center">
         <div className="p-4 rounded-lg bg-slate-900/50 border border-white/5">
             <div className="text-slate-500 text-xs uppercase mb-1">Average Human</div>
             <div className="text-white font-bold text-xl">250 ms</div>
         </div>
         <div className="p-4 rounded-lg bg-slate-900/50 border border-white/5">
             <div className="text-slate-500 text-xs uppercase mb-1">Pro Gamer</div>
             <div className="text-green-400 font-bold text-xl">150-200 ms</div>
         </div>
         <div className="p-4 rounded-lg bg-slate-900/50 border border-white/5">
             <div className="text-slate-500 text-xs uppercase mb-1">Interpretation</div>
             <div className="text-slate-300 text-sm">Visual stimulus processing speed</div>
         </div>
      </div>
    </div>
  );
};

export default ReactionTest;

