        onStatusChange={setGameStatus}
        onTimeUpdate={setCurrentTime}
      />

      {/* Stats / Info Row */}
      <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-4 w-full max-w-5xl">
