import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS, WAVE_SPEED_Y } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle, ChevronsUp, Crown, Infinity as InfinityIcon } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
  isEndless?: boolean;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate, isEndless = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [bestTime, setBestTime] = useState<number>(0);

  // Game State Refs
  const gameState = useRef({
    playerY: 200,
    playerX: 100, 
    velocityY: 0,
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    lastFrameTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0,
    bgOffset: 0,
    shakeIntensity: 0
  });

  const requestRef = useRef<number>();

  // Load best time on mount or difficulty/mode change
  useEffect(() => {
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const savedBest = localStorage.getItem(storageKey);
    setBestTime(savedBest ? parseFloat(savedBest) : 0);
  }, [difficulty.id, isEndless]);

  const saveBestTime = (timeMs: number) => {
    const timeSec = timeMs / 1000;
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const currentBest = parseFloat(localStorage.getItem(storageKey) || '0');

    // For normal mode, cap at 15s (victory). For endless, sky is the limit.
    const effectiveTime = (!isEndless && timeSec > 15) ? 15 : timeSec;

    if (effectiveTime > currentBest) {
      localStorage.setItem(storageKey, effectiveTime.toFixed(2));
      setBestTime(effectiveTime);
    }
  };

  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 20;
    const spawnDistance = 250; 

    const lastObs = gameState.current.obstacles[gameState.current.obstacles.length - 1];

    let minTopLimit = minWall;
    let maxTopLimit = canvasHeight - difficulty.gap - minWall;

    if (lastObs) {
        const framesToReach = spawnDistance / difficulty.speed;
        const maxVerticalTravel = (framesToReach * WAVE_SPEED_Y) * 0.85;
        const prevTop = lastObs.topHeight;
        minTopLimit = Math.max(minWall, prevTop - maxVerticalTravel);
        maxTopLimit = Math.min(canvasHeight - difficulty.gap - minWall, prevTop + maxVerticalTravel);
    }

    if (minTopLimit > maxTopLimit) {
        const avg = (minTopLimit + maxTopLimit) / 2;
        minTopLimit = avg;
        maxTopLimit = avg;
    }

    const topHeight = Math.random() * (maxTopLimit - minTopLimit) + minTopLimit;

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), 
      topHeight: topHeight,
      bottomY: topHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      isHolding: false,
      obstacles: [],
      particles: [],
      trail: [],
      startTime: 0,
      lastFrameTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0,
      bgOffset: 0,
      shakeIntensity: 0
    };

    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate]);

  const createExplosion = (x: number, y: number, color: string) => {
    gameState.current.shakeIntensity = 15;
    for (let i = 0; i < 20; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 5 + 2;
      gameState.current.particles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color
      });
    }
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    // Win Condition (Only for Normal Mode)
    if (!isEndless && elapsed >= WIN_TIME_MS) {
      saveBestTime(WIN_TIME_MS);
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    // Scroll Background Grid
    gameState.current.bgOffset -= difficulty.speed * 0.5; 
    if (gameState.current.bgOffset <= -50) gameState.current.bgOffset += 50;

    // Apply Screen Shake
    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9; 
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    // Clear Canvas
    ctx.fillStyle = '#020617'; 
    ctx.fillRect(0, 0, width, height);

    // Draw Moving Grid
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for(let x = gameState.current.bgOffset; x < width; x += 50) { 
        if (x < 0) continue; 
        ctx.moveTo(x, 0); ctx.lineTo(x, height); 
    }
    for(let y = 0; y < height; y += 50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
    ctx.stroke();

    const waveSpeed = WAVE_SPEED_Y; 

    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    // Floor/Ceiling collision
    if (gameState.current.playerY < 0 || gameState.current.playerY > height) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
      saveBestTime(elapsed);
      onStatusChange(GameStatus.Lost);
      ctx.restore();
      return;
    }

    gameState.current.trail.push({ x: gameState.current.playerX, y: gameState.current.playerY });
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    const spawnDistance = 250; 
    if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
        spawnObstacle(width, height, width + 50);
    }

    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      const playerRadius = 4;

      if (gameState.current.playerX + playerRadius > obs.x && gameState.current.playerX - playerRadius < obs.x + obs.width) {
        if (gameState.current.playerY - playerRadius < obs.topHeight || gameState.current.playerY + playerRadius > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
           saveBestTime(elapsed);
           onStatusChange(GameStatus.Lost);
           ctx.restore();
           return;
        }
      }

      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // Draw Floor/Ceiling lines
    ctx.shadowBlur = 10;
    ctx.shadowColor = difficulty.color;
    ctx.strokeStyle = difficulty.color;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(width, 0);
    ctx.moveTo(0, height); ctx.lineTo(width, height);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw Obstacles
    ctx.fillStyle = '#0f172a';
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 1;

    gameState.current.obstacles.forEach(obs => {
      // Top
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);

      // Bottom
      const bottomH = height - obs.bottomY;
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);

      // Neon Edges
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 2;

      ctx.beginPath();
      ctx.moveTo(obs.x, 0); ctx.lineTo(obs.x, obs.topHeight); ctx.lineTo(obs.x + obs.width, obs.topHeight); ctx.lineTo(obs.x + obs.width, 0);
      ctx.moveTo(obs.x, height); ctx.lineTo(obs.x, obs.bottomY); ctx.lineTo(obs.x + obs.width, obs.bottomY); ctx.lineTo(obs.x + obs.width, height);
      ctx.stroke();

      ctx.fillStyle = difficulty.color;
      ctx.globalAlpha = 0.05;
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);
      ctx.globalAlpha = 1.0;
    });

    // Draw Trail
    if (gameState.current.trail.length > 1) {
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.shadowBlur = 15;
      ctx.shadowColor = difficulty.color;
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    // Draw Player
    ctx.beginPath();
    ctx.arc(gameState.current.playerX, gameState.current.playerY, 5, 0, Math.PI * 2);
    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = difficulty.color;
    ctx.stroke();

    ctx.restore();

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle, isEndless]);

  const particleLoop = useCallback(() => {
    if (status === GameStatus.Playing) return; 

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9;
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<width; x+=50) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
        for(let y=0; y<height; y+=50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
        ctx.stroke();

        ctx.strokeStyle = difficulty.color;
        ctx.lineWidth = 1;
        gameState.current.obstacles.forEach(obs => {
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
        });
    }

    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.02;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      ctx.beginPath();
      ctx.arc(p.x, p.y, 3 * p.life, 0, Math.PI * 2);
      ctx.fillStyle = p.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.color;
      ctx.globalAlpha = p.life;
      ctx.fill();
      ctx.globalAlpha = 1.0;
      ctx.shadowBlur = 0;
    }

    ctx.restore();

    if (gameState.current.particles.length > 0 || gameState.current.shakeIntensity > 0) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status, difficulty]);

  const handleStart = () => { gameState.current.isHolding = true; };
  const handleEnd = () => { gameState.current.isHolding = false; };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault(); 
        gameState.current.isHolding = true;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault();
        gameState.current.isHolding = false;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [status]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]);

  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              if (status === GameStatus.Idle) { resetGame(); }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div 
      className="relative w-full max-w-5xl aspect-video md:h-[500px] bg-slate-950 rounded-lg overflow-hidden transition-all duration-500 mx-auto select-none touch-none group" 
      ref={containerRef}
      style={{
        boxShadow: `0 0 30px ${difficulty.color}15, 0 0 0 1px ${difficulty.color}30`
      }}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer outline-none"
        onMouseDown={handleStart}
        onMouseUp={handleEnd}
        onMouseLeave={handleEnd}
        onTouchStart={(e) => { e.preventDefault(); handleStart(); }}
        onTouchEnd={(e) => { e.preventDefault(); handleEnd(); }}
      />

      {/* Decorative corners */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>

      {/* START SCREEN */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 backdrop-blur-[2px] z-10 animate-in fade-in duration-300">
          <div className="text-center space-y-6 p-8 border border-white/10 bg-black/50 rounded-2xl shadow-2xl backdrop-blur-md max-w-md mx-4">
            <div>
              <h2 className="text-5xl font-display font-black text-white mb-2 tracking-tight" style={{ textShadow: `0 0 20px ${difficulty.color}` }}>
                {difficulty.label.toUpperCase()}
              </h2>
              <div className="h-1 w-24 mx-auto rounded-full" style={{ backgroundColor: difficulty.color, boxShadow: `0 0 10px ${difficulty.color}` }}></div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm font-mono text-slate-400 bg-black/30 p-4 rounded-lg">
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Goal</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                      {isEndless ? (
                        <>Endless <InfinityIcon className="w-3 h-3" /></>
                      ) : (
                        "15 Seconds"
                      )}
                    </span>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Best Time</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                        <Crown className="w-3 h-3 text-yellow-500" />
                        {bestTime > 0 ? `${bestTime}s` : '--'}
                    </span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-2 text-xs text-slate-500 uppercase tracking-widest mb-4">
              <ChevronsUp className="w-4 h-4 animate-bounce" /> Hold Space to Fly
            </div>

            <button
              onClick={() => onStatusChange(GameStatus.Playing)}
              className="group relative w-full py-4 bg-white text-black font-display font-black text-xl rounded hover:scale-[1.02] transition-transform overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
              START RUN
            </button>
          </div>
        </div>
      )}

      {/* GAME OVER SCREEN */}
      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-200">
          <AlertTriangle className="w-20 h-20 text-red-500 mb-4 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
          <h2 className="text-6xl font-display font-black text-white italic mb-2 tracking-tighter text-glow">CRASHED</h2>

          {isEndless ? (
             <div className="mb-8 flex flex-col items-center">
                <span className="text-red-200 font-mono text-sm uppercase tracking-widest mb-1">Time Survived</span>
                <span className="text-4xl font-mono font-bold text-white">
                  {(gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00")}s
                </span>
             </div>
          ) : (
             <p className="text-red-200 mb-8 font-mono text-lg">Attempt Failed</p>
          )}

          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="px-10 py-3 bg-red-600 hover:bg-red-500 text-white font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] transition-all"
          >
            Retry
          </button>
        </div>
      )}

      {/* WIN SCREEN */}
      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-yellow-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-500">
          <Trophy className="w-24 h-24 text-yellow-400 mb-6 drop-shadow-[0_0_25px_rgba(250,204,21,0.6)] animate-pulse" />
          <h2 className="text-6xl font-display font-black text-white mb-2 tracking-tighter text-glow">CLEARED!</h2>
          <p className="text-yellow-100 mb-8 font-mono text-lg">{difficulty.label} Complete</p>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="px-10 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(234,179,8,0.4)] hover:shadow-[0_0_30px_rgba(234,179,8,0.6)] transition-all"
          >
            Play Again
          </button>
        </div>
      )}

      {/* IN-GAME HUD */}
      <div className="absolute top-6 right-6 pointer-events-none flex flex-col items-end">
          <div className="font-display font-black text-5xl text-white drop-shadow-md tabular-nums tracking-tight">
              {status === GameStatus.Playing || status === GameStatus.Lost ? (gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00") : "0.00"}
              <span className="text-2xl text-slate-400 ml-1">s</span>
          </div>

          {/* Progress Bar (Only for Normal Mode) */}
          {!isEndless && (
            <div className="w-48 h-2 bg-slate-800 rounded-full mt-2 overflow-hidden border border-slate-700">
              <div 
                className="h-full transition-all duration-75 ease-linear"
                style={{ 
                  width: `${Math.min(100, (gameState.current.startTime ? (Date.now() - gameState.current.startTime) : 0) / WIN_TIME_MS * 100)}%`,
                  backgroundColor: difficulty.color,
                  boxShadow: `0 0 10px ${difficulty.color}`
                }}
              />
            </div>
          )}
      </div>

       <div className="absolute top-6 left-6 pointer-events-none">
          <div 
            className="px-4 py-2 rounded-sm bg-black/60 backdrop-blur-md border-l-4 text-sm font-bold text-white uppercase tracking-widest shadow-lg mb-2"
            style={{ borderColor: difficulty.color }}
          >
              {difficulty.label} {isEndless && <span className="text-blue-400 ml-1">(∞)</span>}
          </div>
          {bestTime > 0 && (
             <div className="flex items-center gap-1 text-xs text-yellow-500 font-mono bg-black/40 px-2 py-1 rounded">
                <Crown className="w-3 h-3" /> Best: {bestTime}s
             </div>
          )}
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS, WAVE_SPEED_Y } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle, ChevronsUp, Crown, Infinity as InfinityIcon, Volume2, VolumeX } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
  isEndless?: boolean;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
  size: number;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate, isEndless = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [bestTime, setBestTime] = useState<number>(0);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Game State Refs
  const gameState = useRef({
    playerY: 200,
    playerX: 100, 
    velocityY: 0,
    rotation: 0, // In radians
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    lastFrameTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0,
    bgOffset: 0,
    shakeIntensity: 0
  });

  const requestRef = useRef<number>();

  // Initialize Audio Context
  const initAudio = useCallback(() => {
    if (!audioCtxRef.current) {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContext) {
        audioCtxRef.current = new AudioContext();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  }, []);

  const playSound = useCallback((type: 'crash' | 'win') => {
    if (isMuted || !audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    const now = ctx.currentTime;

    if (type === 'crash') {
      // Noise/Sawtooth crash
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(100, now);
      osc.frequency.exponentialRampToValueAtTime(10, now + 0.3);

      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'win') {
      // Major chord
      [523.25, 659.25, 783.99].forEach((freq, i) => { // C Major
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;

        const startTime = now + (i * 0.1);
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(0.1, startTime + 0.1);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + 0.8);

        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + 0.8);
      });
    }
  }, [isMuted]);

  // Load best time on mount or difficulty/mode change
  useEffect(() => {
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const savedBest = localStorage.getItem(storageKey);
    setBestTime(savedBest ? parseFloat(savedBest) : 0);
  }, [difficulty.id, isEndless]);

  const saveBestTime = (timeMs: number) => {
    const timeSec = timeMs / 1000;
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const currentBest = parseFloat(localStorage.getItem(storageKey) || '0');

    // For normal mode, cap at 15s (victory). For endless, sky is the limit.
    const effectiveTime = (!isEndless && timeSec > 15) ? 15 : timeSec;

    if (effectiveTime > currentBest) {
      localStorage.setItem(storageKey, effectiveTime.toFixed(2));
      setBestTime(effectiveTime);
    }
  };

  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 20;
    const spawnDistance = 250; 

    const lastObs = gameState.current.obstacles[gameState.current.obstacles.length - 1];

    let minTopLimit = minWall;
    let maxTopLimit = canvasHeight - difficulty.gap - minWall;

    if (lastObs) {
        const framesToReach = spawnDistance / difficulty.speed;
        const maxVerticalTravel = (framesToReach * WAVE_SPEED_Y) * 0.85;
        const prevTop = lastObs.topHeight;
        minTopLimit = Math.max(minWall, prevTop - maxVerticalTravel);
        maxTopLimit = Math.min(canvasHeight - difficulty.gap - minWall, prevTop + maxVerticalTravel);
    }

    if (minTopLimit > maxTopLimit) {
        const avg = (minTopLimit + maxTopLimit) / 2;
        minTopLimit = avg;
        maxTopLimit = avg;
    }

    const topHeight = Math.random() * (maxTopLimit - minTopLimit) + minTopLimit;

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), 
      topHeight: topHeight,
      bottomY: topHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      rotation: 0,
      isHolding: false,
      obstacles: [],
      particles: [],
      trail: [],
      startTime: 0,
      lastFrameTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0,
      bgOffset: 0,
      shakeIntensity: 0
    };

    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate]);

  const createExplosion = (x: number, y: number, color: string) => {
    gameState.current.shakeIntensity = 20;
    playSound('crash');
    for (let i = 0; i < 25; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 6 + 2;
      gameState.current.particles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color,
        size: Math.random() * 6 + 2
      });
    }
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    // Win Condition (Only for Normal Mode)
    if (!isEndless && elapsed >= WIN_TIME_MS) {
      saveBestTime(WIN_TIME_MS);
      playSound('win');
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    // Scroll Background Grid
    gameState.current.bgOffset -= difficulty.speed * 0.5; 
    if (gameState.current.bgOffset <= -50) gameState.current.bgOffset += 50;

    // Apply Screen Shake
    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9; 
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    // Clear Canvas
    ctx.fillStyle = '#020617'; 
    ctx.fillRect(0, 0, width, height);

    // Draw Moving Grid
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for(let x = gameState.current.bgOffset; x < width; x += 50) { 
        if (x < 0) continue; 
        ctx.moveTo(x, 0); ctx.lineTo(x, height); 
    }
    for(let y = 0; y < height; y += 50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
    ctx.stroke();

    const waveSpeed = WAVE_SPEED_Y; 

    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    // Calculate Rotation (Smooth-ish)
    const targetRotation = gameState.current.isHolding ? -Math.PI / 4 : Math.PI / 4;
    // Snappy interpolation
    gameState.current.rotation += (targetRotation - gameState.current.rotation) * 0.4;

    // Floor/Ceiling collision
    if (gameState.current.playerY < 0 || gameState.current.playerY > height) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
      saveBestTime(elapsed);
      onStatusChange(GameStatus.Lost);
      ctx.restore();
      return;
    }

    // Trail Logic (Adjusted for triangle tip)
    gameState.current.trail.push({ x: gameState.current.playerX - 5, y: gameState.current.playerY });
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    const spawnDistance = 250; 
    if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
        spawnObstacle(width, height, width + 50);
    }

    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      // Hitbox (Simplified to a small box in center of player)
      const playerSize = 6;

      if (gameState.current.playerX + playerSize > obs.x && gameState.current.playerX - playerSize < obs.x + obs.width) {
        if (gameState.current.playerY - playerSize < obs.topHeight || gameState.current.playerY + playerSize > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
           saveBestTime(elapsed);
           onStatusChange(GameStatus.Lost);
           ctx.restore();
           return;
        }
      }

      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // Draw Floor/Ceiling lines
    ctx.shadowBlur = 10;
    ctx.shadowColor = difficulty.color;
    ctx.strokeStyle = difficulty.color;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(width, 0);
    ctx.moveTo(0, height); ctx.lineTo(width, height);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw Obstacles
    ctx.fillStyle = '#0f172a';
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 1;

    gameState.current.obstacles.forEach(obs => {
      // Top
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);

      // Bottom
      const bottomH = height - obs.bottomY;
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);

      // Neon Edges
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 2;

      ctx.beginPath();
      ctx.moveTo(obs.x, 0); ctx.lineTo(obs.x, obs.topHeight); ctx.lineTo(obs.x + obs.width, obs.topHeight); ctx.lineTo(obs.x + obs.width, 0);
      ctx.moveTo(obs.x, height); ctx.lineTo(obs.x, obs.bottomY); ctx.lineTo(obs.x + obs.width, obs.bottomY); ctx.lineTo(obs.x + obs.width, height);
      ctx.stroke();

      ctx.fillStyle = difficulty.color;
      ctx.globalAlpha = 0.05;
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);
      ctx.globalAlpha = 1.0;
    });

    // Draw Trail
    if (gameState.current.trail.length > 1) {
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.shadowBlur = 10;
      ctx.shadowColor = difficulty.color;
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    // Draw Player (Triangle Wave Icon)
    ctx.save();
    ctx.translate(gameState.current.playerX, gameState.current.playerY);
    ctx.rotate(gameState.current.rotation);

    ctx.beginPath();
    ctx.moveTo(-6, -6);
    ctx.lineTo(8, 0);
    ctx.lineTo(-6, 6);
    ctx.closePath();

    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = difficulty.color;
    ctx.stroke();

    // Inner detail
    ctx.beginPath();
    ctx.moveTo(-2, -2);
    ctx.lineTo(2, 0);
    ctx.lineTo(-2, 2);
    ctx.closePath();
    ctx.fillStyle = difficulty.color;
    ctx.fill();

    ctx.restore(); // Restore from rotation
    ctx.restore(); // Restore from shake

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle, isEndless, playSound]);

  const particleLoop = useCallback(() => {
    if (status === GameStatus.Playing) return; 

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9;
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<width; x+=50) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
        for(let y=0; y<height; y+=50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
        ctx.stroke();

        ctx.strokeStyle = difficulty.color;
        ctx.lineWidth = 1;
        gameState.current.obstacles.forEach(obs => {
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
        });
    }

    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.02;
      p.vx *= 0.95; // Drag
      p.vy *= 0.95;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      // Draw Square Particles
      ctx.fillStyle = p.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.color;
      ctx.globalAlpha = p.life;
      ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
      ctx.globalAlpha = 1.0;
      ctx.shadowBlur = 0;
    }

    ctx.restore();

    if (gameState.current.particles.length > 0 || gameState.current.shakeIntensity > 0) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status, difficulty]);

  const handleStart = () => { 
    initAudio();
    gameState.current.isHolding = true; 
  };
  const handleEnd = () => { gameState.current.isHolding = false; };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault(); 

        // Instant Restart Feature
        if (status === GameStatus.Lost) {
             resetGame();
             onStatusChange(GameStatus.Playing);
             return;
        }

        if (status === GameStatus.Idle) {
            initAudio();
        }

        gameState.current.isHolding = true;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault();
        gameState.current.isHolding = false;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [status, resetGame, onStatusChange, initAudio]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]);

  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              if (status === GameStatus.Idle) { resetGame(); }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div 
      className="relative w-full max-w-5xl aspect-video md:h-[500px] bg-slate-950 rounded-lg overflow-hidden transition-all duration-500 mx-auto select-none touch-none group" 
      ref={containerRef}
      style={{
        boxShadow: `0 0 30px ${difficulty.color}15, 0 0 0 1px ${difficulty.color}30`
      }}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer outline-none"
        onMouseDown={handleStart}
        onMouseUp={handleEnd}
        onMouseLeave={handleEnd}
        onTouchStart={(e) => { e.preventDefault(); handleStart(); }}
        onTouchEnd={(e) => { e.preventDefault(); handleEnd(); }}
      />

      {/* Decorative corners */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>

      {/* Mute Button */}
      <button 
        onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
        className="absolute bottom-4 right-4 z-20 p-2 bg-black/40 hover:bg-black/60 backdrop-blur rounded-full text-slate-400 hover:text-white transition-colors"
        title={isMuted ? "Unmute" : "Mute"}
      >
        {isMuted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
      </button>

      {/* START SCREEN */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 backdrop-blur-[2px] z-10 animate-in fade-in duration-300">
          <div className="text-center space-y-6 p-8 border border-white/10 bg-black/50 rounded-2xl shadow-2xl backdrop-blur-md max-w-md mx-4">
            <div>
              <h2 className="text-5xl font-display font-black text-white mb-2 tracking-tight" style={{ textShadow: `0 0 20px ${difficulty.color}` }}>
                {difficulty.label.toUpperCase()}
              </h2>
              <div className="h-1 w-24 mx-auto rounded-full" style={{ backgroundColor: difficulty.color, boxShadow: `0 0 10px ${difficulty.color}` }}></div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm font-mono text-slate-400 bg-black/30 p-4 rounded-lg">
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Goal</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                      {isEndless ? (
                        <>Endless <InfinityIcon className="w-3 h-3" /></>
                      ) : (
                        "15 Seconds"
                      )}
                    </span>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Best Time</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                        <Crown className="w-3 h-3 text-yellow-500" />
                        {bestTime > 0 ? `${bestTime}s` : '--'}
                    </span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-2 text-xs text-slate-500 uppercase tracking-widest mb-4">
              <ChevronsUp className="w-4 h-4 animate-bounce" /> Hold Space to Fly
            </div>

            <button
              onClick={() => { initAudio(); onStatusChange(GameStatus.Playing); }}
              className="group relative w-full py-4 bg-white text-black font-display font-black text-xl rounded hover:scale-[1.02] transition-transform overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
              START RUN
            </button>
          </div>
        </div>
      )}

      {/* GAME OVER SCREEN */}
      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-200">
          <AlertTriangle className="w-20 h-20 text-red-500 mb-4 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
          <h2 className="text-6xl font-display font-black text-white italic mb-2 tracking-tighter text-glow">CRASHED</h2>

          {isEndless ? (
             <div className="mb-8 flex flex-col items-center">
                <span className="text-red-200 font-mono text-sm uppercase tracking-widest mb-1">Time Survived</span>
                <span className="text-4xl font-mono font-bold text-white">
                  {(gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00")}s
                </span>
             </div>
          ) : (
             <p className="text-red-200 mb-4 font-mono text-lg">Attempt Failed</p>
          )}

          <div className="flex flex-col items-center gap-3">
             <button
                onClick={() => onStatusChange(GameStatus.Idle)}
                className="px-10 py-3 bg-red-600 hover:bg-red-500 text-white font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] transition-all"
             >
                Retry
             </button>
             <span className="text-xs text-red-300/60 font-mono uppercase tracking-widest">Press Space to Restart</span>
          </div>
        </div>
      )}

      {/* WIN SCREEN */}
      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-yellow-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-500">
          <Trophy className="w-24 h-24 text-yellow-400 mb-6 drop-shadow-[0_0_25px_rgba(250,204,21,0.6)] animate-pulse" />
          <h2 className="text-6xl font-display font-black text-white mb-2 tracking-tighter text-glow">CLEARED!</h2>
          <p className="text-yellow-100 mb-8 font-mono text-lg">{difficulty.label} Complete</p>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="px-10 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(234,179,8,0.4)] hover:shadow-[0_0_30px_rgba(234,179,8,0.6)] transition-all"
          >
            Play Again
          </button>
        </div>
      )}

      {/* IN-GAME HUD */}
      <div className="absolute top-6 right-6 pointer-events-none flex flex-col items-end">
          <div className="font-display font-black text-5xl text-white drop-shadow-md tabular-nums tracking-tight">
              {status === GameStatus.Playing || status === GameStatus.Lost ? (gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00") : "0.00"}
              <span className="text-2xl text-slate-400 ml-1">s</span>
          </div>

          {/* Progress Bar (Only for Normal Mode) */}
          {!isEndless && (
            <div className="w-48 h-2 bg-slate-800 rounded-full mt-2 overflow-hidden border border-slate-700">
              <div 
                className="h-full transition-all duration-75 ease-linear"
                style={{ 
                  width: `${Math.min(100, (gameState.current.startTime ? (Date.now() - gameState.current.startTime) : 0) / WIN_TIME_MS * 100)}%`,
                  backgroundColor: difficulty.color,
                  boxShadow: `0 0 10px ${difficulty.color}`
                }}
              />
            </div>
          )}
      </div>

       <div className="absolute top-6 left-6 pointer-events-none">
          <div 
            className="px-4 py-2 rounded-sm bg-black/60 backdrop-blur-md border-l-4 text-sm font-bold text-white uppercase tracking-widest shadow-lg mb-2"
            style={{ borderColor: difficulty.color }}
          >
              {difficulty.label} {isEndless && <span className="text-blue-400 ml-1">(∞)</span>}
          </div>
          {bestTime > 0 && (
             <div className="flex items-center gap-1 text-xs text-yellow-500 font-mono bg-black/40 px-2 py-1 rounded">
                <Crown className="w-3 h-3" /> Best: {bestTime}s
             </div>
          )}
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS, WAVE_SPEED_Y } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle, ChevronsUp, Crown, Infinity as InfinityIcon, Volume2, VolumeX, XCircle } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
  isEndless?: boolean;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
  size: number;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate, isEndless = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [bestTime, setBestTime] = useState<number>(0);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Game State Refs
  const gameState = useRef({
    playerY: 200,
    playerX: 100, 
    velocityY: 0,
    rotation: 0, // In radians
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    lastFrameTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0,
    bgOffset: 0,
    shakeIntensity: 0,
    deathCoords: { x: 0, y: 0 } // Store exact death location
  });

  const requestRef = useRef<number>();

  // Initialize Audio Context
  const initAudio = useCallback(() => {
    if (!audioCtxRef.current) {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContext) {
        audioCtxRef.current = new AudioContext();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  }, []);

  const playSound = useCallback((type: 'crash' | 'win') => {
    if (isMuted || !audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    const now = ctx.currentTime;

    if (type === 'crash') {
      // Noise/Sawtooth crash
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(100, now);
      osc.frequency.exponentialRampToValueAtTime(10, now + 0.3);

      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'win') {
      // Major chord
      [523.25, 659.25, 783.99].forEach((freq, i) => { // C Major
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;

        const startTime = now + (i * 0.1);
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(0.1, startTime + 0.1);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + 0.8);

        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + 0.8);
      });
    }
  }, [isMuted]);

  // Load best time on mount or difficulty/mode change
  useEffect(() => {
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const savedBest = localStorage.getItem(storageKey);
    setBestTime(savedBest ? parseFloat(savedBest) : 0);
  }, [difficulty.id, isEndless]);

  const saveBestTime = (timeMs: number) => {
    const timeSec = timeMs / 1000;
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const currentBest = parseFloat(localStorage.getItem(storageKey) || '0');

    // For normal mode, cap at 15s (victory). For endless, sky is the limit.
    const effectiveTime = (!isEndless && timeSec > 15) ? 15 : timeSec;

    if (effectiveTime > currentBest) {
      localStorage.setItem(storageKey, effectiveTime.toFixed(2));
      setBestTime(effectiveTime);
    }
  };

  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 20;
    const spawnDistance = 250; 

    const lastObs = gameState.current.obstacles[gameState.current.obstacles.length - 1];

    let minTopLimit = minWall;
    let maxTopLimit = canvasHeight - difficulty.gap - minWall;

    if (lastObs) {
        const framesToReach = spawnDistance / difficulty.speed;
        const maxVerticalTravel = (framesToReach * WAVE_SPEED_Y) * 0.85;
        const prevTop = lastObs.topHeight;
        minTopLimit = Math.max(minWall, prevTop - maxVerticalTravel);
        maxTopLimit = Math.min(canvasHeight - difficulty.gap - minWall, prevTop + maxVerticalTravel);
    }

    if (minTopLimit > maxTopLimit) {
        const avg = (minTopLimit + maxTopLimit) / 2;
        minTopLimit = avg;
        maxTopLimit = avg;
    }

    const topHeight = Math.random() * (maxTopLimit - minTopLimit) + minTopLimit;

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), 
      topHeight: topHeight,
      bottomY: topHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      rotation: 0,
      isHolding: false,
      obstacles: [],
      particles: [],
      trail: [],
      startTime: 0,
      lastFrameTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0,
      bgOffset: 0,
      shakeIntensity: 0,
      deathCoords: { x: 0, y: 0 }
    };

    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate]);

  const createExplosion = (x: number, y: number, color: string) => {
    gameState.current.shakeIntensity = 20;
    gameState.current.deathCoords = { x, y }; // Record death spot
    playSound('crash');

    for (let i = 0; i < 25; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 6 + 2;

      // Momentum: Add the horizontal speed of the level to particles to simulate forward inertia
      const forwardMomentum = difficulty.speed * 0.5;

      gameState.current.particles.push({
        x,
        y,
        vx: (Math.cos(angle) * speed) + forwardMomentum, // Add forward momentum
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color,
        size: Math.random() * 6 + 2
      });
    }
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    // Win Condition (Only for Normal Mode)
    if (!isEndless && elapsed >= WIN_TIME_MS) {
      saveBestTime(WIN_TIME_MS);
      playSound('win');
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    // Atmospheric Pulse (0.8 to 1.2 scale roughly over time)
    const pulseFactor = 1 + Math.sin(time / 200) * 0.1; 

    // Scroll Background Grid
    gameState.current.bgOffset -= difficulty.speed * 0.5; 
    if (gameState.current.bgOffset <= -50) gameState.current.bgOffset += 50;

    // Apply Screen Shake
    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9; 
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    // Clear Canvas
    ctx.fillStyle = '#020617'; 
    ctx.fillRect(0, 0, width, height);

    // Draw Moving Grid
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5 + (pulseFactor * 0.1); // Pulse opacity
    ctx.beginPath();
    for(let x = gameState.current.bgOffset; x < width; x += 50) { 
        if (x < 0) continue; 
        ctx.moveTo(x, 0); ctx.lineTo(x, height); 
    }
    for(let y = 0; y < height; y += 50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
    ctx.stroke();
    ctx.globalAlpha = 1.0;

    const waveSpeed = WAVE_SPEED_Y; 

    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    // Dynamic Rotation Calculation
    // Angle = atan(vertical_speed / horizontal_speed)
    // We want visually accurate slope. 
    // Holding = Moving Up (-Y), Not Holding = Moving Down (+Y)
    const slopeAngle = Math.atan2(WAVE_SPEED_Y, difficulty.speed);
    const targetRotation = gameState.current.isHolding ? -slopeAngle : slopeAngle;

    // Snappy interpolation
    gameState.current.rotation += (targetRotation - gameState.current.rotation) * 0.5;

    // Floor/Ceiling collision
    if (gameState.current.playerY < 0 || gameState.current.playerY > height) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
      saveBestTime(elapsed);
      onStatusChange(GameStatus.Lost);
      ctx.restore();
      return;
    }

    // Trail Logic
    gameState.current.trail.push({ x: gameState.current.playerX - 5, y: gameState.current.playerY });
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    const spawnDistance = 250; 
    if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
        spawnObstacle(width, height, width + 50);
    }

    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      // Hitbox
      const playerSize = 6;

      if (gameState.current.playerX + playerSize > obs.x && gameState.current.playerX - playerSize < obs.x + obs.width) {
        if (gameState.current.playerY - playerSize < obs.topHeight || gameState.current.playerY + playerSize > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
           saveBestTime(elapsed);
           onStatusChange(GameStatus.Lost);
           ctx.restore();
           return;
        }
      }

      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // Draw Floor/Ceiling lines with pulse
    ctx.shadowBlur = 10 * pulseFactor;
    ctx.shadowColor = difficulty.color;
    ctx.strokeStyle = difficulty.color;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(width, 0);
    ctx.moveTo(0, height); ctx.lineTo(width, height);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw Obstacles
    ctx.fillStyle = '#0f172a';
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 1;

    gameState.current.obstacles.forEach(obs => {
      // Top
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);

      // Bottom
      const bottomH = height - obs.bottomY;
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);

      // Neon Edges
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 2;

      ctx.beginPath();
      ctx.moveTo(obs.x, 0); ctx.lineTo(obs.x, obs.topHeight); ctx.lineTo(obs.x + obs.width, obs.topHeight); ctx.lineTo(obs.x + obs.width, 0);
      ctx.moveTo(obs.x, height); ctx.lineTo(obs.x, obs.bottomY); ctx.lineTo(obs.x + obs.width, obs.bottomY); ctx.lineTo(obs.x + obs.width, height);
      ctx.stroke();

      // Pulsing Glow inside
      ctx.fillStyle = difficulty.color;
      ctx.globalAlpha = 0.05 * pulseFactor;
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);
      ctx.globalAlpha = 1.0;
    });

    // Draw Trail
    if (gameState.current.trail.length > 1) {
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.shadowBlur = 10 * pulseFactor;
      ctx.shadowColor = difficulty.color;
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    // Draw Player
    ctx.save();
    ctx.translate(gameState.current.playerX, gameState.current.playerY);
    ctx.rotate(gameState.current.rotation);

    ctx.beginPath();
    ctx.moveTo(-6, -6);
    ctx.lineTo(8, 0);
    ctx.lineTo(-6, 6);
    ctx.closePath();

    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = difficulty.color;
    ctx.stroke();

    // Inner detail
    ctx.beginPath();
    ctx.moveTo(-2, -2);
    ctx.lineTo(2, 0);
    ctx.lineTo(-2, 2);
    ctx.closePath();
    ctx.fillStyle = difficulty.color;
    ctx.fill();

    ctx.restore(); // Restore from rotation
    ctx.restore(); // Restore from shake

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle, isEndless, playSound]);

  const particleLoop = useCallback((time: number) => {
    if (status === GameStatus.Playing) return; 

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    // Pulse in death screen too
    const pulseFactor = 1 + Math.sin(time / 200) * 0.1;

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9;
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<width; x+=50) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
        for(let y=0; y<height; y+=50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
        ctx.stroke();

        ctx.strokeStyle = difficulty.color;
        ctx.lineWidth = 1;
        gameState.current.obstacles.forEach(obs => {
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
        });

        // Draw Death Marker (X)
        if (status === GameStatus.Lost) {
          const { x, y } = gameState.current.deathCoords;
          ctx.strokeStyle = '#ef4444';
          ctx.lineWidth = 3;
          ctx.shadowColor = '#ef4444';
          ctx.shadowBlur = 15 * pulseFactor;

          const size = 10;
          ctx.beginPath();
          ctx.moveTo(x - size, y - size);
          ctx.lineTo(x + size, y + size);
          ctx.moveTo(x + size, y - size);
          ctx.lineTo(x - size, y + size);
          ctx.stroke();

          // Death Circle ring
          ctx.beginPath();
          ctx.arc(x, y, size * 2 * pulseFactor, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(239, 68, 68, ${0.5 * pulseFactor})`;
          ctx.stroke();
          ctx.shadowBlur = 0;
        }
    }

    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.02;
      p.vx *= 0.95; // Drag
      p.vy *= 0.95;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      // Draw Square Particles
      ctx.fillStyle = p.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.color;
      ctx.globalAlpha = p.life;
      ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
      ctx.globalAlpha = 1.0;
      ctx.shadowBlur = 0;
    }

    ctx.restore();

    if (gameState.current.particles.length > 0 || gameState.current.shakeIntensity > 0 || status === GameStatus.Lost) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status, difficulty]);

  const handleStart = () => { 
    initAudio();
    gameState.current.isHolding = true; 
  };
  const handleEnd = () => { gameState.current.isHolding = false; };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault(); 

        // Instant Restart Feature
        if (status === GameStatus.Lost) {
             resetGame();
             onStatusChange(GameStatus.Playing);
             return;
        }

        if (status === GameStatus.Idle) {
            initAudio();
        }

        gameState.current.isHolding = true;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault();
        gameState.current.isHolding = false;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [status, resetGame, onStatusChange, initAudio]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]);

  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              if (status === GameStatus.Idle) { resetGame(); }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div 
      className="relative w-full max-w-5xl aspect-video md:h-[500px] bg-slate-950 rounded-lg overflow-hidden transition-all duration-500 mx-auto select-none touch-none group" 
      ref={containerRef}
      style={{
        boxShadow: `0 0 30px ${difficulty.color}15, 0 0 0 1px ${difficulty.color}30`
      }}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer outline-none"
        onMouseDown={handleStart}
        onMouseUp={handleEnd}
        onMouseLeave={handleEnd}
        onTouchStart={(e) => { e.preventDefault(); handleStart(); }}
        onTouchEnd={(e) => { e.preventDefault(); handleEnd(); }}
      />

      {/* Decorative corners */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>

      {/* Mute Button */}
      <button 
        onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
        className="absolute bottom-4 right-4 z-20 p-2 bg-black/40 hover:bg-black/60 backdrop-blur rounded-full text-slate-400 hover:text-white transition-colors"
        title={isMuted ? "Unmute" : "Mute"}
      >
        {isMuted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
      </button>

      {/* START SCREEN */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 backdrop-blur-[2px] z-10 animate-in fade-in duration-300">
          <div className="text-center space-y-6 p-8 border border-white/10 bg-black/50 rounded-2xl shadow-2xl backdrop-blur-md max-w-md mx-4">
            <div>
              <h2 className="text-5xl font-display font-black text-white mb-2 tracking-tight" style={{ textShadow: `0 0 20px ${difficulty.color}` }}>
                {difficulty.label.toUpperCase()}
              </h2>
              <div className="h-1 w-24 mx-auto rounded-full" style={{ backgroundColor: difficulty.color, boxShadow: `0 0 10px ${difficulty.color}` }}></div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm font-mono text-slate-400 bg-black/30 p-4 rounded-lg">
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Goal</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                      {isEndless ? (
                        <>Endless <InfinityIcon className="w-3 h-3" /></>
                      ) : (
                        "15 Seconds"
                      )}
                    </span>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Best Time</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                        <Crown className="w-3 h-3 text-yellow-500" />
                        {bestTime > 0 ? `${bestTime}s` : '--'}
                    </span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-2 text-xs text-slate-500 uppercase tracking-widest mb-4">
              <ChevronsUp className="w-4 h-4 animate-bounce" /> Hold Space to Fly
            </div>

            <button
              onClick={() => { initAudio(); onStatusChange(GameStatus.Playing); }}
              className="group relative w-full py-4 bg-white text-black font-display font-black text-xl rounded hover:scale-[1.02] transition-transform overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
              START RUN
            </button>
          </div>
        </div>
      )}

      {/* GAME OVER SCREEN */}
      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-200">
          <div className="relative mb-4">
             <AlertTriangle className="w-20 h-20 text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
             <div className="absolute -bottom-2 -right-2 bg-red-600 rounded-full p-1 animate-ping"></div>
          </div>

          <h2 className="text-6xl font-display font-black text-white italic mb-2 tracking-tighter text-glow">CRASHED</h2>

          {isEndless ? (
             <div className="mb-8 flex flex-col items-center">
                <span className="text-red-200 font-mono text-sm uppercase tracking-widest mb-1">Time Survived</span>
                <span className="text-4xl font-mono font-bold text-white">
                  {(gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00")}s
                </span>
             </div>
          ) : (
             <p className="text-red-200 mb-4 font-mono text-lg">Attempt Failed</p>
          )}

          <div className="flex flex-col items-center gap-3">
             <button
                onClick={() => onStatusChange(GameStatus.Idle)}
                className="px-10 py-3 bg-red-600 hover:bg-red-500 text-white font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] transition-all"
             >
                Retry
             </button>
             <span className="text-xs text-red-300/60 font-mono uppercase tracking-widest flex items-center gap-2">
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div> 
                 Press Space to Restart
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div>
             </span>
          </div>
        </div>
      )}

      {/* WIN SCREEN */}
      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-yellow-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-500">
          <Trophy className="w-24 h-24 text-yellow-400 mb-6 drop-shadow-[0_0_25px_rgba(250,204,21,0.6)] animate-pulse" />
          <h2 className="text-6xl font-display font-black text-white mb-2 tracking-tighter text-glow">CLEARED!</h2>
          <p className="text-yellow-100 mb-8 font-mono text-lg">{difficulty.label} Complete</p>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="px-10 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(234,179,8,0.4)] hover:shadow-[0_0_30px_rgba(234,179,8,0.6)] transition-all"
          >
            Play Again
          </button>
        </div>
      )}

      {/* IN-GAME HUD */}
      <div className="absolute top-6 right-6 pointer-events-none flex flex-col items-end">
          <div className="font-display font-black text-5xl text-white drop-shadow-md tabular-nums tracking-tight">
              {status === GameStatus.Playing || status === GameStatus.Lost ? (gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00") : "0.00"}
              <span className="text-2xl text-slate-400 ml-1">s</span>
          </div>

          {/* Progress Bar (Only for Normal Mode) */}
          {!isEndless && (
            <div className="w-48 h-2 bg-slate-800 rounded-full mt-2 overflow-hidden border border-slate-700">
              <div 
                className="h-full transition-all duration-75 ease-linear"
                style={{ 
                  width: `${Math.min(100, (gameState.current.startTime ? (Date.now() - gameState.current.startTime) : 0) / WIN_TIME_MS * 100)}%`,
                  backgroundColor: difficulty.color,
                  boxShadow: `0 0 10px ${difficulty.color}`
                }}
              />
            </div>
          )}
      </div>

       <div className="absolute top-6 left-6 pointer-events-none">
          <div 
            className="px-4 py-2 rounded-sm bg-black/60 backdrop-blur-md border-l-4 text-sm font-bold text-white uppercase tracking-widest shadow-lg mb-2"
            style={{ borderColor: difficulty.color }}
          >
              {difficulty.label} {isEndless && <span className="text-blue-400 ml-1">(∞)</span>}
          </div>
          {bestTime > 0 && (
             <div className="flex items-center gap-1 text-xs text-yellow-500 font-mono bg-black/40 px-2 py-1 rounded">
                <Crown className="w-3 h-3" /> Best: {bestTime}s
             </div>
          )}
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS, WAVE_SPEED_Y } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle, ChevronsUp, Crown, Infinity as InfinityIcon, Volume2, VolumeX, XCircle } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
  isEndless?: boolean;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
  size: number;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate, isEndless = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [bestTime, setBestTime] = useState<number>(0);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Game State Refs
  const gameState = useRef({
    playerY: 200,
    playerX: 100, 
    velocityY: 0,
    rotation: 0, // In radians
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    lastFrameTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0,
    bgOffset: 0,
    shakeIntensity: 0,
    deathCoords: { x: 0, y: 0 } // Store exact death location
  });

  const requestRef = useRef<number>();

  // Initialize Audio Context
  const initAudio = useCallback(() => {
    if (!audioCtxRef.current) {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContext) {
        audioCtxRef.current = new AudioContext();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  }, []);

  const playSound = useCallback((type: 'crash' | 'win') => {
    if (isMuted || !audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    const now = ctx.currentTime;

    if (type === 'crash') {
      // Noise/Sawtooth crash
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(100, now);
      osc.frequency.exponentialRampToValueAtTime(10, now + 0.3);

      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'win') {
      // Major chord
      [523.25, 659.25, 783.99].forEach((freq, i) => { // C Major
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;

        const startTime = now + (i * 0.1);
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(0.1, startTime + 0.1);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + 0.8);

        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + 0.8);
      });
    }
  }, [isMuted]);

  // Load best time on mount or difficulty/mode change
  useEffect(() => {
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const savedBest = localStorage.getItem(storageKey);
    setBestTime(savedBest ? parseFloat(savedBest) : 0);
  }, [difficulty.id, isEndless]);

  const saveBestTime = (timeMs: number) => {
    const timeSec = timeMs / 1000;
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const currentBest = parseFloat(localStorage.getItem(storageKey) || '0');

    // For normal mode, cap at 15s (victory). For endless, sky is the limit.
    const effectiveTime = (!isEndless && timeSec > 15) ? 15 : timeSec;

    if (effectiveTime > currentBest) {
      localStorage.setItem(storageKey, effectiveTime.toFixed(2));
      setBestTime(effectiveTime);
    }
  };

  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 20;
    const spawnDistance = 250; 

    const lastObs = gameState.current.obstacles[gameState.current.obstacles.length - 1];

    let minTopLimit = minWall;
    let maxTopLimit = canvasHeight - difficulty.gap - minWall;

    if (lastObs) {
        const framesToReach = spawnDistance / difficulty.speed;
        const maxVerticalTravel = (framesToReach * WAVE_SPEED_Y) * 0.85;
        const prevTop = lastObs.topHeight;
        minTopLimit = Math.max(minWall, prevTop - maxVerticalTravel);
        maxTopLimit = Math.min(canvasHeight - difficulty.gap - minWall, prevTop + maxVerticalTravel);
    }

    if (minTopLimit > maxTopLimit) {
        const avg = (minTopLimit + maxTopLimit) / 2;
        minTopLimit = avg;
        maxTopLimit = avg;
    }

    const topHeight = Math.random() * (maxTopLimit - minTopLimit) + minTopLimit;

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), 
      topHeight: topHeight,
      bottomY: topHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      rotation: 0,
      isHolding: false,
      obstacles: [],
      particles: [],
      trail: [],
      startTime: 0,
      lastFrameTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0,
      bgOffset: 0,
      shakeIntensity: 0,
      deathCoords: { x: 0, y: 0 }
    };

    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate]);

  const createExplosion = (x: number, y: number, color: string) => {
    gameState.current.shakeIntensity = 20;
    gameState.current.deathCoords = { x, y }; // Record death spot
    playSound('crash');

    for (let i = 0; i < 25; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 6 + 2;

      // Momentum: Add the horizontal speed of the level to particles to simulate forward inertia
      const forwardMomentum = difficulty.speed * 0.5;

      gameState.current.particles.push({
        x,
        y,
        vx: (Math.cos(angle) * speed) + forwardMomentum, // Add forward momentum
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color,
        size: Math.random() * 6 + 2
      });
    }
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    // Win Condition (Only for Normal Mode)
    if (!isEndless && elapsed >= WIN_TIME_MS) {
      saveBestTime(WIN_TIME_MS);
      playSound('win');
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    // Atmospheric Pulse (0.8 to 1.2 scale roughly over time)
    const pulseFactor = 1 + Math.sin(time / 200) * 0.1; 

    // Scroll Background Grid
    gameState.current.bgOffset -= difficulty.speed * 0.5; 
    if (gameState.current.bgOffset <= -50) gameState.current.bgOffset += 50;

    // Apply Screen Shake
    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9; 
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    // Clear Canvas
    ctx.fillStyle = '#020617'; 
    ctx.fillRect(0, 0, width, height);

    // Draw Moving Grid
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5 + (pulseFactor * 0.1); // Pulse opacity
    ctx.beginPath();
    for(let x = gameState.current.bgOffset; x < width; x += 50) { 
        if (x < 0) continue; 
        ctx.moveTo(x, 0); ctx.lineTo(x, height); 
    }
    for(let y = 0; y < height; y += 50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
    ctx.stroke();
    ctx.globalAlpha = 1.0;

    const waveSpeed = WAVE_SPEED_Y; 

    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    // Dynamic Rotation Calculation
    // Angle = atan(vertical_speed / horizontal_speed)
    // We want visually accurate slope. 
    // Holding = Moving Up (-Y), Not Holding = Moving Down (+Y)
    const slopeAngle = Math.atan2(WAVE_SPEED_Y, difficulty.speed);
    const targetRotation = gameState.current.isHolding ? -slopeAngle : slopeAngle;

    // Snappy interpolation
    gameState.current.rotation += (targetRotation - gameState.current.rotation) * 0.5;

    // Floor/Ceiling collision
    if (gameState.current.playerY < 0 || gameState.current.playerY > height) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
      saveBestTime(elapsed);
      onStatusChange(GameStatus.Lost);
      ctx.restore();
      return;
    }

    // Trail Logic
    gameState.current.trail.push({ x: gameState.current.playerX - 5, y: gameState.current.playerY });
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    const spawnDistance = 250; 
    if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
        spawnObstacle(width, height, width + 50);
    }

    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      // Hitbox
      const playerSize = 6;

      if (gameState.current.playerX + playerSize > obs.x && gameState.current.playerX - playerSize < obs.x + obs.width) {
        if (gameState.current.playerY - playerSize < obs.topHeight || gameState.current.playerY + playerSize > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
           saveBestTime(elapsed);
           onStatusChange(GameStatus.Lost);
           ctx.restore();
           return;
        }
      }

      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // Draw Floor/Ceiling lines with pulse
    ctx.shadowBlur = 10 * pulseFactor;
    ctx.shadowColor = difficulty.color;
    ctx.strokeStyle = difficulty.color;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(width, 0);
    ctx.moveTo(0, height); ctx.lineTo(width, height);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw Obstacles
    ctx.fillStyle = '#0f172a';
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 1;

    gameState.current.obstacles.forEach(obs => {
      // Top
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);

      // Bottom
      const bottomH = height - obs.bottomY;
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);

      // Neon Edges
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 2;

      ctx.beginPath();
      ctx.moveTo(obs.x, 0); ctx.lineTo(obs.x, obs.topHeight); ctx.lineTo(obs.x + obs.width, obs.topHeight); ctx.lineTo(obs.x + obs.width, 0);
      ctx.moveTo(obs.x, height); ctx.lineTo(obs.x, obs.bottomY); ctx.lineTo(obs.x + obs.width, obs.bottomY); ctx.lineTo(obs.x + obs.width, height);
      ctx.stroke();

      // Pulsing Glow inside
      ctx.fillStyle = difficulty.color;
      ctx.globalAlpha = 0.05 * pulseFactor;
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);
      ctx.globalAlpha = 1.0;
    });

    // Draw Trail
    if (gameState.current.trail.length > 1) {
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.shadowBlur = 10 * pulseFactor;
      ctx.shadowColor = difficulty.color;
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    // Draw Player
    ctx.save();
    ctx.translate(gameState.current.playerX, gameState.current.playerY);
    ctx.rotate(gameState.current.rotation);

    ctx.beginPath();
    ctx.moveTo(-6, -6);
    ctx.lineTo(8, 0);
    ctx.lineTo(-6, 6);
    ctx.closePath();

    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = difficulty.color;
    ctx.stroke();

    // Inner detail
    ctx.beginPath();
    ctx.moveTo(-2, -2);
    ctx.lineTo(2, 0);
    ctx.lineTo(-2, 2);
    ctx.closePath();
    ctx.fillStyle = difficulty.color;
    ctx.fill();

    ctx.restore(); // Restore from rotation
    ctx.restore(); // Restore from shake

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle, isEndless, playSound]);

  const particleLoop = useCallback((time: number) => {
    if (status === GameStatus.Playing) return; 

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    // Pulse in death screen too
    const pulseFactor = 1 + Math.sin(time / 200) * 0.1;

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9;
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<width; x+=50) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
        for(let y=0; y<height; y+=50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
        ctx.stroke();

        ctx.strokeStyle = difficulty.color;
        ctx.lineWidth = 1;
        gameState.current.obstacles.forEach(obs => {
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
        });

        // Draw Death Marker (X)
        if (status === GameStatus.Lost) {
          const { x, y } = gameState.current.deathCoords;
          ctx.strokeStyle = '#ef4444';
          ctx.lineWidth = 3;
          ctx.shadowColor = '#ef4444';
          ctx.shadowBlur = 15 * pulseFactor;

          const size = 10;
          ctx.beginPath();
          ctx.moveTo(x - size, y - size);
          ctx.lineTo(x + size, y + size);
          ctx.moveTo(x + size, y - size);
          ctx.lineTo(x - size, y + size);
          ctx.stroke();

          // Death Circle ring
          ctx.beginPath();
          ctx.arc(x, y, size * 2 * pulseFactor, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(239, 68, 68, ${0.5 * pulseFactor})`;
          ctx.stroke();
          ctx.shadowBlur = 0;
        }
    }

    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.02;
      p.vx *= 0.95; // Drag
      p.vy *= 0.95;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      // Draw Square Particles
      ctx.fillStyle = p.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.color;
      ctx.globalAlpha = p.life;
      ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
      ctx.globalAlpha = 1.0;
      ctx.shadowBlur = 0;
    }

    ctx.restore();

    if (gameState.current.particles.length > 0 || gameState.current.shakeIntensity > 0 || status === GameStatus.Lost) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status, difficulty]);

  const handleStart = () => { 
    initAudio();
    gameState.current.isHolding = true; 
  };
  const handleEnd = () => { gameState.current.isHolding = false; };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault(); 

        // Instant Restart Feature
        if (status === GameStatus.Lost) {
             resetGame();
             onStatusChange(GameStatus.Playing);
             return;
        }

        if (status === GameStatus.Idle) {
            initAudio();
        }

        gameState.current.isHolding = true;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault();
        gameState.current.isHolding = false;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [status, resetGame, onStatusChange, initAudio]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]);

  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              if (status === GameStatus.Idle) { resetGame(); }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div 
      className="relative w-full max-w-5xl aspect-video md:h-[500px] bg-slate-950 rounded-lg overflow-hidden transition-all duration-500 mx-auto select-none touch-none group" 
      ref={containerRef}
      style={{
        boxShadow: `0 0 30px ${difficulty.color}15, 0 0 0 1px ${difficulty.color}30`
      }}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer outline-none"
        onMouseDown={handleStart}
        onMouseUp={handleEnd}
        onMouseLeave={handleEnd}
        onTouchStart={(e) => { e.preventDefault(); handleStart(); }}
        onTouchEnd={(e) => { e.preventDefault(); handleEnd(); }}
      />

      {/* Decorative corners */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>

      {/* Mute Button */}
      <button 
        onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
        className="absolute bottom-4 right-4 z-20 p-2 bg-black/40 hover:bg-black/60 backdrop-blur rounded-full text-slate-400 hover:text-white transition-colors"
        title={isMuted ? "Unmute" : "Mute"}
      >
        {isMuted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
      </button>

      {/* START SCREEN */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 backdrop-blur-[2px] z-10 animate-in fade-in duration-300">
          <div className="text-center space-y-6 p-8 border border-white/10 bg-black/50 rounded-2xl shadow-2xl backdrop-blur-md max-w-md mx-4">
            <div>
              <h2 className="text-5xl font-display font-black text-white mb-2 tracking-tight" style={{ textShadow: `0 0 20px ${difficulty.color}` }}>
                {difficulty.label.toUpperCase()}
              </h2>
              <div className="h-1 w-24 mx-auto rounded-full" style={{ backgroundColor: difficulty.color, boxShadow: `0 0 10px ${difficulty.color}` }}></div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm font-mono text-slate-400 bg-black/30 p-4 rounded-lg">
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Goal</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                      {isEndless ? (
                        <>Endless <InfinityIcon className="w-3 h-3" /></>
                      ) : (
                        "15 Seconds"
                      )}
                    </span>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Best Time</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                        <Crown className="w-3 h-3 text-yellow-500" />
                        {bestTime > 0 ? `${bestTime}s` : '--'}
                    </span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-2 text-xs text-slate-500 uppercase tracking-widest mb-4">
              <ChevronsUp className="w-4 h-4 animate-bounce" /> Hold Space to Fly
            </div>

            <button
              onClick={() => { initAudio(); onStatusChange(GameStatus.Playing); }}
              className="group relative w-full py-4 bg-white text-black font-display font-black text-xl rounded hover:scale-[1.02] transition-transform overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
              START RUN
            </button>
          </div>
        </div>
      )}

      {/* GAME OVER SCREEN */}
      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-200">
          <div className="relative mb-4">
             <AlertTriangle className="w-20 h-20 text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
             <div className="absolute -bottom-2 -right-2 bg-red-600 rounded-full p-1 animate-ping"></div>
          </div>

          <h2 className="text-6xl font-display font-black text-white italic mb-2 tracking-tighter text-glow">CRASHED</h2>

          {isEndless ? (
             <div className="mb-8 flex flex-col items-center">
                <span className="text-red-200 font-mono text-sm uppercase tracking-widest mb-1">Time Survived</span>
                <span className="text-4xl font-mono font-bold text-white">
                  {(gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00")}s
                </span>
             </div>
          ) : (
             <p className="text-red-200 mb-4 font-mono text-lg">Attempt Failed</p>
          )}

          <div className="flex flex-col items-center gap-3">
             <button
                onClick={() => onStatusChange(GameStatus.Idle)}
                className="px-10 py-3 bg-red-600 hover:bg-red-500 text-white font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] transition-all"
             >
                Retry
             </button>
             <span className="text-xs text-red-300/60 font-mono uppercase tracking-widest flex items-center gap-2">
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div> 
                 Press Space to Restart
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div>
             </span>
          </div>
        </div>
      )}

      {/* WIN SCREEN */}
      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-yellow-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-500">
          <Trophy className="w-24 h-24 text-yellow-400 mb-6 drop-shadow-[0_0_25px_rgba(250,204,21,0.6)] animate-pulse" />
          <h2 className="text-6xl font-display font-black text-white mb-2 tracking-tighter text-glow">CLEARED!</h2>
          <p className="text-yellow-100 mb-8 font-mono text-lg">{difficulty.label} Complete</p>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="px-10 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(234,179,8,0.4)] hover:shadow-[0_0_30px_rgba(234,179,8,0.6)] transition-all"
          >
            Play Again
          </button>
        </div>
      )}

      {/* IN-GAME HUD */}
      <div className="absolute top-6 right-6 pointer-events-none flex flex-col items-end">
          <div className="font-display font-black text-5xl text-white drop-shadow-md tabular-nums tracking-tight">
              {status === GameStatus.Playing || status === GameStatus.Lost ? (gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00") : "0.00"}
              <span className="text-2xl text-slate-400 ml-1">s</span>
          </div>

          {/* Progress Bar (Only for Normal Mode) */}
          {!isEndless && (
            <div className="w-48 h-2 bg-slate-800 rounded-full mt-2 overflow-hidden border border-slate-700">
              <div 
                className="h-full transition-all duration-75 ease-linear"
                style={{ 
                  width: `${Math.min(100, (gameState.current.startTime ? (Date.now() - gameState.current.startTime) : 0) / WIN_TIME_MS * 100)}%`,
                  backgroundColor: difficulty.color,
                  boxShadow: `0 0 10px ${difficulty.color}`
                }}
              />
            </div>
          )}
      </div>

       <div className="absolute top-6 left-6 pointer-events-none">
          <div 
            className="px-4 py-2 rounded-sm bg-black/60 backdrop-blur-md border-l-4 text-sm font-bold text-white uppercase tracking-widest shadow-lg mb-2"
            style={{ borderColor: difficulty.color }}
          >
              {difficulty.label} {isEndless && <span className="text-blue-400 ml-1">(∞)</span>}
          </div>
          {bestTime > 0 && (
             <div className="flex items-center gap-1 text-xs text-yellow-500 font-mono bg-black/40 px-2 py-1 rounded">
                <Crown className="w-3 h-3" /> Best: {bestTime}s
             </div>
          )}
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS, WAVE_SPEED_Y } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle, ChevronsUp, Crown, Infinity as InfinityIcon, Volume2, VolumeX, XCircle } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
  isEndless?: boolean;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
  size: number;
}

interface ClickEffect {
  x: number;
  y: number;
  life: number;
  maxLife: number;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate, isEndless = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [bestTime, setBestTime] = useState<number>(0);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const inputState = useRef<boolean>(false); // Track physical input state independent of game loop

  // Game State Refs
  const gameState = useRef({
    playerY: 200,
    playerX: 100, 
    velocityY: 0,
    rotation: 0, // In radians
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    clickEffects: [] as ClickEffect[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0,
    bgOffset: 0,
    shakeIntensity: 0,
    deathCoords: { x: 0, y: 0 },
    hasBeatenBest: false // Track if we passed the best time in this run
  });

  const requestRef = useRef<number>();

  // Initialize Audio Context
  const initAudio = useCallback(() => {
    if (!audioCtxRef.current) {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContext) {
        audioCtxRef.current = new AudioContext();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  }, []);

  const playSound = useCallback((type: 'crash' | 'win' | 'newBest') => {
    if (isMuted || !audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    const now = ctx.currentTime;

    if (type === 'crash') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(100, now);
      osc.frequency.exponentialRampToValueAtTime(10, now + 0.3);
      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'win') {
      [523.25, 659.25, 783.99].forEach((freq, i) => { // C Major
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;
        const startTime = now + (i * 0.1);
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(0.1, startTime + 0.1);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + 0.8);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + 0.8);
      });
    } else if (type === 'newBest') {
      // High pitch sparkle
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.linearRampToValueAtTime(1760, now + 0.1);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.linearRampToValueAtTime(0, now + 0.2);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.2);
    }
  }, [isMuted]);

  // Load best time on mount or difficulty/mode change
  useEffect(() => {
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const savedBest = localStorage.getItem(storageKey);
    setBestTime(savedBest ? parseFloat(savedBest) : 0);
  }, [difficulty.id, isEndless]);

  const saveBestTime = (timeMs: number) => {
    const timeSec = timeMs / 1000;
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const currentBest = parseFloat(localStorage.getItem(storageKey) || '0');
    const effectiveTime = (!isEndless && timeSec > 15) ? 15 : timeSec;

    if (effectiveTime > currentBest) {
      localStorage.setItem(storageKey, effectiveTime.toFixed(2));
      setBestTime(effectiveTime);
    }
  };

  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 20;
    const spawnDistance = 250; 

    const lastObs = gameState.current.obstacles[gameState.current.obstacles.length - 1];

    let minTopLimit = minWall;
    let maxTopLimit = canvasHeight - difficulty.gap - minWall;

    if (lastObs) {
        const framesToReach = spawnDistance / difficulty.speed;
        const maxVerticalTravel = (framesToReach * WAVE_SPEED_Y) * 0.85;
        const prevTop = lastObs.topHeight;
        minTopLimit = Math.max(minWall, prevTop - maxVerticalTravel);
        maxTopLimit = Math.min(canvasHeight - difficulty.gap - minWall, prevTop + maxVerticalTravel);
    }

    if (minTopLimit > maxTopLimit) {
        const avg = (minTopLimit + maxTopLimit) / 2;
        minTopLimit = avg;
        maxTopLimit = avg;
    }

    const topHeight = Math.random() * (maxTopLimit - minTopLimit) + minTopLimit;

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), 
      topHeight: topHeight,
      bottomY: topHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      rotation: 0,
      // CRITICAL: Inherit the physical input state immediately so holding space restarts with upward momentum
      isHolding: inputState.current, 
      obstacles: [],
      particles: [],
      clickEffects: [],
      trail: [],
      startTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0,
      bgOffset: 0,
      shakeIntensity: 0,
      deathCoords: { x: 0, y: 0 },
      hasBeatenBest: false
    };

    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate]);

  const createExplosion = (x: number, y: number, color: string) => {
    gameState.current.shakeIntensity = 20;
    gameState.current.deathCoords = { x, y }; 
    playSound('crash');

    for (let i = 0; i < 25; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 6 + 2;
      // Momentum: Add horizontal speed
      const forwardMomentum = difficulty.speed * 0.5;

      gameState.current.particles.push({
        x,
        y,
        vx: (Math.cos(angle) * speed) + forwardMomentum, 
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color,
        size: Math.random() * 6 + 2
      });
    }
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    // Sync input state for this frame
    const wasHolding = gameState.current.isHolding;
    gameState.current.isHolding = inputState.current;

    // Detect Click/Release for Visual Effects
    if (wasHolding !== gameState.current.isHolding) {
       gameState.current.clickEffects.push({
           x: gameState.current.playerX,
           y: gameState.current.playerY,
           life: 1.0,
           maxLife: 15 // Frames
       });
    }

    // New Best Logic (Visual feedback during gameplay)
    if (bestTime > 0 && !gameState.current.hasBeatenBest) {
        const currentSec = elapsed / 1000;
        if (currentSec > bestTime) {
            gameState.current.hasBeatenBest = true;
            playSound('newBest');
        }
    }

    // Win Condition
    if (!isEndless && elapsed >= WIN_TIME_MS) {
      saveBestTime(WIN_TIME_MS);
      playSound('win');
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    const pulseFactor = 1 + Math.sin(time / 200) * 0.1; 

    // Background Scroll
    gameState.current.bgOffset -= difficulty.speed * 0.5; 
    if (gameState.current.bgOffset <= -50) gameState.current.bgOffset += 50;

    // Shake
    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9; 
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    // Clear
    ctx.fillStyle = '#020617'; 
    ctx.fillRect(0, 0, width, height);

    // Big Background Percentage
    ctx.save();
    ctx.font = '900 150px Orbitron, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = gameState.current.hasBeatenBest ? '#fbbf24' : '#1e293b'; // Gold if new best, else slate
    ctx.globalAlpha = 0.1;
    let percent = 0;
    if (isEndless) {
       percent = Math.floor(elapsed / 1000); // Seconds count for endless
    } else {
       percent = Math.min(100, Math.floor((elapsed / WIN_TIME_MS) * 100));
    }
    ctx.fillText(`${percent}${isEndless ? 's' : '%'}`, width / 2, height / 2);
    ctx.restore();

    // Grid
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5 + (pulseFactor * 0.1); 
    ctx.beginPath();
    for(let x = gameState.current.bgOffset; x < width; x += 50) { 
        if (x < 0) continue; 
        ctx.moveTo(x, 0); ctx.lineTo(x, height); 
    }
    for(let y = 0; y < height; y += 50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
    ctx.stroke();
    ctx.globalAlpha = 1.0;

    // Player Physics
    const waveSpeed = WAVE_SPEED_Y; 
    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    // Rotation
    const slopeAngle = Math.atan2(WAVE_SPEED_Y, difficulty.speed);
    const targetRotation = gameState.current.isHolding ? -slopeAngle : slopeAngle;
    gameState.current.rotation += (targetRotation - gameState.current.rotation) * 0.5;

    // Collision: Floor/Ceiling
    if (gameState.current.playerY < 0 || gameState.current.playerY > height) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
      saveBestTime(elapsed);
      onStatusChange(GameStatus.Lost);
      ctx.restore();
      return;
    }

    // Trail
    gameState.current.trail.push({ x: gameState.current.playerX - 5, y: gameState.current.playerY });
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    // Spawn Obstacles
    const spawnDistance = 250; 
    if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
        spawnObstacle(width, height, width + 50);
    }

    // Logic Loop
    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      // Hitbox
      const playerSize = 6;
      if (gameState.current.playerX + playerSize > obs.x && gameState.current.playerX - playerSize < obs.x + obs.width) {
        if (gameState.current.playerY - playerSize < obs.topHeight || gameState.current.playerY + playerSize > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
           saveBestTime(elapsed);
           onStatusChange(GameStatus.Lost);
           ctx.restore();
           return;
        }
      }

      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // Draw Obstacles
    ctx.strokeStyle = difficulty.color;
    ctx.lineWidth = 2;
    gameState.current.obstacles.forEach(obs => {
      // Top
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);

      // Bottom
      const bottomH = height - obs.bottomY;
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);

      // Edges
      ctx.beginPath();
      ctx.moveTo(obs.x, 0); ctx.lineTo(obs.x, obs.topHeight); ctx.lineTo(obs.x + obs.width, obs.topHeight); ctx.lineTo(obs.x + obs.width, 0);
      ctx.moveTo(obs.x, height); ctx.lineTo(obs.x, obs.bottomY); ctx.lineTo(obs.x + obs.width, obs.bottomY); ctx.lineTo(obs.x + obs.width, height);
      ctx.stroke();

      // Glow
      ctx.fillStyle = difficulty.color;
      ctx.globalAlpha = 0.05 * pulseFactor;
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, bottomH);
      ctx.globalAlpha = 1.0;
    });

    // Draw Floor/Ceiling lines
    ctx.shadowBlur = 10 * pulseFactor;
    ctx.shadowColor = difficulty.color;
    ctx.strokeStyle = difficulty.color;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(width, 0);
    ctx.moveTo(0, height); ctx.lineTo(width, height);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw Trail
    if (gameState.current.trail.length > 1) {
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.shadowBlur = 10 * pulseFactor;
      ctx.shadowColor = difficulty.color;
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    // Draw Click Effects (Ripple)
    for(let i = gameState.current.clickEffects.length - 1; i >= 0; i--) {
        const effect = gameState.current.clickEffects[i];
        effect.life -= 1;
        if(effect.life <= 0) {
            gameState.current.clickEffects.splice(i, 1);
            continue;
        }
        const progress = 1 - (effect.life / effect.maxLife); // 0 to 1
        ctx.beginPath();
        ctx.arc(effect.x, effect.y, 10 + (progress * 20), 0, Math.PI * 2);
        ctx.strokeStyle = difficulty.color;
        ctx.lineWidth = 2 * (1 - progress);
        ctx.stroke();
    }

    // Draw Player
    ctx.save();
    ctx.translate(gameState.current.playerX, gameState.current.playerY);
    ctx.rotate(gameState.current.rotation);

    ctx.beginPath();
    ctx.moveTo(-6, -6);
    ctx.lineTo(8, 0);
    ctx.lineTo(-6, 6);
    ctx.closePath();

    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = difficulty.color;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(-2, -2);
    ctx.lineTo(2, 0);
    ctx.lineTo(-2, 2);
    ctx.closePath();
    ctx.fillStyle = difficulty.color;
    ctx.fill();

    ctx.restore();
    ctx.restore(); // Restore shake

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle, isEndless, playSound, bestTime]);

  const particleLoop = useCallback((time: number) => {
    if (status === GameStatus.Playing) return; 

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    const pulseFactor = 1 + Math.sin(time / 200) * 0.1;

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9;
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<width; x+=50) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
        for(let y=0; y<height; y+=50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
        ctx.stroke();

        ctx.strokeStyle = difficulty.color;
        ctx.lineWidth = 1;
        gameState.current.obstacles.forEach(obs => {
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
        });

        // Death Marker
        if (status === GameStatus.Lost) {
          const { x, y } = gameState.current.deathCoords;
          ctx.strokeStyle = '#ef4444';
          ctx.lineWidth = 3;
          ctx.shadowColor = '#ef4444';
          ctx.shadowBlur = 15 * pulseFactor;

          const size = 10;
          ctx.beginPath();
          ctx.moveTo(x - size, y - size);
          ctx.lineTo(x + size, y + size);
          ctx.moveTo(x + size, y - size);
          ctx.lineTo(x - size, y + size);
          ctx.stroke();

          ctx.beginPath();
          ctx.arc(x, y, size * 2 * pulseFactor, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(239, 68, 68, ${0.5 * pulseFactor})`;
          ctx.stroke();
          ctx.shadowBlur = 0;
        }
    }

    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.02;
      p.vx *= 0.95; 
      p.vy *= 0.95;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      ctx.fillStyle = p.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.color;
      ctx.globalAlpha = p.life;
      ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
      ctx.globalAlpha = 1.0;
      ctx.shadowBlur = 0;
    }

    ctx.restore();

    if (gameState.current.particles.length > 0 || gameState.current.shakeIntensity > 0 || status === GameStatus.Lost) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status, difficulty]);

  // Input Handling
  useEffect(() => {
    const handleInputDown = (e: Event) => {
        // Only prevent default for game controls to avoid blocking UI clicks elsewhere if we expand
        if (e.type === 'keydown' && (e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        if (e.type === 'touchstart') e.preventDefault();

        inputState.current = true; // Set physical state

        // Instant Restart Check
        if (status === GameStatus.Lost) {
             resetGame();
             gameState.current.isHolding = true; // Force hold on new game
             onStatusChange(GameStatus.Playing);
             return;
        }

        // Start from Idle
        if (status === GameStatus.Idle) {
            initAudio();
            onStatusChange(GameStatus.Playing);
            gameState.current.isHolding = true;
        }
    };

    const handleInputUp = (e: Event) => {
        if (e.type === 'keyup' && (e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        inputState.current = false;
    };

    window.addEventListener('keydown', handleInputDown as any);
    window.addEventListener('keyup', handleInputUp as any);

    // Bind to canvas for mouse/touch to avoid global interference
    const canvas = canvasRef.current;
    if (canvas) {
        canvas.addEventListener('mousedown', handleInputDown);
        canvas.addEventListener('mouseup', handleInputUp);
        canvas.addEventListener('mouseleave', handleInputUp);
        canvas.addEventListener('touchstart', handleInputDown, { passive: false });
        canvas.addEventListener('touchend', handleInputUp);
    }

    return () => {
        window.removeEventListener('keydown', handleInputDown as any);
        window.removeEventListener('keyup', handleInputUp as any);
        if (canvas) {
            canvas.removeEventListener('mousedown', handleInputDown);
            canvas.removeEventListener('mouseup', handleInputUp);
            canvas.removeEventListener('mouseleave', handleInputUp);
            canvas.removeEventListener('touchstart', handleInputDown);
            canvas.removeEventListener('touchend', handleInputUp);
        }
    };
  }, [status, resetGame, onStatusChange, initAudio]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]);

  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              if (status === GameStatus.Idle) { resetGame(); }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div 
      className="relative w-full max-w-5xl aspect-video md:h-[500px] bg-slate-950 rounded-lg overflow-hidden transition-all duration-500 mx-auto select-none touch-none group" 
      ref={containerRef}
      style={{
        boxShadow: `0 0 30px ${difficulty.color}15, 0 0 0 1px ${difficulty.color}30`
      }}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer outline-none"
      />

      {/* Decorative corners */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>

      {/* Mute Button */}
      <button 
        onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
        className="absolute bottom-4 right-4 z-20 p-2 bg-black/40 hover:bg-black/60 backdrop-blur rounded-full text-slate-400 hover:text-white transition-colors"
        title={isMuted ? "Unmute" : "Mute"}
      >
        {isMuted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
      </button>

      {/* START SCREEN */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 backdrop-blur-[2px] z-10 animate-in fade-in duration-300 pointer-events-none">
          <div className="text-center space-y-6 p-8 border border-white/10 bg-black/50 rounded-2xl shadow-2xl backdrop-blur-md max-w-md mx-4 pointer-events-auto">
            <div>
              <h2 className="text-5xl font-display font-black text-white mb-2 tracking-tight" style={{ textShadow: `0 0 20px ${difficulty.color}` }}>
                {difficulty.label.toUpperCase()}
              </h2>
              <div className="h-1 w-24 mx-auto rounded-full" style={{ backgroundColor: difficulty.color, boxShadow: `0 0 10px ${difficulty.color}` }}></div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm font-mono text-slate-400 bg-black/30 p-4 rounded-lg">
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Goal</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                      {isEndless ? (
                        <>Endless <InfinityIcon className="w-3 h-3" /></>
                      ) : (
                        "15 Seconds"
                      )}
                    </span>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Best Time</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                        <Crown className="w-3 h-3 text-yellow-500" />
                        {bestTime > 0 ? `${bestTime}s` : '--'}
                    </span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-2 text-xs text-slate-500 uppercase tracking-widest mb-4">
              <ChevronsUp className="w-4 h-4 animate-bounce" /> Hold Space to Fly
            </div>

            <button
              onClick={() => { initAudio(); onStatusChange(GameStatus.Playing); }}
              className="group relative w-full py-4 bg-white text-black font-display font-black text-xl rounded hover:scale-[1.02] transition-transform overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
              START RUN
            </button>
          </div>
        </div>
      )}

      {/* GAME OVER SCREEN */}
      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-200 pointer-events-none">
          <div className="relative mb-4">
             <AlertTriangle className="w-20 h-20 text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
             <div className="absolute -bottom-2 -right-2 bg-red-600 rounded-full p-1 animate-ping"></div>
          </div>

          <h2 className="text-6xl font-display font-black text-white italic mb-2 tracking-tighter text-glow">CRASHED</h2>

          {isEndless ? (
             <div className="mb-8 flex flex-col items-center">
                <span className="text-red-200 font-mono text-sm uppercase tracking-widest mb-1">Time Survived</span>
                <span className="text-4xl font-mono font-bold text-white">
                  {(gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00")}s
                </span>
             </div>
          ) : (
             <p className="text-red-200 mb-4 font-mono text-lg">Attempt Failed</p>
          )}

          <div className="flex flex-col items-center gap-3 pointer-events-auto">
             <button
                onClick={() => onStatusChange(GameStatus.Idle)}
                className="px-10 py-3 bg-red-600 hover:bg-red-500 text-white font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] transition-all"
             >
                Retry
             </button>
             <span className="text-xs text-red-300/60 font-mono uppercase tracking-widest flex items-center gap-2">
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div> 
                 Press Space to Restart
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div>
             </span>
          </div>
        </div>
      )}

      {/* WIN SCREEN */}
      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-yellow-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-500 pointer-events-none">
          <Trophy className="w-24 h-24 text-yellow-400 mb-6 drop-shadow-[0_0_25px_rgba(250,204,21,0.6)] animate-pulse" />
          <h2 className="text-6xl font-display font-black text-white mb-2 tracking-tighter text-glow">CLEARED!</h2>
          <p className="text-yellow-100 mb-8 font-mono text-lg">{difficulty.label} Complete</p>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="pointer-events-auto px-10 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(234,179,8,0.4)] hover:shadow-[0_0_30px_rgba(234,179,8,0.6)] transition-all"
          >
            Play Again
          </button>
        </div>
      )}

      {/* IN-GAME HUD */}
      <div className="absolute top-6 right-6 pointer-events-none flex flex-col items-end">
          <div className="font-display font-black text-5xl text-white drop-shadow-md tabular-nums tracking-tight">
              {status === GameStatus.Playing || status === GameStatus.Lost ? (gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00") : "0.00"}
              <span className="text-2xl text-slate-400 ml-1">s</span>
          </div>

          {/* Progress Bar (Only for Normal Mode) */}
          {!isEndless && (
            <div className="w-48 h-2 bg-slate-800 rounded-full mt-2 overflow-hidden border border-slate-700">
              <div 
                className="h-full transition-all duration-75 ease-linear"
                style={{ 
                  width: `${Math.min(100, (gameState.current.startTime ? (Date.now() - gameState.current.startTime) : 0) / WIN_TIME_MS * 100)}%`,
                  backgroundColor: difficulty.color,
                  boxShadow: `0 0 10px ${difficulty.color}`
                }}
              />
            </div>
          )}
      </div>

       <div className="absolute top-6 left-6 pointer-events-none">
          <div 
            className="px-4 py-2 rounded-sm bg-black/60 backdrop-blur-md border-l-4 text-sm font-bold text-white uppercase tracking-widest shadow-lg mb-2"
            style={{ borderColor: difficulty.color }}
          >
              {difficulty.label} {isEndless && <span className="text-blue-400 ml-1">(∞)</span>}
          </div>
          {bestTime > 0 && (
             <div className="flex items-center gap-1 text-xs text-yellow-500 font-mono bg-black/40 px-2 py-1 rounded">
                <Crown className="w-3 h-3" /> Best: {bestTime}s
             </div>
          )}
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS, WAVE_SPEED_Y } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle, ChevronsUp, Crown, Infinity as InfinityIcon, Volume2, VolumeX, XCircle, MousePointer2, Eye, EyeOff, Activity } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
  isEndless?: boolean;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
  size: number;
}

interface ClickEffect {
  x: number;
  y: number;
  life: number;
  maxLife: number;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate, isEndless = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [bestTime, setBestTime] = useState<number>(0);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const [clickSoundEnabled, setClickSoundEnabled] = useState<boolean>(true);
  const [showHitbox, setShowHitbox] = useState<boolean>(false);
  const [fps, setFps] = useState<number>(60);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const inputState = useRef<boolean>(false); // Track physical input state independent of game loop

  // Game State Refs
  const gameState = useRef({
    playerY: 200,
    playerX: 100, 
    velocityY: 0,
    rotation: 0, // In radians
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    clickEffects: [] as ClickEffect[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0,
    bgOffset: 0,
    shakeIntensity: 0,
    deathCoords: { x: 0, y: 0 },
    hasBeatenBest: false,
    frameCount: 0,
    lastFpsTime: 0
  });

  const requestRef = useRef<number>();

  // Initialize Audio Context
  const initAudio = useCallback(() => {
    if (!audioCtxRef.current) {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContext) {
        audioCtxRef.current = new AudioContext();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  }, []);

  const playSound = useCallback((type: 'crash' | 'win' | 'newBest' | 'click') => {
    if (isMuted || !audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    const now = ctx.currentTime;

    if (type === 'crash') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(100, now);
      osc.frequency.exponentialRampToValueAtTime(10, now + 0.3);
      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'win') {
      [523.25, 659.25, 783.99].forEach((freq, i) => { // C Major
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;
        const startTime = now + (i * 0.1);
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(0.1, startTime + 0.1);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + 0.8);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + 0.8);
      });
    } else if (type === 'newBest') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.linearRampToValueAtTime(1760, now + 0.1);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.linearRampToValueAtTime(0, now + 0.2);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.2);
    } else if (type === 'click' && clickSoundEnabled) {
      // Crisp mechanical click
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      // High frequency burst for "click" transient
      osc.frequency.setValueAtTime(1200, now);
      osc.frequency.exponentialRampToValueAtTime(600, now + 0.05);

      gain.gain.setValueAtTime(0.08, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);

      osc.type = 'square'; // Square wave gives it that "switch" feel
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.05);
    }
  }, [isMuted, clickSoundEnabled]);

  // Load best time on mount or difficulty/mode change
  useEffect(() => {
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const savedBest = localStorage.getItem(storageKey);
    setBestTime(savedBest ? parseFloat(savedBest) : 0);
  }, [difficulty.id, isEndless]);

  const saveBestTime = (timeMs: number) => {
    const timeSec = timeMs / 1000;
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const currentBest = parseFloat(localStorage.getItem(storageKey) || '0');
    const effectiveTime = (!isEndless && timeSec > 15) ? 15 : timeSec;

    if (effectiveTime > currentBest) {
      localStorage.setItem(storageKey, effectiveTime.toFixed(2));
      setBestTime(effectiveTime);
    }
  };

  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 20;
    const spawnDistance = 250; 

    const lastObs = gameState.current.obstacles[gameState.current.obstacles.length - 1];

    let minTopLimit = minWall;
    let maxTopLimit = canvasHeight - difficulty.gap - minWall;

    if (lastObs) {
        const framesToReach = spawnDistance / difficulty.speed;
        const maxVerticalTravel = (framesToReach * WAVE_SPEED_Y) * 0.85;
        const prevTop = lastObs.topHeight;
        minTopLimit = Math.max(minWall, prevTop - maxVerticalTravel);
        maxTopLimit = Math.min(canvasHeight - difficulty.gap - minWall, prevTop + maxVerticalTravel);
    }

    if (minTopLimit > maxTopLimit) {
        const avg = (minTopLimit + maxTopLimit) / 2;
        minTopLimit = avg;
        maxTopLimit = avg;
    }

    const topHeight = Math.random() * (maxTopLimit - minTopLimit) + minTopLimit;

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), 
      topHeight: topHeight,
      bottomY: topHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      rotation: 0,
      isHolding: inputState.current, 
      obstacles: [],
      particles: [],
      clickEffects: [],
      trail: [],
      startTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0,
      bgOffset: 0,
      shakeIntensity: 0,
      deathCoords: { x: 0, y: 0 },
      hasBeatenBest: false,
      frameCount: 0,
      lastFpsTime: performance.now()
    };

    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate]);

  const createExplosion = (x: number, y: number, color: string) => {
    gameState.current.shakeIntensity = 20;
    gameState.current.deathCoords = { x, y }; 
    playSound('crash');

    for (let i = 0; i < 25; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 6 + 2;
      const forwardMomentum = difficulty.speed * 0.5;

      gameState.current.particles.push({
        x,
        y,
        vx: (Math.cos(angle) * speed) + forwardMomentum, 
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color,
        size: Math.random() * 6 + 2
      });
    }
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // FPS Counter
    gameState.current.frameCount++;
    if (time - gameState.current.lastFpsTime >= 1000) {
        setFps(Math.round((gameState.current.frameCount * 1000) / (time - gameState.current.lastFpsTime)));
        gameState.current.frameCount = 0;
        gameState.current.lastFpsTime = time;
    }

    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    const wasHolding = gameState.current.isHolding;
    gameState.current.isHolding = inputState.current;

    if (wasHolding !== gameState.current.isHolding) {
       // Play click sound on press
       if (gameState.current.isHolding) {
           playSound('click');
       }

       gameState.current.clickEffects.push({
           x: gameState.current.playerX,
           y: gameState.current.playerY,
           life: 1.0,
           maxLife: 15
       });
    }

    if (bestTime > 0 && !gameState.current.hasBeatenBest) {
        const currentSec = elapsed / 1000;
        if (currentSec > bestTime) {
            gameState.current.hasBeatenBest = true;
            playSound('newBest');
        }
    }

    if (!isEndless && elapsed >= WIN_TIME_MS) {
      saveBestTime(WIN_TIME_MS);
      playSound('win');
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    const pulseFactor = 1 + Math.sin(time / 200) * 0.1; 

    gameState.current.bgOffset -= difficulty.speed * 0.5; 
    if (gameState.current.bgOffset <= -50) gameState.current.bgOffset += 50;

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9; 
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    ctx.fillStyle = '#020617'; 
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    ctx.font = '900 150px Orbitron, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = gameState.current.hasBeatenBest ? '#fbbf24' : '#1e293b'; 
    ctx.globalAlpha = 0.1;
    let percent = 0;
    if (isEndless) {
       percent = Math.floor(elapsed / 1000); 
    } else {
       percent = Math.min(100, Math.floor((elapsed / WIN_TIME_MS) * 100));
    }
    ctx.fillText(`${percent}${isEndless ? 's' : '%'}`, width / 2, height / 2);
    ctx.restore();

    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5 + (pulseFactor * 0.1); 
    ctx.beginPath();
    for(let x = gameState.current.bgOffset; x < width; x += 50) { 
        if (x < 0) continue; 
        ctx.moveTo(x, 0); ctx.lineTo(x, height); 
    }
    for(let y = 0; y < height; y += 50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
    ctx.stroke();
    ctx.globalAlpha = 1.0;

    const waveSpeed = WAVE_SPEED_Y; 
    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    const slopeAngle = Math.atan2(WAVE_SPEED_Y, difficulty.speed);
    const targetRotation = gameState.current.isHolding ? -slopeAngle : slopeAngle;
    gameState.current.rotation += (targetRotation - gameState.current.rotation) * 0.5;

    // Use tighter collision radius for gameplay feel (3px instead of 6)
    const collisionRadius = 3;

    if (gameState.current.playerY < collisionRadius || gameState.current.playerY > height - collisionRadius) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
      saveBestTime(elapsed);
      onStatusChange(GameStatus.Lost);
      ctx.restore();
      return;
    }

    gameState.current.trail.push({ x: gameState.current.playerX - 5, y: gameState.current.playerY });
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    const spawnDistance = 250; 
    if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
        spawnObstacle(width, height, width + 50);
    }

    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      // Precision Hitbox Check
      if (gameState.current.playerX + collisionRadius > obs.x && gameState.current.playerX - collisionRadius < obs.x + obs.width) {
        if (gameState.current.playerY - collisionRadius < obs.topHeight || gameState.current.playerY + collisionRadius > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, difficulty.color);
           saveBestTime(elapsed);
           onStatusChange(GameStatus.Lost);
           ctx.restore();
           return;
        }
      }

      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // Draw Obstacles with Sawteeth
    const sawSize = 20; 
    const sawHeight = 6; 

    gameState.current.obstacles.forEach(obs => {
      // Main blocks
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);

      // Edges with Sawteeth visuals
      ctx.fillStyle = difficulty.color;

      // Top Block Teeth (pointing down)
      ctx.beginPath();
      const startSaw = Math.floor(Math.max(0, -obs.x) / sawSize) * sawSize; // Optimization: don't draw offscreen
      for(let sx = startSaw; sx < obs.width; sx += sawSize) {
          const px = obs.x + sx;
          if (px > width) break;
          ctx.moveTo(px, obs.topHeight);
          ctx.lineTo(px + sawSize/2, obs.topHeight + sawHeight);
          ctx.lineTo(px + sawSize, obs.topHeight);
      }
      ctx.fill();

      // Bottom Block Teeth (pointing up)
      ctx.beginPath();
      for(let sx = startSaw; sx < obs.width; sx += sawSize) {
          const px = obs.x + sx;
          if (px > width) break;
          ctx.moveTo(px, obs.bottomY);
          ctx.lineTo(px + sawSize/2, obs.bottomY - sawHeight);
          ctx.lineTo(px + sawSize, obs.bottomY);
      }
      ctx.fill();

      // Neon lines on the actual collision surface
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(obs.x, obs.topHeight); ctx.lineTo(obs.x + obs.width, obs.topHeight);
      ctx.moveTo(obs.x, obs.bottomY); ctx.lineTo(obs.x + obs.width, obs.bottomY);
      ctx.stroke();

      // Glow
      ctx.fillStyle = difficulty.color;
      ctx.globalAlpha = 0.05 * pulseFactor;
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
      ctx.globalAlpha = 1.0;

      // Debug Hitbox View
      if (showHitbox) {
          ctx.strokeStyle = '#ef4444';
          ctx.lineWidth = 1;
          ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
          ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
      }
    });

    ctx.shadowBlur = 10 * pulseFactor;
    ctx.shadowColor = difficulty.color;
    ctx.strokeStyle = difficulty.color;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(width, 0);
    ctx.moveTo(0, height); ctx.lineTo(width, height);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw Trail with additive blending for neon look
    if (gameState.current.trail.length > 1) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter'; // Additive blending
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = difficulty.color;
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.shadowBlur = 15;
      ctx.shadowColor = difficulty.color;
      ctx.stroke();
      ctx.restore();
    }

    for(let i = gameState.current.clickEffects.length - 1; i >= 0; i--) {
        const effect = gameState.current.clickEffects[i];
        effect.life -= 1;
        if(effect.life <= 0) {
            gameState.current.clickEffects.splice(i, 1);
            continue;
        }
        const progress = 1 - (effect.life / effect.maxLife); 
        ctx.beginPath();
        ctx.arc(effect.x, effect.y, 10 + (progress * 20), 0, Math.PI * 2);
        ctx.strokeStyle = difficulty.color;
        ctx.lineWidth = 2 * (1 - progress);
        ctx.stroke();
    }

    // Draw Player
    ctx.save();
    ctx.translate(gameState.current.playerX, gameState.current.playerY);
    ctx.rotate(gameState.current.rotation);

    ctx.beginPath();
    ctx.moveTo(-6, -6);
    ctx.lineTo(8, 0);
    ctx.lineTo(-6, 6);
    ctx.closePath();

    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = difficulty.color;
    ctx.stroke();

    // Inner detail
    ctx.beginPath();
    ctx.moveTo(-2, -2);
    ctx.lineTo(2, 0);
    ctx.lineTo(-2, 2);
    ctx.closePath();
    ctx.fillStyle = difficulty.color;
    ctx.fill();

    // Hitbox Debug
    if (showHitbox) {
        ctx.beginPath();
        ctx.arc(0, 0, collisionRadius, 0, Math.PI * 2);
        ctx.fillStyle = '#ef4444';
        ctx.fill();
    }

    ctx.restore();
    ctx.restore(); 

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle, isEndless, playSound, bestTime, showHitbox, clickSoundEnabled]);

  const particleLoop = useCallback((time: number) => {
    if (status === GameStatus.Playing) return; 

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    const pulseFactor = 1 + Math.sin(time / 200) * 0.1;

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9;
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<width; x+=50) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
        for(let y=0; y<height; y+=50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
        ctx.stroke();

        ctx.strokeStyle = difficulty.color;
        ctx.lineWidth = 1;
        gameState.current.obstacles.forEach(obs => {
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
        });

        if (status === GameStatus.Lost) {
          const { x, y } = gameState.current.deathCoords;
          ctx.strokeStyle = '#ef4444';
          ctx.lineWidth = 3;
          ctx.shadowColor = '#ef4444';
          ctx.shadowBlur = 15 * pulseFactor;

          const size = 10;
          ctx.beginPath();
          ctx.moveTo(x - size, y - size);
          ctx.lineTo(x + size, y + size);
          ctx.moveTo(x + size, y - size);
          ctx.lineTo(x - size, y + size);
          ctx.stroke();

          ctx.beginPath();
          ctx.arc(x, y, size * 2 * pulseFactor, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(239, 68, 68, ${0.5 * pulseFactor})`;
          ctx.stroke();
          ctx.shadowBlur = 0;
        }
    }

    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.02;
      p.vx *= 0.95; 
      p.vy *= 0.95;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      ctx.fillStyle = p.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.color;
      ctx.globalAlpha = p.life;
      ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
      ctx.globalAlpha = 1.0;
      ctx.shadowBlur = 0;
    }

    ctx.restore();

    if (gameState.current.particles.length > 0 || gameState.current.shakeIntensity > 0 || status === GameStatus.Lost) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status, difficulty]);

  // Input Handling
  useEffect(() => {
    const handleInputDown = (e: Event) => {
        // Toggle handlers for debug should not trigger game input
        if (e.target instanceof HTMLButtonElement) return;

        if (e.type === 'keydown') {
             // Debug Hotkeys
             if ((e as KeyboardEvent).code === 'KeyH') {
                 setShowHitbox(prev => !prev);
                 return;
             }
             if ((e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        }
        if (e.type === 'touchstart') e.preventDefault();

        inputState.current = true; 

        if (status === GameStatus.Lost) {
             resetGame();
             gameState.current.isHolding = true; 
             onStatusChange(GameStatus.Playing);
             return;
        }

        if (status === GameStatus.Idle) {
            initAudio();
            onStatusChange(GameStatus.Playing);
            gameState.current.isHolding = true;
        }
    };

    const handleInputUp = (e: Event) => {
        if (e.type === 'keyup' && (e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        inputState.current = false;
    };

    window.addEventListener('keydown', handleInputDown as any);
    window.addEventListener('keyup', handleInputUp as any);

    const canvas = canvasRef.current;
    if (canvas) {
        canvas.addEventListener('mousedown', handleInputDown);
        canvas.addEventListener('mouseup', handleInputUp);
        canvas.addEventListener('mouseleave', handleInputUp);
        canvas.addEventListener('touchstart', handleInputDown, { passive: false });
        canvas.addEventListener('touchend', handleInputUp);
    }

    return () => {
        window.removeEventListener('keydown', handleInputDown as any);
        window.removeEventListener('keyup', handleInputUp as any);
        if (canvas) {
            canvas.removeEventListener('mousedown', handleInputDown);
            canvas.removeEventListener('mouseup', handleInputUp);
            canvas.removeEventListener('mouseleave', handleInputUp);
            canvas.removeEventListener('touchstart', handleInputDown);
            canvas.removeEventListener('touchend', handleInputUp);
        }
    };
  }, [status, resetGame, onStatusChange, initAudio]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]);

  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              if (status === GameStatus.Idle) { resetGame(); }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div 
      className="relative w-full max-w-5xl aspect-video md:h-[500px] bg-slate-950 rounded-lg overflow-hidden transition-all duration-500 mx-auto select-none touch-none group" 
      ref={containerRef}
      style={{
        boxShadow: `0 0 30px ${difficulty.color}15, 0 0 0 1px ${difficulty.color}30`
      }}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer outline-none"
      />

      {/* Decorative corners */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: difficulty.color }}></div>

      {/* Control Toolbar */}
      <div className="absolute bottom-4 right-4 z-20 flex items-center gap-2">
         {/* FPS Counter (Only visible when Playing) */}
         {status === GameStatus.Playing && (
             <div className="px-2 py-1 bg-black/40 backdrop-blur rounded text-[10px] font-mono text-slate-400 border border-white/5 flex items-center gap-1">
                 <Activity className="w-3 h-3" /> {fps} FPS
             </div>
         )}

         <div className="h-6 w-px bg-white/10 mx-1"></div>

         {/* Hitbox Toggle */}
         <button 
            onClick={(e) => { e.stopPropagation(); setShowHitbox(!showHitbox); }}
            className={`p-2 backdrop-blur rounded-full transition-colors ${showHitbox ? 'bg-red-500/20 text-red-400' : 'bg-black/40 text-slate-400 hover:text-white'}`}
            title="Toggle Hitbox (H)"
         >
            {showHitbox ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
         </button>

         {/* Click Sound Toggle */}
         <button 
            onClick={(e) => { e.stopPropagation(); setClickSoundEnabled(!clickSoundEnabled); }}
            className={`p-2 backdrop-blur rounded-full transition-colors ${clickSoundEnabled ? 'bg-blue-500/20 text-blue-400' : 'bg-black/40 text-slate-400 hover:text-white'}`}
            title="Click Sound FX"
         >
            <MousePointer2 className="w-4 h-4" />
         </button>

         {/* Master Mute */}
         <button 
            onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
            className="p-2 bg-black/40 hover:bg-black/60 backdrop-blur rounded-full text-slate-400 hover:text-white transition-colors"
            title={isMuted ? "Unmute Master" : "Mute Master"}
         >
            {isMuted ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
         </button>
      </div>

      {/* START SCREEN */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 backdrop-blur-[2px] z-10 animate-in fade-in duration-300 pointer-events-none">
          <div className="text-center space-y-6 p-8 border border-white/10 bg-black/50 rounded-2xl shadow-2xl backdrop-blur-md max-w-md mx-4 pointer-events-auto">
            <div>
              <h2 className="text-5xl font-display font-black text-white mb-2 tracking-tight" style={{ textShadow: `0 0 20px ${difficulty.color}` }}>
                {difficulty.label.toUpperCase()}
              </h2>
              <div className="h-1 w-24 mx-auto rounded-full" style={{ backgroundColor: difficulty.color, boxShadow: `0 0 10px ${difficulty.color}` }}></div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm font-mono text-slate-400 bg-black/30 p-4 rounded-lg">
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Goal</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                      {isEndless ? (
                        <>Endless <InfinityIcon className="w-3 h-3" /></>
                      ) : (
                        "15 Seconds"
                      )}
                    </span>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Best Time</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                        <Crown className="w-3 h-3 text-yellow-500" />
                        {bestTime > 0 ? `${bestTime}s` : '--'}
                    </span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-2 text-xs text-slate-500 uppercase tracking-widest mb-4">
              <ChevronsUp className="w-4 h-4 animate-bounce" /> Hold Space to Fly
            </div>

            <button
              onClick={() => { initAudio(); onStatusChange(GameStatus.Playing); }}
              className="group relative w-full py-4 bg-white text-black font-display font-black text-xl rounded hover:scale-[1.02] transition-transform overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
              START RUN
            </button>
          </div>
        </div>
      )}

      {/* GAME OVER SCREEN */}
      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-200 pointer-events-none">
          <div className="relative mb-4">
             <AlertTriangle className="w-20 h-20 text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
             <div className="absolute -bottom-2 -right-2 bg-red-600 rounded-full p-1 animate-ping"></div>
          </div>

          <h2 className="text-6xl font-display font-black text-white italic mb-2 tracking-tighter text-glow">CRASHED</h2>

          {isEndless ? (
             <div className="mb-8 flex flex-col items-center">
                <span className="text-red-200 font-mono text-sm uppercase tracking-widest mb-1">Time Survived</span>
                <span className="text-4xl font-mono font-bold text-white">
                  {(gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00")}s
                </span>
             </div>
          ) : (
             <p className="text-red-200 mb-4 font-mono text-lg">Attempt Failed</p>
          )}

          <div className="flex flex-col items-center gap-3 pointer-events-auto">
             <button
                onClick={() => onStatusChange(GameStatus.Idle)}
                className="px-10 py-3 bg-red-600 hover:bg-red-500 text-white font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] transition-all"
             >
                Retry
             </button>
             <span className="text-xs text-red-300/60 font-mono uppercase tracking-widest flex items-center gap-2">
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div> 
                 Press Space to Restart
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div>
             </span>
          </div>
        </div>
      )}

      {/* WIN SCREEN */}
      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-yellow-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-500 pointer-events-none">
          <Trophy className="w-24 h-24 text-yellow-400 mb-6 drop-shadow-[0_0_25px_rgba(250,204,21,0.6)] animate-pulse" />
          <h2 className="text-6xl font-display font-black text-white mb-2 tracking-tighter text-glow">CLEARED!</h2>
          <p className="text-yellow-100 mb-8 font-mono text-lg">{difficulty.label} Complete</p>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="pointer-events-auto px-10 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(234,179,8,0.4)] hover:shadow-[0_0_30px_rgba(234,179,8,0.6)] transition-all"
          >
            Play Again
          </button>
        </div>
      )}

      {/* IN-GAME HUD */}
      <div className="absolute top-6 right-6 pointer-events-none flex flex-col items-end">
          <div className="font-display font-black text-5xl text-white drop-shadow-md tabular-nums tracking-tight">
              {status === GameStatus.Playing || status === GameStatus.Lost ? (gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00") : "0.00"}
              <span className="text-2xl text-slate-400 ml-1">s</span>
          </div>

          {/* Progress Bar (Only for Normal Mode) */}
          {!isEndless && (
            <div className="w-48 h-2 bg-slate-800 rounded-full mt-2 overflow-hidden border border-slate-700">
              <div 
                className="h-full transition-all duration-75 ease-linear"
                style={{ 
                  width: `${Math.min(100, (gameState.current.startTime ? (Date.now() - gameState.current.startTime) : 0) / WIN_TIME_MS * 100)}%`,
                  backgroundColor: difficulty.color,
                  boxShadow: `0 0 10px ${difficulty.color}`
                }}
              />
            </div>
          )}
      </div>

       <div className="absolute top-6 left-6 pointer-events-none">
          <div 
            className="px-4 py-2 rounded-sm bg-black/60 backdrop-blur-md border-l-4 text-sm font-bold text-white uppercase tracking-widest shadow-lg mb-2"
            style={{ borderColor: difficulty.color }}
          >
              {difficulty.label} {isEndless && <span className="text-blue-400 ml-1">(∞)</span>}
          </div>
          {bestTime > 0 && (
             <div className="flex items-center gap-1 text-xs text-yellow-500 font-mono bg-black/40 px-2 py-1 rounded">
                <Crown className="w-3 h-3" /> Best: {bestTime}s
             </div>
          )}
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS, WAVE_SPEED_Y } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle, ChevronsUp, Crown, Infinity as InfinityIcon, Volume2, VolumeX, XCircle, MousePointer2, Eye, EyeOff, Activity, Hash } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
  isEndless?: boolean;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
  size: number;
}

interface ClickEffect {
  x: number;
  y: number;
  life: number;
  maxLife: number;
}

type GenerationPattern = 'flat' | 'ascend' | 'descend' | 'random';

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate, isEndless = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [bestTime, setBestTime] = useState<number>(0);
  const [attempts, setAttempts] = useState<number>(1);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const [clickSoundEnabled, setClickSoundEnabled] = useState<boolean>(true);
  const [showHitbox, setShowHitbox] = useState<boolean>(false);
  const [fps, setFps] = useState<number>(60);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const inputState = useRef<boolean>(false); 

  // Game State Refs
  const gameState = useRef({
    playerY: 200,
    playerX: 100, 
    velocityY: 0,
    rotation: 0, 
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    clickEffects: [] as ClickEffect[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0,
    bgOffset: 0,
    shakeIntensity: 0,
    deathCoords: { x: 0, y: 0 },
    hasBeatenBest: false,
    frameCount: 0,
    lastFpsTime: 0,
    // Pattern Generation State
    pattern: 'flat' as GenerationPattern,
    patternCounter: 0,
    currentHue: 0, // For endless mode rainbow effect
    baseColor: difficulty.color // Store current effective color
  });

  const requestRef = useRef<number>();

  // Initialize Audio Context
  const initAudio = useCallback(() => {
    if (!audioCtxRef.current) {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContext) {
        audioCtxRef.current = new AudioContext();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  }, []);

  const playSound = useCallback((type: 'crash' | 'win' | 'newBest' | 'click') => {
    if (isMuted || !audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    const now = ctx.currentTime;

    if (type === 'crash') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(100, now);
      osc.frequency.exponentialRampToValueAtTime(10, now + 0.3);
      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'win') {
      [523.25, 659.25, 783.99].forEach((freq, i) => { 
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;
        const startTime = now + (i * 0.1);
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(0.1, startTime + 0.1);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + 0.8);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + 0.8);
      });
    } else if (type === 'newBest') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.linearRampToValueAtTime(1760, now + 0.1);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.linearRampToValueAtTime(0, now + 0.2);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.2);
    } else if (type === 'click' && clickSoundEnabled) {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.frequency.setValueAtTime(1200, now);
      osc.frequency.exponentialRampToValueAtTime(600, now + 0.05);
      gain.gain.setValueAtTime(0.08, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
      osc.type = 'square'; 
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.05);
    }
  }, [isMuted, clickSoundEnabled]);

  // Load best time & reset attempts on difficulty switch
  useEffect(() => {
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const savedBest = localStorage.getItem(storageKey);
    setBestTime(savedBest ? parseFloat(savedBest) : 0);
    setAttempts(1); // Reset attempts on difficulty change
    gameState.current.baseColor = difficulty.color;
  }, [difficulty.id, isEndless]);

  const saveBestTime = (timeMs: number) => {
    const timeSec = timeMs / 1000;
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const currentBest = parseFloat(localStorage.getItem(storageKey) || '0');
    const effectiveTime = (!isEndless && timeSec > 15) ? 15 : timeSec;

    if (effectiveTime > currentBest) {
      localStorage.setItem(storageKey, effectiveTime.toFixed(2));
      setBestTime(effectiveTime);
    }
  };

  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 20;
    const minGapCenter = minWall + difficulty.gap / 2;
    const maxGapCenter = canvasHeight - minWall - difficulty.gap / 2;

    // Pattern Management
    if (gameState.current.patternCounter <= 0) {
        // Pick new pattern
        // Weighting: Flat > Slopes > Random
        const rand = Math.random();
        if (rand < 0.4) gameState.current.pattern = 'flat';
        else if (rand < 0.7) gameState.current.pattern = Math.random() > 0.5 ? 'ascend' : 'descend';
        else gameState.current.pattern = 'random';

        // Duration: 5 to 15 blocks
        gameState.current.patternCounter = Math.floor(Math.random() * 10) + 5;
    }
    gameState.current.patternCounter--;

    const lastObs = gameState.current.obstacles[gameState.current.obstacles.length - 1];
    let targetTopHeight = 0;

    if (!lastObs) {
        // First obstacle: center it
        targetTopHeight = (canvasHeight - difficulty.gap) / 2;
    } else {
        const prevCenter = lastObs.topHeight + difficulty.gap / 2;
        let nextCenter = prevCenter;

        // Calculate max possible vertical change based on speed
        // If blocks are closer (higher speed), we can't move vertical center as fast relative to X
        // Actually, higher speed = blocks spawn further apart in time? No, spawn distance is fixed.
        // Let's use a safe step size for slopes.
        const slopeStep = WAVE_SPEED_Y * 5; // How much Y changes per block spawn

        switch(gameState.current.pattern) {
            case 'flat':
                // Ideally keep exact same height, but add tiny jitter for organic feel
                nextCenter = prevCenter + (Math.random() * 10 - 5);
                break;
            case 'ascend':
                // Move gap UP (y decreases)
                nextCenter = prevCenter - slopeStep;
                break;
            case 'descend':
                // Move gap DOWN (y increases)
                nextCenter = prevCenter + slopeStep;
                break;
            case 'random':
            default:
                // Random jump within limits
                nextCenter = prevCenter + (Math.random() * 200 - 100);
                break;
        }

        // Bounce off walls logic
        if (nextCenter < minGapCenter) {
             nextCenter = minGapCenter + (minGapCenter - nextCenter); // Bounce back down
             if (gameState.current.pattern === 'ascend') gameState.current.pattern = 'descend'; // Switch trend
        }
        if (nextCenter > maxGapCenter) {
             nextCenter = maxGapCenter - (nextCenter - maxGapCenter); // Bounce back up
             if (gameState.current.pattern === 'descend') gameState.current.pattern = 'ascend'; // Switch trend
        }

        targetTopHeight = nextCenter - difficulty.gap / 2;
    }

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), 
      topHeight: targetTopHeight,
      bottomY: targetTopHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    // Increment attempts if we were previously playing/lost
    setAttempts(prev => prev + 1);

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      rotation: 0,
      isHolding: inputState.current, 
      obstacles: [],
      particles: [],
      clickEffects: [],
      trail: [],
      startTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0,
      bgOffset: 0,
      shakeIntensity: 0,
      deathCoords: { x: 0, y: 0 },
      hasBeatenBest: false,
      frameCount: 0,
      lastFpsTime: performance.now(),
      pattern: 'flat',
      patternCounter: 0,
      currentHue: 0,
      baseColor: difficulty.color
    };

    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate, difficulty.color]);

  const createExplosion = (x: number, y: number, color: string) => {
    gameState.current.shakeIntensity = 20;
    gameState.current.deathCoords = { x, y }; 
    playSound('crash');

    for (let i = 0; i < 25; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 6 + 2;
      const forwardMomentum = difficulty.speed * 0.5;

      gameState.current.particles.push({
        x,
        y,
        vx: (Math.cos(angle) * speed) + forwardMomentum, 
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color,
        size: Math.random() * 6 + 2
      });
    }
  };

  const hslToHex = (h: number, s: number, l: number) => {
    l /= 100;
    const a = s * Math.min(l, 1 - l) / 100;
    const f = (n: number) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Endless Mode Rainbow Effect
    if (isEndless) {
       gameState.current.currentHue = (gameState.current.currentHue + 0.5) % 360;
       gameState.current.baseColor = hslToHex(gameState.current.currentHue, 80, 60);
    } else {
       gameState.current.baseColor = difficulty.color;
    }
    const currentColor = gameState.current.baseColor;

    // FPS Counter
    gameState.current.frameCount++;
    if (time - gameState.current.lastFpsTime >= 1000) {
        setFps(Math.round((gameState.current.frameCount * 1000) / (time - gameState.current.lastFpsTime)));
        gameState.current.frameCount = 0;
        gameState.current.lastFpsTime = time;
    }

    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    const wasHolding = gameState.current.isHolding;
    gameState.current.isHolding = inputState.current;

    if (wasHolding !== gameState.current.isHolding) {
       // Play click sound on press
       if (gameState.current.isHolding) {
           playSound('click');
       }

       gameState.current.clickEffects.push({
           x: gameState.current.playerX,
           y: gameState.current.playerY,
           life: 1.0,
           maxLife: 15
       });
    }

    if (bestTime > 0 && !gameState.current.hasBeatenBest) {
        const currentSec = elapsed / 1000;
        if (currentSec > bestTime) {
            gameState.current.hasBeatenBest = true;
            playSound('newBest');
        }
    }

    if (!isEndless && elapsed >= WIN_TIME_MS) {
      saveBestTime(WIN_TIME_MS);
      playSound('win');
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    const pulseFactor = 1 + Math.sin(time / 200) * 0.1; 

    gameState.current.bgOffset -= difficulty.speed * 0.5; 
    if (gameState.current.bgOffset <= -50) gameState.current.bgOffset += 50;

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9; 
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    ctx.fillStyle = '#020617'; 
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    ctx.font = '900 150px Orbitron, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = gameState.current.hasBeatenBest ? '#fbbf24' : '#1e293b'; 
    ctx.globalAlpha = 0.1;
    let percent = 0;
    if (isEndless) {
       percent = Math.floor(elapsed / 1000); 
    } else {
       percent = Math.min(100, Math.floor((elapsed / WIN_TIME_MS) * 100));
    }
    ctx.fillText(`${percent}${isEndless ? 's' : '%'}`, width / 2, height / 2);
    ctx.restore();

    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5 + (pulseFactor * 0.1); 
    ctx.beginPath();
    for(let x = gameState.current.bgOffset; x < width; x += 50) { 
        if (x < 0) continue; 
        ctx.moveTo(x, 0); ctx.lineTo(x, height); 
    }
    for(let y = 0; y < height; y += 50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
    ctx.stroke();
    ctx.globalAlpha = 1.0;

    const waveSpeed = WAVE_SPEED_Y; 
    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    const slopeAngle = Math.atan2(WAVE_SPEED_Y, difficulty.speed);
    const targetRotation = gameState.current.isHolding ? -slopeAngle : slopeAngle;
    gameState.current.rotation += (targetRotation - gameState.current.rotation) * 0.5;

    const collisionRadius = 3;

    if (gameState.current.playerY < collisionRadius || gameState.current.playerY > height - collisionRadius) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, currentColor);
      saveBestTime(elapsed);
      onStatusChange(GameStatus.Lost);
      ctx.restore();
      return;
    }

    gameState.current.trail.push({ x: gameState.current.playerX - 5, y: gameState.current.playerY });
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    const spawnDistance = 250; 
    if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
        spawnObstacle(width, height, width + 50);
    }

    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      // Precision Hitbox Check
      if (gameState.current.playerX + collisionRadius > obs.x && gameState.current.playerX - collisionRadius < obs.x + obs.width) {
        if (gameState.current.playerY - collisionRadius < obs.topHeight || gameState.current.playerY + collisionRadius > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, currentColor);
           saveBestTime(elapsed);
           onStatusChange(GameStatus.Lost);
           ctx.restore();
           return;
        }
      }

      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // Draw Obstacles with Sawteeth
    const sawSize = 20; 
    const sawHeight = 6; 

    gameState.current.obstacles.forEach(obs => {
      // Main blocks
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);

      // Edges with Sawteeth visuals
      ctx.fillStyle = currentColor;

      // Top Block Teeth (pointing down)
      ctx.beginPath();
      const startSaw = Math.floor(Math.max(0, -obs.x) / sawSize) * sawSize; 
      for(let sx = startSaw; sx < obs.width; sx += sawSize) {
          const px = obs.x + sx;
          if (px > width) break;
          ctx.moveTo(px, obs.topHeight);
          ctx.lineTo(px + sawSize/2, obs.topHeight + sawHeight);
          ctx.lineTo(px + sawSize, obs.topHeight);
      }
      ctx.fill();

      // Bottom Block Teeth (pointing up)
      ctx.beginPath();
      for(let sx = startSaw; sx < obs.width; sx += sawSize) {
          const px = obs.x + sx;
          if (px > width) break;
          ctx.moveTo(px, obs.bottomY);
          ctx.lineTo(px + sawSize/2, obs.bottomY - sawHeight);
          ctx.lineTo(px + sawSize, obs.bottomY);
      }
      ctx.fill();

      // Neon lines on the actual collision surface
      ctx.strokeStyle = currentColor;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(obs.x, obs.topHeight); ctx.lineTo(obs.x + obs.width, obs.topHeight);
      ctx.moveTo(obs.x, obs.bottomY); ctx.lineTo(obs.x + obs.width, obs.bottomY);
      ctx.stroke();

      // Glow
      ctx.fillStyle = currentColor;
      ctx.globalAlpha = 0.05 * pulseFactor;
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
      ctx.globalAlpha = 1.0;

      // Debug Hitbox View
      if (showHitbox) {
          ctx.strokeStyle = '#ef4444';
          ctx.lineWidth = 1;
          ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
          ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
      }
    });

    ctx.shadowBlur = 10 * pulseFactor;
    ctx.shadowColor = currentColor;
    ctx.strokeStyle = currentColor;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(width, 0);
    ctx.moveTo(0, height); ctx.lineTo(width, height);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw Trail
    if (gameState.current.trail.length > 1) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter'; 
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = currentColor;
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.shadowBlur = 15;
      ctx.shadowColor = currentColor;
      ctx.stroke();
      ctx.restore();
    }

    for(let i = gameState.current.clickEffects.length - 1; i >= 0; i--) {
        const effect = gameState.current.clickEffects[i];
        effect.life -= 1;
        if(effect.life <= 0) {
            gameState.current.clickEffects.splice(i, 1);
            continue;
        }
        const progress = 1 - (effect.life / effect.maxLife); 
        ctx.beginPath();
        ctx.arc(effect.x, effect.y, 10 + (progress * 20), 0, Math.PI * 2);
        ctx.strokeStyle = currentColor;
        ctx.lineWidth = 2 * (1 - progress);
        ctx.stroke();
    }

    // Draw Player
    ctx.save();
    ctx.translate(gameState.current.playerX, gameState.current.playerY);
    ctx.rotate(gameState.current.rotation);

    ctx.beginPath();
    ctx.moveTo(-6, -6);
    ctx.lineTo(8, 0);
    ctx.lineTo(-6, 6);
    ctx.closePath();

    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = currentColor;
    ctx.stroke();

    // Inner detail
    ctx.beginPath();
    ctx.moveTo(-2, -2);
    ctx.lineTo(2, 0);
    ctx.lineTo(-2, 2);
    ctx.closePath();
    ctx.fillStyle = currentColor;
    ctx.fill();

    // Hitbox Debug
    if (showHitbox) {
        ctx.beginPath();
        ctx.arc(0, 0, collisionRadius, 0, Math.PI * 2);
        ctx.fillStyle = '#ef4444';
        ctx.fill();
    }

    ctx.restore();
    ctx.restore(); 

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle, isEndless, playSound, bestTime, showHitbox, clickSoundEnabled]);

  const particleLoop = useCallback((time: number) => {
    if (status === GameStatus.Playing) return; 

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    // Use stored baseColor so particles match the color you died at
    const currentColor = gameState.current.baseColor;
    const pulseFactor = 1 + Math.sin(time / 200) * 0.1;

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9;
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<width; x+=50) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
        for(let y=0; y<height; y+=50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
        ctx.stroke();

        ctx.strokeStyle = currentColor;
        ctx.lineWidth = 1;
        gameState.current.obstacles.forEach(obs => {
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
        });

        if (status === GameStatus.Lost) {
          const { x, y } = gameState.current.deathCoords;
          ctx.strokeStyle = '#ef4444';
          ctx.lineWidth = 3;
          ctx.shadowColor = '#ef4444';
          ctx.shadowBlur = 15 * pulseFactor;

          const size = 10;
          ctx.beginPath();
          ctx.moveTo(x - size, y - size);
          ctx.lineTo(x + size, y + size);
          ctx.moveTo(x + size, y - size);
          ctx.lineTo(x - size, y + size);
          ctx.stroke();

          ctx.beginPath();
          ctx.arc(x, y, size * 2 * pulseFactor, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(239, 68, 68, ${0.5 * pulseFactor})`;
          ctx.stroke();
          ctx.shadowBlur = 0;
        }
    }

    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.02;
      p.vx *= 0.95; 
      p.vy *= 0.95;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      ctx.fillStyle = p.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.color;
      ctx.globalAlpha = p.life;
      ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
      ctx.globalAlpha = 1.0;
      ctx.shadowBlur = 0;
    }

    ctx.restore();

    if (gameState.current.particles.length > 0 || gameState.current.shakeIntensity > 0 || status === GameStatus.Lost) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status, difficulty]);

  // Input Handling
  useEffect(() => {
    const handleInputDown = (e: Event) => {
        // Toggle handlers for debug should not trigger game input
        if (e.target instanceof HTMLButtonElement) return;

        if (e.type === 'keydown') {
             // Debug Hotkeys
             if ((e as KeyboardEvent).code === 'KeyH') {
                 setShowHitbox(prev => !prev);
                 return;
             }
             if ((e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        }
        if (e.type === 'touchstart') e.preventDefault();

        inputState.current = true; 

        if (status === GameStatus.Lost) {
             resetGame();
             gameState.current.isHolding = true; 
             onStatusChange(GameStatus.Playing);
             return;
        }

        if (status === GameStatus.Idle) {
            initAudio();
            onStatusChange(GameStatus.Playing);
            gameState.current.isHolding = true;
        }
    };

    const handleInputUp = (e: Event) => {
        if (e.type === 'keyup' && (e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        inputState.current = false;
    };

    window.addEventListener('keydown', handleInputDown as any);
    window.addEventListener('keyup', handleInputUp as any);

    const canvas = canvasRef.current;
    if (canvas) {
        canvas.addEventListener('mousedown', handleInputDown);
        canvas.addEventListener('mouseup', handleInputUp);
        canvas.addEventListener('mouseleave', handleInputUp);
        canvas.addEventListener('touchstart', handleInputDown, { passive: false });
        canvas.addEventListener('touchend', handleInputUp);
    }

    return () => {
        window.removeEventListener('keydown', handleInputDown as any);
        window.removeEventListener('keyup', handleInputUp as any);
        if (canvas) {
            canvas.removeEventListener('mousedown', handleInputDown);
            canvas.removeEventListener('mouseup', handleInputUp);
            canvas.removeEventListener('mouseleave', handleInputUp);
            canvas.removeEventListener('touchstart', handleInputDown);
            canvas.removeEventListener('touchend', handleInputUp);
        }
    };
  }, [status, resetGame, onStatusChange, initAudio]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]);

  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              if (status === GameStatus.Idle) { resetGame(); }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div 
      className="relative w-full max-w-5xl aspect-video md:h-[500px] bg-slate-950 rounded-lg overflow-hidden transition-all duration-500 mx-auto select-none touch-none group" 
      ref={containerRef}
      style={{
        boxShadow: `0 0 30px ${gameState.current.baseColor}15, 0 0 0 1px ${gameState.current.baseColor}30`
      }}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer outline-none"
      />

      {/* Decorative corners */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>

      {/* Control Toolbar */}
      <div className="absolute bottom-4 right-4 z-20 flex items-center gap-2">
         {/* Attempts Counter (Only visible when Playing) */}
         {status === GameStatus.Playing && (
             <div className="px-2 py-1 bg-black/40 backdrop-blur rounded text-[10px] font-mono text-slate-400 border border-white/5 flex items-center gap-1">
                 <Hash className="w-3 h-3" /> Att: {attempts}
             </div>
         )}

         <div className="h-6 w-px bg-white/10 mx-1"></div>

         {/* FPS Counter (Only visible when Playing) */}
         {status === GameStatus.Playing && (
             <div className="px-2 py-1 bg-black/40 backdrop-blur rounded text-[10px] font-mono text-slate-400 border border-white/5 flex items-center gap-1">
                 <Activity className="w-3 h-3" /> {fps} FPS
             </div>
         )}

         <div className="h-6 w-px bg-white/10 mx-1"></div>

         {/* Hitbox Toggle */}
         <button 
            onClick={(e) => { e.stopPropagation(); setShowHitbox(!showHitbox); }}
            className={`p-2 backdrop-blur rounded-full transition-colors ${showHitbox ? 'bg-red-500/20 text-red-400' : 'bg-black/40 text-slate-400 hover:text-white'}`}
            title="Toggle Hitbox (H)"
         >
            {showHitbox ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
         </button>

         {/* Click Sound Toggle */}
         <button 
            onClick={(e) => { e.stopPropagation(); setClickSoundEnabled(!clickSoundEnabled); }}
            className={`p-2 backdrop-blur rounded-full transition-colors ${clickSoundEnabled ? 'bg-blue-500/20 text-blue-400' : 'bg-black/40 text-slate-400 hover:text-white'}`}
            title="Click Sound FX"
         >
            <MousePointer2 className="w-4 h-4" />
         </button>

         {/* Master Mute */}
         <button 
            onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
            className="p-2 bg-black/40 hover:bg-black/60 backdrop-blur rounded-full text-slate-400 hover:text-white transition-colors"
            title={isMuted ? "Unmute Master" : "Mute Master"}
         >
            {isMuted ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
         </button>
      </div>

      {/* START SCREEN */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 backdrop-blur-[2px] z-10 animate-in fade-in duration-300 pointer-events-none">
          <div className="text-center space-y-6 p-8 border border-white/10 bg-black/50 rounded-2xl shadow-2xl backdrop-blur-md max-w-md mx-4 pointer-events-auto">
            <div>
              <h2 className="text-5xl font-display font-black text-white mb-2 tracking-tight" style={{ textShadow: `0 0 20px ${difficulty.color}` }}>
                {difficulty.label.toUpperCase()}
              </h2>
              <div className="h-1 w-24 mx-auto rounded-full" style={{ backgroundColor: difficulty.color, boxShadow: `0 0 10px ${difficulty.color}` }}></div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm font-mono text-slate-400 bg-black/30 p-4 rounded-lg">
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Goal</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                      {isEndless ? (
                        <>Endless <InfinityIcon className="w-3 h-3" /></>
                      ) : (
                        "15 Seconds"
                      )}
                    </span>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Best Time</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                        <Crown className="w-3 h-3 text-yellow-500" />
                        {bestTime > 0 ? `${bestTime}s` : '--'}
                    </span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-2 text-xs text-slate-500 uppercase tracking-widest mb-4">
              <ChevronsUp className="w-4 h-4 animate-bounce" /> Hold Space to Fly
            </div>

            <button
              onClick={() => { initAudio(); onStatusChange(GameStatus.Playing); }}
              className="group relative w-full py-4 bg-white text-black font-display font-black text-xl rounded hover:scale-[1.02] transition-transform overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
              START RUN
            </button>
          </div>
        </div>
      )}

      {/* GAME OVER SCREEN */}
      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-200 pointer-events-none">
          <div className="relative mb-4">
             <AlertTriangle className="w-20 h-20 text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
             <div className="absolute -bottom-2 -right-2 bg-red-600 rounded-full p-1 animate-ping"></div>
          </div>

          <h2 className="text-6xl font-display font-black text-white italic mb-2 tracking-tighter text-glow">CRASHED</h2>

          <div className="mb-8 flex flex-col items-center">
             <span className="text-red-200 font-mono text-sm uppercase tracking-widest mb-1">
                {isEndless ? "Time Survived" : "Attempt Failed"}
             </span>
             <span className="text-4xl font-mono font-bold text-white">
                {(gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00")}s
             </span>
             <span className="text-xs text-red-400/70 mt-2 font-mono">Attempt {attempts}</span>
          </div>

          <div className="flex flex-col items-center gap-3 pointer-events-auto">
             <button
                onClick={() => onStatusChange(GameStatus.Idle)}
                className="px-10 py-3 bg-red-600 hover:bg-red-500 text-white font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] transition-all"
             >
                Retry
             </button>
             <span className="text-xs text-red-300/60 font-mono uppercase tracking-widest flex items-center gap-2">
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div> 
                 Press Space to Restart
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div>
             </span>
          </div>
        </div>
      )}

      {/* WIN SCREEN */}
      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-yellow-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-500 pointer-events-none">
          <Trophy className="w-24 h-24 text-yellow-400 mb-6 drop-shadow-[0_0_25px_rgba(250,204,21,0.6)] animate-pulse" />
          <h2 className="text-6xl font-display font-black text-white mb-2 tracking-tighter text-glow">CLEARED!</h2>
          <p className="text-yellow-100 mb-8 font-mono text-lg">{difficulty.label} Complete</p>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="pointer-events-auto px-10 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(234,179,8,0.4)] hover:shadow-[0_0_30px_rgba(234,179,8,0.6)] transition-all"
          >
            Play Again
          </button>
        </div>
      )}

      {/* IN-GAME HUD */}
      <div className="absolute top-6 right-6 pointer-events-none flex flex-col items-end">
          <div className="font-display font-black text-5xl text-white drop-shadow-md tabular-nums tracking-tight">
              {status === GameStatus.Playing || status === GameStatus.Lost ? (gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00") : "0.00"}
              <span className="text-2xl text-slate-400 ml-1">s</span>
          </div>

          {/* Progress Bar (Only for Normal Mode) */}
          {!isEndless && (
            <div className="w-48 h-2 bg-slate-800 rounded-full mt-2 overflow-hidden border border-slate-700">
              <div 
                className="h-full transition-all duration-75 ease-linear"
                style={{ 
                  width: `${Math.min(100, (gameState.current.startTime ? (Date.now() - gameState.current.startTime) : 0) / WIN_TIME_MS * 100)}%`,
                  backgroundColor: gameState.current.baseColor,
                  boxShadow: `0 0 10px ${gameState.current.baseColor}`
                }}
              />
            </div>
          )}
      </div>

       <div className="absolute top-6 left-6 pointer-events-none">
          <div 
            className="px-4 py-2 rounded-sm bg-black/60 backdrop-blur-md border-l-4 text-sm font-bold text-white uppercase tracking-widest shadow-lg mb-2"
            style={{ borderColor: gameState.current.baseColor }}
          >
              {difficulty.label} {isEndless && <span className="text-blue-400 ml-1">(∞)</span>}
          </div>
          {bestTime > 0 && (
             <div className="flex items-center gap-1 text-xs text-yellow-500 font-mono bg-black/40 px-2 py-1 rounded">
                <Crown className="w-3 h-3" /> Best: {bestTime}s
             </div>
          )}
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS, WAVE_SPEED_Y } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle, ChevronsUp, Crown, Infinity as InfinityIcon, Volume2, VolumeX, MousePointer2, Eye, EyeOff, Activity, Hash, Zap } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
  isEndless?: boolean;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
  size: number;
  rotation: number; // Added rotation for shatter effect
  vRot: number;     // Angular velocity
}

interface ClickEffect {
  x: number;
  y: number;
  life: number;
  maxLife: number;
}

type GenerationPattern = 'flat' | 'ascend' | 'descend' | 'random';

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate, isEndless = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [bestTime, setBestTime] = useState<number>(0);
  const [attempts, setAttempts] = useState<number>(1);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const [clickSoundEnabled, setClickSoundEnabled] = useState<boolean>(true);
  const [showHitbox, setShowHitbox] = useState<boolean>(false);
  const [fps, setFps] = useState<number>(60);
  const [consistency, setConsistency] = useState<string>('100%'); // New Metric

  const audioCtxRef = useRef<AudioContext | null>(null);
  const inputState = useRef<boolean>(false); 

  // Game State Refs
  const gameState = useRef({
    playerY: 200,
    playerX: 100, 
    velocityY: 0,
    rotation: 0, 
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    clickEffects: [] as ClickEffect[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0,
    bgOffset: 0,
    shakeIntensity: 0,
    deathCoords: { x: 0, y: 0 },
    hasBeatenBest: false,
    frameCount: 0,
    lastFpsTime: 0,
    // Pattern Generation State
    pattern: 'flat' as GenerationPattern,
    patternCounter: 0,
    currentHue: 0,
    baseColor: difficulty.color,
    // Pulse System
    beatPhase: 0, 
    // Consistency Tracking
    lastClickTime: 0,
    clickIntervals: [] as number[],
    consistencyScore: 100
  });

  const requestRef = useRef<number>();

  // Initialize Audio Context
  const initAudio = useCallback(() => {
    if (!audioCtxRef.current) {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContext) {
        audioCtxRef.current = new AudioContext();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  }, []);

  const playSound = useCallback((type: 'crash' | 'win' | 'newBest' | 'click') => {
    if (isMuted || !audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    const now = ctx.currentTime;

    if (type === 'crash') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(100, now);
      osc.frequency.exponentialRampToValueAtTime(10, now + 0.3);
      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'win') {
      [523.25, 659.25, 783.99].forEach((freq, i) => { 
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;
        const startTime = now + (i * 0.1);
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(0.1, startTime + 0.1);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + 0.8);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + 0.8);
      });
    } else if (type === 'newBest') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.linearRampToValueAtTime(1760, now + 0.1);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.linearRampToValueAtTime(0, now + 0.2);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.2);
    } else if (type === 'click' && clickSoundEnabled) {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.frequency.setValueAtTime(1200, now);
      osc.frequency.exponentialRampToValueAtTime(600, now + 0.05);
      gain.gain.setValueAtTime(0.08, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
      osc.type = 'square'; 
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.05);
    }
  }, [isMuted, clickSoundEnabled]);

  // Load best time & reset attempts on difficulty switch
  useEffect(() => {
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const savedBest = localStorage.getItem(storageKey);
    setBestTime(savedBest ? parseFloat(savedBest) : 0);
    setAttempts(1); 
    gameState.current.baseColor = difficulty.color;
  }, [difficulty.id, isEndless]);

  const saveBestTime = (timeMs: number) => {
    const timeSec = timeMs / 1000;
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const currentBest = parseFloat(localStorage.getItem(storageKey) || '0');
    const effectiveTime = (!isEndless && timeSec > 15) ? 15 : timeSec;

    if (effectiveTime > currentBest) {
      localStorage.setItem(storageKey, effectiveTime.toFixed(2));
      setBestTime(effectiveTime);
    }
  };

  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 20;
    const minGapCenter = minWall + difficulty.gap / 2;
    const maxGapCenter = canvasHeight - minWall - difficulty.gap / 2;

    // Pattern Management
    if (gameState.current.patternCounter <= 0) {
        const rand = Math.random();
        if (rand < 0.4) gameState.current.pattern = 'flat';
        else if (rand < 0.7) gameState.current.pattern = Math.random() > 0.5 ? 'ascend' : 'descend';
        else gameState.current.pattern = 'random';

        gameState.current.patternCounter = Math.floor(Math.random() * 10) + 5;
    }
    gameState.current.patternCounter--;

    const lastObs = gameState.current.obstacles[gameState.current.obstacles.length - 1];
    let targetTopHeight = 0;

    if (!lastObs) {
        targetTopHeight = (canvasHeight - difficulty.gap) / 2;
    } else {
        const prevCenter = lastObs.topHeight + difficulty.gap / 2;
        let nextCenter = prevCenter;

        const slopeStep = WAVE_SPEED_Y * 5; 

        switch(gameState.current.pattern) {
            case 'flat':
                nextCenter = prevCenter + (Math.random() * 10 - 5);
                break;
            case 'ascend':
                nextCenter = prevCenter - slopeStep;
                break;
            case 'descend':
                nextCenter = prevCenter + slopeStep;
                break;
            case 'random':
            default:
                nextCenter = prevCenter + (Math.random() * 200 - 100);
                break;
        }

        if (nextCenter < minGapCenter) {
             nextCenter = minGapCenter + (minGapCenter - nextCenter); 
             if (gameState.current.pattern === 'ascend') gameState.current.pattern = 'descend'; 
        }
        if (nextCenter > maxGapCenter) {
             nextCenter = maxGapCenter - (nextCenter - maxGapCenter);
             if (gameState.current.pattern === 'descend') gameState.current.pattern = 'ascend'; 
        }

        targetTopHeight = nextCenter - difficulty.gap / 2;
    }

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), 
      topHeight: targetTopHeight,
      bottomY: targetTopHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    setAttempts(prev => prev + 1);
    setConsistency('100%');

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      rotation: 0,
      isHolding: inputState.current, 
      obstacles: [],
      particles: [],
      clickEffects: [],
      trail: [],
      startTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0,
      bgOffset: 0,
      shakeIntensity: 0,
      deathCoords: { x: 0, y: 0 },
      hasBeatenBest: false,
      frameCount: 0,
      lastFpsTime: performance.now(),
      pattern: 'flat',
      patternCounter: 0,
      currentHue: 0,
      baseColor: difficulty.color,
      beatPhase: 0,
      lastClickTime: 0,
      clickIntervals: [],
      consistencyScore: 100
    };

    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate, difficulty.color]);

  const createExplosion = (x: number, y: number, color: string) => {
    gameState.current.shakeIntensity = 25;
    gameState.current.deathCoords = { x, y }; 
    playSound('crash');

    // Simulate "Icon Shatter" - fewer, larger, squarish particles
    for (let i = 0; i < 8; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 8 + 4;
      const forwardMomentum = difficulty.speed * 0.8;

      gameState.current.particles.push({
        x,
        y,
        vx: (Math.cos(angle) * speed) + forwardMomentum, 
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color,
        size: Math.random() * 8 + 4,
        rotation: Math.random() * Math.PI * 2,
        vRot: (Math.random() - 0.5) * 0.5
      });
    }
  };

  const hslToHex = (h: number, s: number, l: number) => {
    l /= 100;
    const a = s * Math.min(l, 1 - l) / 100;
    const f = (n: number) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  };

  const calculateConsistency = () => {
      const intervals = gameState.current.clickIntervals;
      if (intervals.length < 5) return '100%';

      // We only care about consistency of "spamming", so filter out long pauses
      const spamIntervals = intervals.filter(i => i < 300); // Only clicks faster than ~3.3 CPS count for consistency

      if (spamIntervals.length < 5) return '100%';

      // Standard Deviation Calculation
      const mean = spamIntervals.reduce((a, b) => a + b) / spamIntervals.length;
      const variance = spamIntervals.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / spamIntervals.length;
      const stdDev = Math.sqrt(variance);

      // Normalize to a score (Lower stdDev is better)
      // < 10ms variance is godly (100%), > 50ms is bad (0%)
      const score = Math.max(0, Math.min(100, 100 - (stdDev - 5) * 2));
      gameState.current.consistencyScore = score;

      return `${score.toFixed(1)}%`;
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Pulse Logic (Simulate 128 BPM)
    gameState.current.beatPhase += 0.05;
    const beatPulse = Math.pow((Math.sin(gameState.current.beatPhase) + 1) / 2, 4); // Sharp pulse curve

    // Endless Mode Rainbow Effect
    if (isEndless) {
       gameState.current.currentHue = (gameState.current.currentHue + 0.5) % 360;
       gameState.current.baseColor = hslToHex(gameState.current.currentHue, 80, 60);
    } else {
       gameState.current.baseColor = difficulty.color;
    }
    const currentColor = gameState.current.baseColor;

    // FPS Counter
    gameState.current.frameCount++;
    if (time - gameState.current.lastFpsTime >= 1000) {
        setFps(Math.round((gameState.current.frameCount * 1000) / (time - gameState.current.lastFpsTime)));
        gameState.current.frameCount = 0;
        gameState.current.lastFpsTime = time;
    }

    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    const wasHolding = gameState.current.isHolding;
    gameState.current.isHolding = inputState.current;

    // Click Handling & Consistency
    if (wasHolding !== gameState.current.isHolding) {
       if (gameState.current.isHolding) {
           // Press Start
           playSound('click');

           const now = Date.now();
           if (gameState.current.lastClickTime > 0) {
               const diff = now - gameState.current.lastClickTime;
               gameState.current.clickIntervals.push(diff);
               if (gameState.current.clickIntervals.length % 5 === 0) {
                   setConsistency(calculateConsistency());
               }
           }
           gameState.current.lastClickTime = now;
       }

       gameState.current.clickEffects.push({
           x: gameState.current.playerX,
           y: gameState.current.playerY,
           life: 1.0,
           maxLife: 15
       });
    }

    if (bestTime > 0 && !gameState.current.hasBeatenBest) {
        const currentSec = elapsed / 1000;
        if (currentSec > bestTime) {
            gameState.current.hasBeatenBest = true;
            playSound('newBest');
        }
    }

    if (!isEndless && elapsed >= WIN_TIME_MS) {
      saveBestTime(WIN_TIME_MS);
      playSound('win');
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    gameState.current.bgOffset -= difficulty.speed * 0.5; 
    if (gameState.current.bgOffset <= -50) gameState.current.bgOffset += 50;

    // Shake
    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9; 
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    // BG Fill
    ctx.fillStyle = '#020617'; 
    ctx.fillRect(0, 0, width, height);

    // Pulsing Background Grid (Sync with Pulse)
    ctx.strokeStyle = currentColor;
    ctx.lineWidth = 1 + (beatPulse * 2); // Pulse line width
    ctx.globalAlpha = 0.1 + (beatPulse * 0.15); // Pulse opacity
    ctx.beginPath();
    for(let x = gameState.current.bgOffset; x < width; x += 50) { 
        if (x < 0) continue; 
        ctx.moveTo(x, 0); ctx.lineTo(x, height); 
    }
    for(let y = 0; y < height; y += 50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
    ctx.stroke();

    // Background Percent
    ctx.save();
    ctx.font = '900 150px Orbitron, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = gameState.current.hasBeatenBest ? '#fbbf24' : '#1e293b'; 
    ctx.globalAlpha = 0.1;
    let percent = 0;
    if (isEndless) {
       percent = Math.floor(elapsed / 1000); 
    } else {
       percent = Math.min(100, Math.floor((elapsed / WIN_TIME_MS) * 100));
    }
    ctx.fillText(`${percent}${isEndless ? 's' : '%'}`, width / 2, height / 2);
    ctx.restore();

    ctx.globalAlpha = 1.0;

    const waveSpeed = WAVE_SPEED_Y; 
    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    const slopeAngle = Math.atan2(WAVE_SPEED_Y, difficulty.speed);
    const targetRotation = gameState.current.isHolding ? -slopeAngle : slopeAngle;
    gameState.current.rotation += (targetRotation - gameState.current.rotation) * 0.5;

    const collisionRadius = 3;

    if (gameState.current.playerY < collisionRadius || gameState.current.playerY > height - collisionRadius) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, currentColor);
      saveBestTime(elapsed);
      onStatusChange(GameStatus.Lost);
      ctx.restore();
      return;
    }

    gameState.current.trail.push({ x: gameState.current.playerX - 5, y: gameState.current.playerY });
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    const spawnDistance = 250; 
    if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
        spawnObstacle(width, height, width + 50);
    }

    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      // Precision Hitbox Check
      if (gameState.current.playerX + collisionRadius > obs.x && gameState.current.playerX - collisionRadius < obs.x + obs.width) {
        if (gameState.current.playerY - collisionRadius < obs.topHeight || gameState.current.playerY + collisionRadius > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, currentColor);
           saveBestTime(elapsed);
           onStatusChange(GameStatus.Lost);
           ctx.restore();
           return;
        }
      }

      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // Draw Obstacles with Sawteeth
    const sawSize = 20; 
    const sawHeight = 6; 

    gameState.current.obstacles.forEach(obs => {
      // Main blocks
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);

      // Edges with Sawteeth visuals
      ctx.fillStyle = currentColor;

      ctx.beginPath();
      const startSaw = Math.floor(Math.max(0, -obs.x) / sawSize) * sawSize; 
      for(let sx = startSaw; sx < obs.width; sx += sawSize) {
          const px = obs.x + sx;
          if (px > width) break;
          ctx.moveTo(px, obs.topHeight);
          ctx.lineTo(px + sawSize/2, obs.topHeight + sawHeight);
          ctx.lineTo(px + sawSize, obs.topHeight);
      }
      ctx.fill();

      ctx.beginPath();
      for(let sx = startSaw; sx < obs.width; sx += sawSize) {
          const px = obs.x + sx;
          if (px > width) break;
          ctx.moveTo(px, obs.bottomY);
          ctx.lineTo(px + sawSize/2, obs.bottomY - sawHeight);
          ctx.lineTo(px + sawSize, obs.bottomY);
      }
      ctx.fill();

      // Neon lines on collision surface - Pulse thickness
      ctx.strokeStyle = currentColor;
      ctx.lineWidth = 2 + beatPulse;
      ctx.beginPath();
      ctx.moveTo(obs.x, obs.topHeight); ctx.lineTo(obs.x + obs.width, obs.topHeight);
      ctx.moveTo(obs.x, obs.bottomY); ctx.lineTo(obs.x + obs.width, obs.bottomY);
      ctx.stroke();

      // Debug Hitbox View
      if (showHitbox) {
          ctx.strokeStyle = '#ef4444';
          ctx.lineWidth = 1;
          ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
          ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
      }
    });

    // Floor Ceiling
    ctx.shadowBlur = (10 * beatPulse) + 5;
    ctx.shadowColor = currentColor;
    ctx.strokeStyle = currentColor;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(width, 0);
    ctx.moveTo(0, height); ctx.lineTo(width, height);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Enhanced Wave Trail (Thicker, tapered)
    if (gameState.current.trail.length > 1) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter'; 
      ctx.shadowBlur = 15;
      ctx.shadowColor = currentColor;

      // Draw outer glow
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = currentColor;
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.stroke();

      // Draw inner white core
      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1;
      ctx.stroke();

      ctx.restore();
    }

    // Draw Click Effects
    for(let i = gameState.current.clickEffects.length - 1; i >= 0; i--) {
        const effect = gameState.current.clickEffects[i];
        effect.life -= 1;
        if(effect.life <= 0) {
            gameState.current.clickEffects.splice(i, 1);
            continue;
        }
        const progress = 1 - (effect.life / effect.maxLife); 
        ctx.beginPath();
        ctx.arc(effect.x, effect.y, 10 + (progress * 20), 0, Math.PI * 2);
        ctx.strokeStyle = currentColor;
        ctx.lineWidth = 2 * (1 - progress);
        ctx.stroke();
    }

    // Draw Player
    ctx.save();
    ctx.translate(gameState.current.playerX, gameState.current.playerY);
    ctx.rotate(gameState.current.rotation);

    ctx.beginPath();
    ctx.moveTo(-6, -6);
    ctx.lineTo(8, 0);
    ctx.lineTo(-6, 6);
    ctx.closePath();

    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = currentColor;
    ctx.stroke();

    // Inner detail
    ctx.beginPath();
    ctx.moveTo(-2, -2);
    ctx.lineTo(2, 0);
    ctx.lineTo(-2, 2);
    ctx.closePath();
    ctx.fillStyle = currentColor;
    ctx.fill();

    // Hitbox Debug
    if (showHitbox) {
        ctx.beginPath();
        ctx.arc(0, 0, collisionRadius, 0, Math.PI * 2);
        ctx.fillStyle = '#ef4444';
        ctx.fill();
    }

    ctx.restore();
    ctx.restore(); 

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle, isEndless, playSound, bestTime, showHitbox, clickSoundEnabled]);

  const particleLoop = useCallback((time: number) => {
    if (status === GameStatus.Playing) return; 

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    const currentColor = gameState.current.baseColor;

    // Still pulse on death screen
    gameState.current.beatPhase += 0.05;
    const beatPulse = Math.pow((Math.sin(gameState.current.beatPhase) + 1) / 2, 4); 

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9;
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<width; x+=50) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
        for(let y=0; y<height; y+=50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
        ctx.stroke();

        ctx.strokeStyle = currentColor;
        ctx.lineWidth = 1;
        gameState.current.obstacles.forEach(obs => {
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
        });

        if (status === GameStatus.Lost) {
          const { x, y } = gameState.current.deathCoords;
          // Death Pulse Ring
          ctx.beginPath();
          ctx.arc(x, y, 20 + (beatPulse * 10), 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(239, 68, 68, ${0.5 * beatPulse})`;
          ctx.lineWidth = 3;
          ctx.stroke();
        }
    }

    // Render Shatter Particles
    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.rotation += p.vRot; // Rotate particle
      p.life -= 0.02;
      p.vx *= 0.95; 
      p.vy *= 0.95;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rotation);
      ctx.fillStyle = p.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.color;
      ctx.globalAlpha = p.life;
      // Draw square shards instead of generic circles
      ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
      ctx.restore();
    }

    ctx.restore();

    if (gameState.current.particles.length > 0 || gameState.current.shakeIntensity > 0 || status === GameStatus.Lost) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status, difficulty]);

  // Input Handling
  useEffect(() => {
    const handleInputDown = (e: Event) => {
        if (e.target instanceof HTMLButtonElement) return;

        if (e.type === 'keydown') {
             if ((e as KeyboardEvent).code === 'KeyH') {
                 setShowHitbox(prev => !prev);
                 return;
             }
             if ((e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        }
        if (e.type === 'touchstart') e.preventDefault();

        inputState.current = true; 

        if (status === GameStatus.Lost) {
             resetGame();
             gameState.current.isHolding = true; 
             onStatusChange(GameStatus.Playing);
             return;
        }

        if (status === GameStatus.Idle) {
            initAudio();
            onStatusChange(GameStatus.Playing);
            gameState.current.isHolding = true;
        }
    };

    const handleInputUp = (e: Event) => {
        if (e.type === 'keyup' && (e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        inputState.current = false;
    };

    window.addEventListener('keydown', handleInputDown as any);
    window.addEventListener('keyup', handleInputUp as any);

    const canvas = canvasRef.current;
    if (canvas) {
        canvas.addEventListener('mousedown', handleInputDown);
        canvas.addEventListener('mouseup', handleInputUp);
        canvas.addEventListener('mouseleave', handleInputUp);
        canvas.addEventListener('touchstart', handleInputDown, { passive: false });
        canvas.addEventListener('touchend', handleInputUp);
    }

    return () => {
        window.removeEventListener('keydown', handleInputDown as any);
        window.removeEventListener('keyup', handleInputUp as any);
        if (canvas) {
            canvas.removeEventListener('mousedown', handleInputDown);
            canvas.removeEventListener('mouseup', handleInputUp);
            canvas.removeEventListener('mouseleave', handleInputUp);
            canvas.removeEventListener('touchstart', handleInputDown);
            canvas.removeEventListener('touchend', handleInputUp);
        }
    };
  }, [status, resetGame, onStatusChange, initAudio]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]);

  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              if (status === GameStatus.Idle) { resetGame(); }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div 
      className="relative w-full max-w-5xl aspect-video md:h-[500px] bg-slate-950 rounded-lg overflow-hidden transition-all duration-500 mx-auto select-none touch-none group" 
      ref={containerRef}
      style={{
        boxShadow: `0 0 30px ${gameState.current.baseColor}15, 0 0 0 1px ${gameState.current.baseColor}30`
      }}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer outline-none"
      />

      {/* Decorative corners */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>

      {/* Control Toolbar */}
      <div className="absolute bottom-4 right-4 z-20 flex items-center gap-2">
         {/* Attempts Counter */}
         {status === GameStatus.Playing && (
             <div className="px-2 py-1 bg-black/40 backdrop-blur rounded text-[10px] font-mono text-slate-400 border border-white/5 flex items-center gap-1">
                 <Hash className="w-3 h-3" /> Att: {attempts}
             </div>
         )}

         <div className="h-6 w-px bg-white/10 mx-1"></div>

         {/* Consistency Meter (New Feature) */}
         {status === GameStatus.Playing && (
             <div className="px-2 py-1 bg-black/40 backdrop-blur rounded text-[10px] font-mono border border-white/5 flex items-center gap-1">
                 <Zap className="w-3 h-3 text-yellow-400" />
                 <span className={`${gameState.current.consistencyScore > 90 ? 'text-green-400' : gameState.current.consistencyScore > 70 ? 'text-yellow-400' : 'text-red-400'}`}>
                    {consistency}
                 </span>
             </div>
         )}

         <div className="h-6 w-px bg-white/10 mx-1"></div>

         {/* FPS Counter */}
         {status === GameStatus.Playing && (
             <div className="px-2 py-1 bg-black/40 backdrop-blur rounded text-[10px] font-mono text-slate-400 border border-white/5 flex items-center gap-1">
                 <Activity className="w-3 h-3" /> {fps} FPS
             </div>
         )}

         <div className="h-6 w-px bg-white/10 mx-1"></div>

         {/* Hitbox Toggle */}
         <button 
            onClick={(e) => { e.stopPropagation(); setShowHitbox(!showHitbox); }}
            className={`p-2 backdrop-blur rounded-full transition-colors ${showHitbox ? 'bg-red-500/20 text-red-400' : 'bg-black/40 text-slate-400 hover:text-white'}`}
            title="Toggle Hitbox (H)"
         >
            {showHitbox ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
         </button>

         {/* Click Sound Toggle */}
         <button 
            onClick={(e) => { e.stopPropagation(); setClickSoundEnabled(!clickSoundEnabled); }}
            className={`p-2 backdrop-blur rounded-full transition-colors ${clickSoundEnabled ? 'bg-blue-500/20 text-blue-400' : 'bg-black/40 text-slate-400 hover:text-white'}`}
            title="Click Sound FX"
         >
            <MousePointer2 className="w-4 h-4" />
         </button>

         {/* Master Mute */}
         <button 
            onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
            className="p-2 bg-black/40 hover:bg-black/60 backdrop-blur rounded-full text-slate-400 hover:text-white transition-colors"
            title={isMuted ? "Unmute Master" : "Mute Master"}
         >
            {isMuted ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
         </button>
      </div>

      {/* START SCREEN */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 backdrop-blur-[2px] z-10 animate-in fade-in duration-300 pointer-events-none">
          <div className="text-center space-y-6 p-8 border border-white/10 bg-black/50 rounded-2xl shadow-2xl backdrop-blur-md max-w-md mx-4 pointer-events-auto">
            <div>
              <h2 className="text-5xl font-display font-black text-white mb-2 tracking-tight" style={{ textShadow: `0 0 20px ${difficulty.color}` }}>
                {difficulty.label.toUpperCase()}
              </h2>
              <div className="h-1 w-24 mx-auto rounded-full" style={{ backgroundColor: difficulty.color, boxShadow: `0 0 10px ${difficulty.color}` }}></div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm font-mono text-slate-400 bg-black/30 p-4 rounded-lg">
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Goal</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                      {isEndless ? (
                        <>Endless <InfinityIcon className="w-3 h-3" /></>
                      ) : (
                        "15 Seconds"
                      )}
                    </span>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Best Time</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                        <Crown className="w-3 h-3 text-yellow-500" />
                        {bestTime > 0 ? `${bestTime}s` : '--'}
                    </span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-2 text-xs text-slate-500 uppercase tracking-widest mb-4">
              <ChevronsUp className="w-4 h-4 animate-bounce" /> Hold Space to Fly
            </div>

            <button
              onClick={() => { initAudio(); onStatusChange(GameStatus.Playing); }}
              className="group relative w-full py-4 bg-white text-black font-display font-black text-xl rounded hover:scale-[1.02] transition-transform overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
              START RUN
            </button>
          </div>
        </div>
      )}

      {/* GAME OVER SCREEN */}
      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-200 pointer-events-none">
          <div className="relative mb-4">
             <AlertTriangle className="w-20 h-20 text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
             <div className="absolute -bottom-2 -right-2 bg-red-600 rounded-full p-1 animate-ping"></div>
          </div>

          <h2 className="text-6xl font-display font-black text-white italic mb-2 tracking-tighter text-glow">CRASHED</h2>

          <div className="mb-8 flex flex-col items-center">
             <span className="text-red-200 font-mono text-sm uppercase tracking-widest mb-1">
                {isEndless ? "Time Survived" : "Attempt Failed"}
             </span>
             <span className="text-4xl font-mono font-bold text-white">
                {(gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00")}s
             </span>

             {/* Consistency Report on Death */}
             <div className="mt-4 flex items-center gap-4 text-xs font-mono">
                 <span className="text-slate-400">Consistency: 
                    <span className={`ml-1 font-bold ${gameState.current.consistencyScore > 90 ? 'text-green-400' : 'text-yellow-400'}`}>
                        {consistency}
                    </span>
                 </span>
                 <span className="text-slate-400">Attempt {attempts}</span>
             </div>
          </div>

          <div className="flex flex-col items-center gap-3 pointer-events-auto">
             <button
                onClick={() => onStatusChange(GameStatus.Idle)}
                className="px-10 py-3 bg-red-600 hover:bg-red-500 text-white font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] transition-all"
             >
                Retry
             </button>
             <span className="text-xs text-red-300/60 font-mono uppercase tracking-widest flex items-center gap-2">
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div> 
                 Press Space to Restart
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div>
             </span>
          </div>
        </div>
      )}

      {/* WIN SCREEN */}
      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-yellow-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-500 pointer-events-none">
          <Trophy className="w-24 h-24 text-yellow-400 mb-6 drop-shadow-[0_0_25px_rgba(250,204,21,0.6)] animate-pulse" />
          <h2 className="text-6xl font-display font-black text-white mb-2 tracking-tighter text-glow">CLEARED!</h2>
          <p className="text-yellow-100 mb-8 font-mono text-lg">{difficulty.label} Complete</p>
          <div className="text-center mb-8">
               <div className="text-xs text-yellow-500/80 uppercase font-mono tracking-widest mb-1">Stability</div>
               <div className="text-3xl font-bold text-white">{consistency}</div>
          </div>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="pointer-events-auto px-10 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(234,179,8,0.4)] hover:shadow-[0_0_30px_rgba(234,179,8,0.6)] transition-all"
          >
            Play Again
          </button>
        </div>
      )}

      {/* IN-GAME HUD */}
      <div className="absolute top-6 right-6 pointer-events-none flex flex-col items-end">
          <div className="font-display font-black text-5xl text-white drop-shadow-md tabular-nums tracking-tight">
              {status === GameStatus.Playing || status === GameStatus.Lost ? (gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00") : "0.00"}
              <span className="text-2xl text-slate-400 ml-1">s</span>
          </div>

          {/* Progress Bar (Only for Normal Mode) */}
          {!isEndless && (
            <div className="w-48 h-2 bg-slate-800 rounded-full mt-2 overflow-hidden border border-slate-700">
              <div 
                className="h-full transition-all duration-75 ease-linear"
                style={{ 
                  width: `${Math.min(100, (gameState.current.startTime ? (Date.now() - gameState.current.startTime) : 0) / WIN_TIME_MS * 100)}%`,
                  backgroundColor: gameState.current.baseColor,
                  boxShadow: `0 0 10px ${gameState.current.baseColor}`
                }}
              />
            </div>
          )}
      </div>

       <div className="absolute top-6 left-6 pointer-events-none">
          <div 
            className="px-4 py-2 rounded-sm bg-black/60 backdrop-blur-md border-l-4 text-sm font-bold text-white uppercase tracking-widest shadow-lg mb-2"
            style={{ borderColor: gameState.current.baseColor }}
          >
              {difficulty.label} {isEndless && <span className="text-blue-400 ml-1">(∞)</span>}
          </div>
          {bestTime > 0 && (
             <div className="flex items-center gap-1 text-xs text-yellow-500 font-mono bg-black/40 px-2 py-1 rounded">
                <Crown className="w-3 h-3" /> Best: {bestTime}s
             </div>
          )}
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { DifficultyConfig, GameStatus } from '../types';
import { WIN_TIME_MS, WAVE_SPEED_Y } from '../constants';
import { Play, RotateCcw, Trophy, AlertTriangle, ChevronsUp, Crown, Infinity as InfinityIcon, Volume2, VolumeX, MousePointer2, Eye, EyeOff, Activity, Hash, Zap } from 'lucide-react';

interface GameCanvasProps {
  difficulty: DifficultyConfig;
  status: GameStatus;
  onStatusChange: (status: GameStatus) => void;
  onTimeUpdate: (ms: number) => void;
  isEndless?: boolean;
}

interface Obstacle {
  x: number;
  width: number;
  topHeight: number;
  bottomY: number;
  passed: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
  size: number;
  rotation: number; 
  vRot: number;     
}

interface Decoration {
  x: number;
  y: number;
  size: number;
  shape: 'square' | 'triangle';
  speedFactor: number; // 0.1 to 0.5 relative to game speed
  rotation: number;
  opacity: number;
}

interface ClickEffect {
  x: number;
  y: number;
  life: number;
  maxLife: number;
}

type GenerationPattern = 'flat' | 'ascend' | 'descend' | 'random';

const GameCanvas: React.FC<GameCanvasProps> = ({ difficulty, status, onStatusChange, onTimeUpdate, isEndless = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [bestTime, setBestTime] = useState<number>(0);
  const [attempts, setAttempts] = useState<number>(1);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const [clickSoundEnabled, setClickSoundEnabled] = useState<boolean>(true);
  const [showHitbox, setShowHitbox] = useState<boolean>(false);
  const [fps, setFps] = useState<number>(60);
  const [consistency, setConsistency] = useState<string>('100%'); 

  const audioCtxRef = useRef<AudioContext | null>(null);
  const inputState = useRef<boolean>(false); 

  // Game State Refs
  const gameState = useRef({
    playerY: 200,
    playerX: 100, 
    velocityY: 0,
    rotation: 0, 
    isHolding: false,
    obstacles: [] as Obstacle[],
    particles: [] as Particle[],
    decorations: [] as Decoration[],
    clickEffects: [] as ClickEffect[],
    trail: [] as {x: number, y: number}[],
    startTime: 0,
    distanceTraveled: 0,
    lastObstacleX: 0,
    bgOffset: 0,
    groundOffset: 0,
    shakeIntensity: 0,
    deathCoords: { x: 0, y: 0 },
    hasBeatenBest: false,
    frameCount: 0,
    lastFpsTime: 0,
    pattern: 'flat' as GenerationPattern,
    patternCounter: 0,
    currentHue: 0,
    baseColor: difficulty.color,
    beatPhase: 0, 
    lastClickTime: 0,
    clickIntervals: [] as number[],
    consistencyScore: 100
  });

  const requestRef = useRef<number>();

  const initAudio = useCallback(() => {
    if (!audioCtxRef.current) {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContext) {
        audioCtxRef.current = new AudioContext();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  }, []);

  const playSound = useCallback((type: 'crash' | 'win' | 'newBest' | 'click') => {
    if (isMuted || !audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    const now = ctx.currentTime;

    if (type === 'crash') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(100, now);
      osc.frequency.exponentialRampToValueAtTime(10, now + 0.3);
      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'win') {
      [523.25, 659.25, 783.99].forEach((freq, i) => { 
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;
        const startTime = now + (i * 0.1);
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(0.1, startTime + 0.1);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + 0.8);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + 0.8);
      });
    } else if (type === 'newBest') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.linearRampToValueAtTime(1760, now + 0.1);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.linearRampToValueAtTime(0, now + 0.2);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.2);
    } else if (type === 'click' && clickSoundEnabled) {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.frequency.setValueAtTime(1200, now);
      osc.frequency.exponentialRampToValueAtTime(600, now + 0.05);
      gain.gain.setValueAtTime(0.08, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
      osc.type = 'square'; 
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.05);
    }
  }, [isMuted, clickSoundEnabled]);

  useEffect(() => {
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const savedBest = localStorage.getItem(storageKey);
    setBestTime(savedBest ? parseFloat(savedBest) : 0);
    setAttempts(1); 
    gameState.current.baseColor = difficulty.color;
  }, [difficulty.id, isEndless]);

  const saveBestTime = (timeMs: number) => {
    const timeSec = timeMs / 1000;
    const storageKey = isEndless 
        ? `gd_spam_best_endless_${difficulty.id}` 
        : `gd_spam_best_${difficulty.id}`;

    const currentBest = parseFloat(localStorage.getItem(storageKey) || '0');
    const effectiveTime = (!isEndless && timeSec > 15) ? 15 : timeSec;

    if (effectiveTime > currentBest) {
      localStorage.setItem(storageKey, effectiveTime.toFixed(2));
      setBestTime(effectiveTime);
    }
  };

  const spawnDecoration = (canvasWidth: number, canvasHeight: number) => {
      // Spawn floating background shapes
      if (Math.random() < 0.02) { // Low chance per frame
          gameState.current.decorations.push({
              x: canvasWidth + 50,
              y: Math.random() * canvasHeight,
              size: Math.random() * 40 + 10,
              shape: Math.random() > 0.5 ? 'square' : 'triangle',
              speedFactor: Math.random() * 0.3 + 0.1, // Slower than obstacles for parallax
              rotation: Math.random() * Math.PI * 2,
              opacity: Math.random() * 0.1 + 0.05
          });
      }
  };

  const spawnObstacle = useCallback((canvasWidth: number, canvasHeight: number, startX: number) => {
    const minWall = 30; // Increased floor/ceiling thickness
    const minGapCenter = minWall + difficulty.gap / 2;
    const maxGapCenter = canvasHeight - minWall - difficulty.gap / 2;

    // Pattern Management
    if (gameState.current.patternCounter <= 0) {
        const rand = Math.random();
        if (rand < 0.4) gameState.current.pattern = 'flat';
        else if (rand < 0.7) gameState.current.pattern = Math.random() > 0.5 ? 'ascend' : 'descend';
        else gameState.current.pattern = 'random';

        gameState.current.patternCounter = Math.floor(Math.random() * 10) + 5;
    }
    gameState.current.patternCounter--;

    const lastObs = gameState.current.obstacles[gameState.current.obstacles.length - 1];
    let targetTopHeight = 0;

    if (!lastObs) {
        targetTopHeight = (canvasHeight - difficulty.gap) / 2;
    } else {
        const prevCenter = lastObs.topHeight + difficulty.gap / 2;
        let nextCenter = prevCenter;
        const slopeStep = WAVE_SPEED_Y * 5; 

        switch(gameState.current.pattern) {
            case 'flat':
                nextCenter = prevCenter + (Math.random() * 10 - 5);
                break;
            case 'ascend':
                nextCenter = prevCenter - slopeStep;
                break;
            case 'descend':
                nextCenter = prevCenter + slopeStep;
                break;
            case 'random':
            default:
                nextCenter = prevCenter + (Math.random() * 200 - 100);
                break;
        }

        if (nextCenter < minGapCenter) {
             nextCenter = minGapCenter + (minGapCenter - nextCenter); 
             if (gameState.current.pattern === 'ascend') gameState.current.pattern = 'descend'; 
        }
        if (nextCenter > maxGapCenter) {
             nextCenter = maxGapCenter - (nextCenter - maxGapCenter);
             if (gameState.current.pattern === 'descend') gameState.current.pattern = 'ascend'; 
        }

        targetTopHeight = nextCenter - difficulty.gap / 2;
    }

    gameState.current.obstacles.push({
      x: startX,
      width: 50 + (difficulty.speed * 2), 
      topHeight: targetTopHeight,
      bottomY: targetTopHeight + difficulty.gap,
      passed: false
    });

    gameState.current.lastObstacleX = startX;
  }, [difficulty]);

  const resetGame = useCallback(() => {
    if (!canvasRef.current) return;
    const height = canvasRef.current.height;

    setAttempts(prev => prev + 1);
    setConsistency('100%');

    gameState.current = {
      playerY: height / 2,
      playerX: 100,
      velocityY: 0,
      rotation: 0,
      isHolding: inputState.current, 
      obstacles: [],
      particles: [],
      decorations: [], // Clear decorations
      clickEffects: [],
      trail: [],
      startTime: 0,
      distanceTraveled: 0,
      lastObstacleX: 0,
      bgOffset: 0,
      groundOffset: 0,
      shakeIntensity: 0,
      deathCoords: { x: 0, y: 0 },
      hasBeatenBest: false,
      frameCount: 0,
      lastFpsTime: performance.now(),
      pattern: 'flat',
      patternCounter: 0,
      currentHue: 0,
      baseColor: difficulty.color,
      beatPhase: 0,
      lastClickTime: 0,
      clickIntervals: [],
      consistencyScore: 100
    };

    const ctx = canvasRef.current.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvasRef.current.width, height);
    onTimeUpdate(0);
  }, [onTimeUpdate, difficulty.color]);

  const createExplosion = (x: number, y: number, color: string) => {
    gameState.current.shakeIntensity = 25;
    gameState.current.deathCoords = { x, y }; 
    playSound('crash');

    for (let i = 0; i < 8; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 8 + 4;
      const forwardMomentum = difficulty.speed * 0.8;

      gameState.current.particles.push({
        x,
        y,
        vx: (Math.cos(angle) * speed) + forwardMomentum, 
        vy: Math.sin(angle) * speed,
        life: 1.0,
        color,
        size: Math.random() * 8 + 4,
        rotation: Math.random() * Math.PI * 2,
        vRot: (Math.random() - 0.5) * 0.5
      });
    }
  };

  const hslToHex = (h: number, s: number, l: number) => {
    l /= 100;
    const a = s * Math.min(l, 1 - l) / 100;
    const f = (n: number) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  };

  const calculateConsistency = () => {
      const intervals = gameState.current.clickIntervals;
      if (intervals.length < 5) return '100%';
      const spamIntervals = intervals.filter(i => i < 300); 
      if (spamIntervals.length < 5) return '100%';
      const mean = spamIntervals.reduce((a, b) => a + b) / spamIntervals.length;
      const variance = spamIntervals.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / spamIntervals.length;
      const stdDev = Math.sqrt(variance);
      const score = Math.max(0, Math.min(100, 100 - (stdDev - 5) * 2));
      gameState.current.consistencyScore = score;
      return `${score.toFixed(1)}%`;
  };

  const gameLoop = useCallback((time: number) => {
    if (status !== GameStatus.Playing) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Pulse Logic
    gameState.current.beatPhase += 0.05;
    const beatPulse = Math.pow((Math.sin(gameState.current.beatPhase) + 1) / 2, 4); 

    // Endless Mode Rainbow
    if (isEndless) {
       gameState.current.currentHue = (gameState.current.currentHue + 0.5) % 360;
       gameState.current.baseColor = hslToHex(gameState.current.currentHue, 80, 60);
    } else {
       gameState.current.baseColor = difficulty.color;
    }
    const currentColor = gameState.current.baseColor;

    // FPS
    gameState.current.frameCount++;
    if (time - gameState.current.lastFpsTime >= 1000) {
        setFps(Math.round((gameState.current.frameCount * 1000) / (time - gameState.current.lastFpsTime)));
        gameState.current.frameCount = 0;
        gameState.current.lastFpsTime = time;
    }

    if (gameState.current.startTime === 0) gameState.current.startTime = time;
    const elapsed = time - gameState.current.startTime;
    onTimeUpdate(elapsed);

    const wasHolding = gameState.current.isHolding;
    gameState.current.isHolding = inputState.current;

    // Click Handling
    if (wasHolding !== gameState.current.isHolding) {
       if (gameState.current.isHolding) {
           playSound('click');
           const now = Date.now();
           if (gameState.current.lastClickTime > 0) {
               const diff = now - gameState.current.lastClickTime;
               gameState.current.clickIntervals.push(diff);
               if (gameState.current.clickIntervals.length % 5 === 0) {
                   setConsistency(calculateConsistency());
               }
           }
           gameState.current.lastClickTime = now;
       }
       gameState.current.clickEffects.push({
           x: gameState.current.playerX,
           y: gameState.current.playerY,
           life: 1.0,
           maxLife: 15
       });
    }

    if (bestTime > 0 && !gameState.current.hasBeatenBest) {
        const currentSec = elapsed / 1000;
        if (currentSec > bestTime) {
            gameState.current.hasBeatenBest = true;
            playSound('newBest');
        }
    }

    if (!isEndless && elapsed >= WIN_TIME_MS) {
      saveBestTime(WIN_TIME_MS);
      playSound('win');
      onStatusChange(GameStatus.Won);
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    // Offsets
    gameState.current.bgOffset -= difficulty.speed * 0.5; 
    if (gameState.current.bgOffset <= -50) gameState.current.bgOffset += 50;

    gameState.current.groundOffset -= difficulty.speed;
    if (gameState.current.groundOffset <= -50) gameState.current.groundOffset += 50;

    // Shake
    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9; 
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    // --- BG Fill ---
    ctx.fillStyle = '#020617'; 
    ctx.fillRect(0, 0, width, height);

    // --- Parallax Decorations ---
    spawnDecoration(width, height);
    for(let i = gameState.current.decorations.length - 1; i >= 0; i--) {
        const decor = gameState.current.decorations[i];
        decor.x -= difficulty.speed * decor.speedFactor;
        decor.rotation += 0.01;

        if (decor.x + decor.size < 0) {
            gameState.current.decorations.splice(i, 1);
            continue;
        }

        ctx.save();
        ctx.translate(decor.x, decor.y);
        ctx.rotate(decor.rotation);
        ctx.fillStyle = currentColor;
        ctx.globalAlpha = decor.opacity;

        if (decor.shape === 'square') {
            ctx.fillRect(-decor.size/2, -decor.size/2, decor.size, decor.size);
        } else {
            ctx.beginPath();
            ctx.moveTo(0, -decor.size/2);
            ctx.lineTo(decor.size/2, decor.size/2);
            ctx.lineTo(-decor.size/2, decor.size/2);
            ctx.fill();
        }
        ctx.restore();
    }

    // --- Grid ---
    ctx.strokeStyle = currentColor;
    ctx.lineWidth = 1 + (beatPulse * 2); 
    ctx.globalAlpha = 0.1 + (beatPulse * 0.15); 
    ctx.beginPath();
    for(let x = gameState.current.bgOffset; x < width; x += 50) { 
        if (x < 0) continue; 
        ctx.moveTo(x, 0); ctx.lineTo(x, height); 
    }
    for(let y = 0; y < height; y += 50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
    ctx.stroke();
    ctx.globalAlpha = 1.0;

    // --- Player Physics ---
    const waveSpeed = WAVE_SPEED_Y; 
    if (gameState.current.isHolding) {
      gameState.current.playerY -= waveSpeed;
    } else {
      gameState.current.playerY += waveSpeed;
    }

    const slopeAngle = Math.atan2(WAVE_SPEED_Y, difficulty.speed);
    const targetRotation = gameState.current.isHolding ? -slopeAngle : slopeAngle;
    gameState.current.rotation += (targetRotation - gameState.current.rotation) * 0.5;

    const collisionRadius = 3;
    const floorHeight = 25;

    // --- Floor Collision ---
    if (gameState.current.playerY < floorHeight + collisionRadius || gameState.current.playerY > height - floorHeight - collisionRadius) {
      createExplosion(gameState.current.playerX, gameState.current.playerY, currentColor);
      saveBestTime(elapsed);
      onStatusChange(GameStatus.Lost);
      ctx.restore();
      return;
    }

    gameState.current.trail.push({ x: gameState.current.playerX - 5, y: gameState.current.playerY });
    gameState.current.trail = gameState.current.trail.map(p => ({ ...p, x: p.x - difficulty.speed })).filter(p => p.x > 0);

    // --- Obstacle Spawning (With Start Buffer) ---
    // Wait 500ms or 200 pixels before spawning first obstacle
    const startBuffer = 500; 
    const spawnDistance = 250; 

    if (gameState.current.distanceTraveled < startBuffer) {
        gameState.current.distanceTraveled += difficulty.speed;
        gameState.current.lastObstacleX = width; // Reset spawn pointer
    } else {
        if (gameState.current.obstacles.length === 0 || (width + 100) - gameState.current.lastObstacleX > spawnDistance) {
            spawnObstacle(width, height, width + 50);
        }
    }

    for (let i = gameState.current.obstacles.length - 1; i >= 0; i--) {
      const obs = gameState.current.obstacles[i];
      obs.x -= difficulty.speed;

      // Hitbox
      if (gameState.current.playerX + collisionRadius > obs.x && gameState.current.playerX - collisionRadius < obs.x + obs.width) {
        if (gameState.current.playerY - collisionRadius < obs.topHeight || gameState.current.playerY + collisionRadius > obs.bottomY) {
           createExplosion(gameState.current.playerX, gameState.current.playerY, currentColor);
           saveBestTime(elapsed);
           onStatusChange(GameStatus.Lost);
           ctx.restore();
           return;
        }
      }

      if (obs.x + obs.width < -100) {
        gameState.current.obstacles.splice(i, 1);
      }
    }

    // --- Draw Obstacles ---
    const sawSize = 20; 
    const sawHeight = 6; 

    gameState.current.obstacles.forEach(obs => {
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
      ctx.fillRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
      ctx.fillStyle = currentColor;

      // Top Teeth
      ctx.beginPath();
      const startSaw = Math.floor(Math.max(0, -obs.x) / sawSize) * sawSize; 
      for(let sx = startSaw; sx < obs.width; sx += sawSize) {
          const px = obs.x + sx;
          if (px > width) break;
          ctx.moveTo(px, obs.topHeight);
          ctx.lineTo(px + sawSize/2, obs.topHeight + sawHeight);
          ctx.lineTo(px + sawSize, obs.topHeight);
      }
      ctx.fill();

      // Bottom Teeth
      ctx.beginPath();
      for(let sx = startSaw; sx < obs.width; sx += sawSize) {
          const px = obs.x + sx;
          if (px > width) break;
          ctx.moveTo(px, obs.bottomY);
          ctx.lineTo(px + sawSize/2, obs.bottomY - sawHeight);
          ctx.lineTo(px + sawSize, obs.bottomY);
      }
      ctx.fill();

      // Neon lines
      ctx.strokeStyle = currentColor;
      ctx.lineWidth = 2 + beatPulse;
      ctx.beginPath();
      ctx.moveTo(obs.x, obs.topHeight); ctx.lineTo(obs.x + obs.width, obs.topHeight);
      ctx.moveTo(obs.x, obs.bottomY); ctx.lineTo(obs.x + obs.width, obs.bottomY);
      ctx.stroke();

      if (showHitbox) {
          ctx.strokeStyle = '#ef4444';
          ctx.lineWidth = 1;
          ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
          ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
      }
    });

    // --- Floor & Ceiling Scrolling Texture ---
    const floorSize = 50;
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(0, 0, width, floorHeight);
    ctx.fillRect(0, height - floorHeight, width, floorHeight);

    ctx.strokeStyle = currentColor;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, floorHeight); ctx.lineTo(width, floorHeight);
    ctx.moveTo(0, height - floorHeight); ctx.lineTo(width, height - floorHeight);
    ctx.stroke();

    // Floor Detail (Scrolling squares)
    ctx.fillStyle = currentColor;
    ctx.globalAlpha = 0.3;
    for(let x = gameState.current.groundOffset; x < width; x += floorSize) {
         // Top blocks
         ctx.fillRect(x + 10, 5, floorSize - 20, floorSize - 35);
         // Bottom blocks
         ctx.fillRect(x + 10, height - floorHeight + 10, floorSize - 20, floorSize - 35);
    }
    ctx.globalAlpha = 1.0;

    // --- Wave Trail ---
    if (gameState.current.trail.length > 1) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter'; 
      ctx.shadowBlur = 15;
      ctx.shadowColor = currentColor;

      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = currentColor;
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(gameState.current.trail[0].x, gameState.current.trail[0].y);
      for (let i = 1; i < gameState.current.trail.length; i++) {
        ctx.lineTo(gameState.current.trail[i].x, gameState.current.trail[i].y);
      }
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.restore();
    }

    // --- Click Effects ---
    for(let i = gameState.current.clickEffects.length - 1; i >= 0; i--) {
        const effect = gameState.current.clickEffects[i];
        effect.life -= 1;
        if(effect.life <= 0) {
            gameState.current.clickEffects.splice(i, 1);
            continue;
        }
        const progress = 1 - (effect.life / effect.maxLife); 
        ctx.beginPath();
        ctx.arc(effect.x, effect.y, 10 + (progress * 20), 0, Math.PI * 2);
        ctx.strokeStyle = currentColor;
        ctx.lineWidth = 2 * (1 - progress);
        ctx.stroke();
    }

    // --- Player ---
    ctx.save();
    ctx.translate(gameState.current.playerX, gameState.current.playerY);
    ctx.rotate(gameState.current.rotation);

    ctx.beginPath();
    ctx.moveTo(-6, -6);
    ctx.lineTo(8, 0);
    ctx.lineTo(-6, 6);
    ctx.closePath();

    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = currentColor;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(-2, -2);
    ctx.lineTo(2, 0);
    ctx.lineTo(-2, 2);
    ctx.closePath();
    ctx.fillStyle = currentColor;
    ctx.fill();

    if (showHitbox) {
        ctx.beginPath();
        ctx.arc(0, 0, collisionRadius, 0, Math.PI * 2);
        ctx.fillStyle = '#ef4444';
        ctx.fill();
    }

    ctx.restore();
    ctx.restore(); 

    requestRef.current = requestAnimationFrame(gameLoop);
  }, [difficulty, status, onStatusChange, onTimeUpdate, spawnObstacle, isEndless, playSound, bestTime, showHitbox, clickSoundEnabled]);

  const particleLoop = useCallback((time: number) => {
    if (status === GameStatus.Playing) return; 

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;

    const currentColor = gameState.current.baseColor;

    // Still pulse on death screen
    gameState.current.beatPhase += 0.05;
    const beatPulse = Math.pow((Math.sin(gameState.current.beatPhase) + 1) / 2, 4); 

    ctx.save();
    if (gameState.current.shakeIntensity > 0) {
      const shakeX = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      const shakeY = (Math.random() - 0.5) * gameState.current.shakeIntensity;
      ctx.translate(shakeX, shakeY);
      gameState.current.shakeIntensity *= 0.9;
      if (gameState.current.shakeIntensity < 0.5) gameState.current.shakeIntensity = 0;
    }

    if (status !== GameStatus.Playing) {
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<width; x+=50) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
        for(let y=0; y<height; y+=50) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
        ctx.stroke();

        ctx.strokeStyle = currentColor;
        ctx.lineWidth = 1;
        gameState.current.obstacles.forEach(obs => {
            ctx.strokeRect(obs.x, 0, obs.width, obs.topHeight);
            ctx.strokeRect(obs.x, obs.bottomY, obs.width, height - obs.bottomY);
        });

        if (status === GameStatus.Lost) {
          const { x, y } = gameState.current.deathCoords;
          // Death Pulse Ring
          ctx.beginPath();
          ctx.arc(x, y, 20 + (beatPulse * 10), 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(239, 68, 68, ${0.5 * beatPulse})`;
          ctx.lineWidth = 3;
          ctx.stroke();
        }
    }

    // Render Shatter Particles
    for (let i = gameState.current.particles.length - 1; i >= 0; i--) {
      const p = gameState.current.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.rotation += p.vRot; // Rotate particle
      p.life -= 0.02;
      p.vx *= 0.95; 
      p.vy *= 0.95;

      if (p.life <= 0) {
        gameState.current.particles.splice(i, 1);
        continue;
      }

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rotation);
      ctx.fillStyle = p.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.color;
      ctx.globalAlpha = p.life;
      ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
      ctx.restore();
    }

    ctx.restore();

    if (gameState.current.particles.length > 0 || gameState.current.shakeIntensity > 0 || status === GameStatus.Lost) {
       requestRef.current = requestAnimationFrame(particleLoop);
    }
  }, [status, difficulty]);

  // Input Handling
  useEffect(() => {
    const handleInputDown = (e: Event) => {
        if (e.target instanceof HTMLButtonElement) return;

        if (e.type === 'keydown') {
             if ((e as KeyboardEvent).code === 'KeyH') {
                 setShowHitbox(prev => !prev);
                 return;
             }
             if ((e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        }
        if (e.type === 'touchstart') e.preventDefault();

        inputState.current = true; 

        if (status === GameStatus.Lost) {
             resetGame();
             gameState.current.isHolding = true; 
             onStatusChange(GameStatus.Playing);
             return;
        }

        if (status === GameStatus.Idle) {
            initAudio();
            onStatusChange(GameStatus.Playing);
            gameState.current.isHolding = true;
        }
    };

    const handleInputUp = (e: Event) => {
        if (e.type === 'keyup' && (e as KeyboardEvent).code !== 'Space' && (e as KeyboardEvent).code !== 'ArrowUp') return;
        inputState.current = false;
    };

    window.addEventListener('keydown', handleInputDown as any);
    window.addEventListener('keyup', handleInputUp as any);

    const canvas = canvasRef.current;
    if (canvas) {
        canvas.addEventListener('mousedown', handleInputDown);
        canvas.addEventListener('mouseup', handleInputUp);
        canvas.addEventListener('mouseleave', handleInputUp);
        canvas.addEventListener('touchstart', handleInputDown, { passive: false });
        canvas.addEventListener('touchend', handleInputUp);
    }

    return () => {
        window.removeEventListener('keydown', handleInputDown as any);
        window.removeEventListener('keyup', handleInputUp as any);
        if (canvas) {
            canvas.removeEventListener('mousedown', handleInputDown);
            canvas.removeEventListener('mouseup', handleInputUp);
            canvas.removeEventListener('mouseleave', handleInputUp);
            canvas.removeEventListener('touchstart', handleInputDown);
            canvas.removeEventListener('touchend', handleInputUp);
        }
    };
  }, [status, resetGame, onStatusChange, initAudio]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameLoop]);

  useEffect(() => {
     if (status === GameStatus.Lost) {
         requestRef.current = requestAnimationFrame(particleLoop);
     }
  }, [status, particleLoop]);

  useEffect(() => {
    if (status === GameStatus.Idle) {
        resetGame();
    }
  }, [status, resetGame, difficulty]);

  useEffect(() => {
      const handleResize = () => {
          if (containerRef.current && canvasRef.current) {
              canvasRef.current.width = containerRef.current.clientWidth;
              canvasRef.current.height = containerRef.current.clientHeight;
              if (status === GameStatus.Idle) { resetGame(); }
          }
      };
      window.addEventListener('resize', handleResize);
      handleResize();
      return () => window.removeEventListener('resize', handleResize);
  }, [status, resetGame]);


  return (
    <div 
      className="relative w-full max-w-5xl aspect-video md:h-[500px] bg-slate-950 rounded-lg overflow-hidden transition-all duration-500 mx-auto select-none touch-none group" 
      ref={containerRef}
      style={{
        boxShadow: `0 0 30px ${gameState.current.baseColor}15, 0 0 0 1px ${gameState.current.baseColor}30`
      }}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full cursor-pointer outline-none"
      />

      {/* Decorative corners */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 opacity-50 transition-colors duration-300" style={{ borderColor: gameState.current.baseColor }}></div>

      {/* TOP PROGRESS BAR (Like Real GD) */}
      {!isEndless && (status === GameStatus.Playing || status === GameStatus.Lost) && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 w-2/3 h-4 bg-black/60 backdrop-blur border border-white/20 rounded-full overflow-hidden shadow-lg z-20">
              <div 
                  className="h-full transition-all duration-100 ease-linear relative"
                  style={{ 
                    width: `${Math.min(100, (gameState.current.startTime ? (Date.now() - gameState.current.startTime) : 0) / WIN_TIME_MS * 100)}%`,
                    backgroundColor: gameState.current.baseColor,
                    boxShadow: `0 0 15px ${gameState.current.baseColor}`
                  }}
              >
                  <div className="absolute right-0 top-0 bottom-0 w-[2px] bg-white shadow-[0_0_10px_white]"></div>
              </div>
          </div>
      )}

      {/* Control Toolbar */}
      <div className="absolute bottom-4 right-4 z-20 flex items-center gap-2">
         {status === GameStatus.Playing && (
             <div className="px-2 py-1 bg-black/40 backdrop-blur rounded text-[10px] font-mono text-slate-400 border border-white/5 flex items-center gap-1">
                 <Hash className="w-3 h-3" /> Att: {attempts}
             </div>
         )}

         <div className="h-6 w-px bg-white/10 mx-1"></div>

         {status === GameStatus.Playing && (
             <div className="px-2 py-1 bg-black/40 backdrop-blur rounded text-[10px] font-mono border border-white/5 flex items-center gap-1">
                 <Zap className="w-3 h-3 text-yellow-400" />
                 <span className={`${gameState.current.consistencyScore > 90 ? 'text-green-400' : gameState.current.consistencyScore > 70 ? 'text-yellow-400' : 'text-red-400'}`}>
                    {consistency}
                 </span>
             </div>
         )}

         <div className="h-6 w-px bg-white/10 mx-1"></div>

         {status === GameStatus.Playing && (
             <div className="px-2 py-1 bg-black/40 backdrop-blur rounded text-[10px] font-mono text-slate-400 border border-white/5 flex items-center gap-1">
                 <Activity className="w-3 h-3" /> {fps} FPS
             </div>
         )}

         <div className="h-6 w-px bg-white/10 mx-1"></div>

         <button 
            onClick={(e) => { e.stopPropagation(); setShowHitbox(!showHitbox); }}
            className={`p-2 backdrop-blur rounded-full transition-colors ${showHitbox ? 'bg-red-500/20 text-red-400' : 'bg-black/40 text-slate-400 hover:text-white'}`}
            title="Toggle Hitbox (H)"
         >
            {showHitbox ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
         </button>

         <button 
            onClick={(e) => { e.stopPropagation(); setClickSoundEnabled(!clickSoundEnabled); }}
            className={`p-2 backdrop-blur rounded-full transition-colors ${clickSoundEnabled ? 'bg-blue-500/20 text-blue-400' : 'bg-black/40 text-slate-400 hover:text-white'}`}
            title="Click Sound FX"
         >
            <MousePointer2 className="w-4 h-4" />
         </button>

         <button 
            onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
            className="p-2 bg-black/40 hover:bg-black/60 backdrop-blur rounded-full text-slate-400 hover:text-white transition-colors"
            title={isMuted ? "Unmute Master" : "Mute Master"}
         >
            {isMuted ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
         </button>
      </div>

      {/* START SCREEN */}
      {status === GameStatus.Idle && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 backdrop-blur-[2px] z-10 animate-in fade-in duration-300 pointer-events-none">
          <div className="text-center space-y-6 p-8 border border-white/10 bg-black/50 rounded-2xl shadow-2xl backdrop-blur-md max-w-md mx-4 pointer-events-auto">
            <div>
              <h2 className="text-5xl font-display font-black text-white mb-2 tracking-tight" style={{ textShadow: `0 0 20px ${difficulty.color}` }}>
                {difficulty.label.toUpperCase()}
              </h2>
              <div className="h-1 w-24 mx-auto rounded-full" style={{ backgroundColor: difficulty.color, boxShadow: `0 0 10px ${difficulty.color}` }}></div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm font-mono text-slate-400 bg-black/30 p-4 rounded-lg">
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Goal</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                      {isEndless ? (
                        <>Endless <InfinityIcon className="w-3 h-3" /></>
                      ) : (
                        "15 Seconds"
                      )}
                    </span>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] uppercase text-slate-500">Best Time</span>
                    <span className="text-white font-bold flex items-center justify-center gap-1">
                        <Crown className="w-3 h-3 text-yellow-500" />
                        {bestTime > 0 ? `${bestTime}s` : '--'}
                    </span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-2 text-xs text-slate-500 uppercase tracking-widest mb-4">
              <ChevronsUp className="w-4 h-4 animate-bounce" /> Hold Space to Fly
            </div>

            <button
              onClick={() => { initAudio(); onStatusChange(GameStatus.Playing); }}
              className="group relative w-full py-4 bg-white text-black font-display font-black text-xl rounded hover:scale-[1.02] transition-transform overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
              START RUN
            </button>
          </div>
        </div>
      )}

      {/* GAME OVER SCREEN */}
      {status === GameStatus.Lost && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-200 pointer-events-none">
          <div className="relative mb-4">
             <AlertTriangle className="w-20 h-20 text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
             <div className="absolute -bottom-2 -right-2 bg-red-600 rounded-full p-1 animate-ping"></div>
          </div>

          <h2 className="text-6xl font-display font-black text-white italic mb-2 tracking-tighter text-glow">CRASHED</h2>

          <div className="mb-8 flex flex-col items-center">
             <span className="text-red-200 font-mono text-sm uppercase tracking-widest mb-1">
                {isEndless ? "Time Survived" : "Attempt Failed"}
             </span>
             <span className="text-4xl font-mono font-bold text-white">
                {(gameState.current.startTime ? ((Date.now() - gameState.current.startTime)/1000).toFixed(2) : "0.00")}s
             </span>

             {/* Consistency Report on Death */}
             <div className="mt-4 flex items-center gap-4 text-xs font-mono">
                 <span className="text-slate-400">Consistency: 
                    <span className={`ml-1 font-bold ${gameState.current.consistencyScore > 90 ? 'text-green-400' : 'text-yellow-400'}`}>
                        {consistency}
                    </span>
                 </span>
                 <span className="text-slate-400">Attempt {attempts}</span>
             </div>
          </div>

          <div className="flex flex-col items-center gap-3 pointer-events-auto">
             <button
                onClick={() => onStatusChange(GameStatus.Idle)}
                className="px-10 py-3 bg-red-600 hover:bg-red-500 text-white font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] transition-all"
             >
                Retry
             </button>
             <span className="text-xs text-red-300/60 font-mono uppercase tracking-widest flex items-center gap-2">
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div> 
                 Press Space to Restart
                 <div className="w-8 h-1 bg-white/20 rounded-full"></div>
             </span>
          </div>
        </div>
      )}

      {/* WIN SCREEN */}
      {status === GameStatus.Won && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-yellow-950/80 backdrop-blur-sm z-10 animate-in zoom-in-95 duration-500 pointer-events-none">
          <Trophy className="w-24 h-24 text-yellow-400 mb-6 drop-shadow-[0_0_25px_rgba(250,204,21,0.6)] animate-pulse" />
          <h2 className="text-6xl font-display font-black text-white mb-2 tracking-tighter text-glow">CLEARED!</h2>
          <p className="text-yellow-100 mb-8 font-mono text-lg">{difficulty.label} Complete</p>
          <div className="text-center mb-8">
               <div className="text-xs text-yellow-500/80 uppercase font-mono tracking-widest mb-1">Stability</div>
               <div className="text-3xl font-bold text-white">{consistency}</div>
          </div>
          <button
            onClick={() => onStatusChange(GameStatus.Idle)}
            className="pointer-events-auto px-10 py-3 bg-yellow-500 hover:bg-yellow-400 text-black font-bold font-display uppercase tracking-widest rounded shadow-[0_0_20px_rgba(234,179,8,0.4)] hover:shadow-[0_0_30px_rgba(234,179,8,0.6)] transition-all"
          >
            Play Again
          </button>
        </div>
      )}

       <div className="absolute top-6 left-6 pointer-events-none">
          <div 
            className="px-4 py-2 rounded-sm bg-black/60 backdrop-blur-md border-l-4 text-sm font-bold text-white uppercase tracking-widest shadow-lg mb-2"
            style={{ borderColor: gameState.current.baseColor }}
          >
              {difficulty.label} {isEndless && <span className="text-blue-400 ml-1">(∞)</span>}
          </div>
          {bestTime > 0 && (
             <div className="flex items-center gap-1 text-xs text-yellow-500 font-mono bg-black/40 px-2 py-1 rounded">
                <Crown className="w-3 h-3" /> Best: {bestTime}s
             </div>
          )}
      </div>
    </div>
  );
};

export default GameCanvas;

import React, { useState, useEffect } from 'react';
import { Difficulty, GameStatus } from '../types';
import { DIFFICULTY_CONFIGS } from '../constants';
import DifficultySelector from './DifficultySelector';
import GameCanvas from './GameCanvas';
import { Activity, TrendingUp, MousePointerClick, Infinity as InfinityIcon, Minimize2 } from 'lucide-react';

const WaveSimulator: React.FC = () => {
  // Initialize with saved difficulty if present
  const [difficulty, setDifficulty] = useState<Difficulty>(() => {
    const saved = localStorage.getItem('gd_spam_last_difficulty');
    return (saved && Object.values(Difficulty).includes(saved as Difficulty)) 
      ? (saved as Difficulty) 
      : Difficulty.Easy;
  });

  // Initialize Endless Mode state
  const [isEndless, setIsEndless] = useState<boolean>(() => {
    return localStorage.getItem('gd_spam_endless_mode') === 'true';
  });

  // Initialize Mini Wave state
  const [isMini, setIsMini] = useState<boolean>(() => {
    return localStorage.getItem('gd_spam_mini_mode') === 'true';
  });

