      {/* Stats / Info Row */}
      <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-4 w-full max-w-5xl">
        <div className="bg-slate-900/40 backdrop-blur border border-white/5 p-5 rounded-lg flex items-center gap-4 hover:bg-slate-900/60 transition-colors group">
