    ctx.strokeStyle = currentColor; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(0, floorHeight); ctx.lineTo(width, floorHeight); ctx.moveTo(0, height - floorHeight); ctx.lineTo(width, height - floorHeight); ctx.stroke();
