             if (isBinding) { e.preventDefault(); const code = (e as KeyboardEvent).code; updateKeybind(code); return; }
             const kbEvent = e as KeyboardEvent; if (kbEvent.code === 'KeyH') { setShowHitbox(prev => !prev); return; }
