         <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 opacity-50 border-inherit"></div>
         <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 opacity-50 border-inherit"></div>
