                     </div>
                 </div>
             </div>
          </div>

          {/* Internal Linking / Related Tools */}
          <div className="border-t border-white/10 pt-8">
              <h3 className="text-xl font-bold text-white mb-6 uppercase tracking-widest flex items-center gap-2">
