                {currentView === 'spacebar' && "SPACEBAR COUNTER"}
                {currentView === 'reaction' && "REACTION TEST"}
                {currentView === 'blog' && "LATEST INSIGHTS"}
                {currentView === '404' && "PAGE NOT FOUND"}
