import React, { useState, useEffect, useRef } from 'react';
import { MousePointer2, RotateCcw, Timer, Activity, Zap, Share2, Check } from 'lucide-react';

interface ClickEffect {
  id: number;
  x: number;
  y: number;
}

const JitterClickTest: React.FC = () => {
  const [active, setActive] = useState(false);
  const [finished, setFinished] = useState(false);
  const [clicks, setClicks] = useState(0);
  const [timeLeft, setTimeLeft] = useState(10.00);
  const [ripples, setRipples] = useState<ClickEffect[]>([]);
  const [copied, setCopied] = useState(false);
  const timerRef = useRef<number | null>(null);

  const startTest = () => {
    setActive(true);
    setFinished(false);
    setClicks(1);
    setTimeLeft(10.00);
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    e.preventDefault();

    // Add Visual Ripple
    const rect = (e.currentTarget as HTMLButtonElement).getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const newRipple = { id: Date.now(), x, y };
    setRipples(prev => [...prev, newRipple]);

    setTimeout(() => {
      setRipples(prev => prev.filter(r => r.id !== newRipple.id));
    }, 500);

    if (finished) return;
    if (!active) {
      startTest();
      return;
    }
    setClicks(c => c + 1);
  };

  const reset = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setActive(false);
    setFinished(false);
    setClicks(0);
    setTimeLeft(10.00);
    setCopied(false);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const shareScore = async (e: React.MouseEvent) => {
     e.stopPropagation();
     const score = (clicks / 10).toFixed(2);
     const text = `I just hit ${score} CPS using Jitter Clicking! ⚡ Can you beat me?`;
     const url = 'https://geometrydashspam.cc/jitter-click';

     if (typeof navigator !== 'undefined' && navigator.share) {
        try {
            await navigator.share({ title: 'Jitter Click Test', text: text, url: url });
            return;
        } catch (err) { console.error(err); }
     }

     navigator.clipboard.writeText(`${text} ${url}`);
     setCopied(true);
     setTimeout(() => setCopied(false), 2000);
  };

  useEffect(() => {
    if (active && !finished) {
      const startTime = Date.now();
      timerRef.current = window.setInterval(() => {
        const elapsed = (Date.now() - startTime) / 1000;
        const remaining = Math.max(0, 10 - elapsed);
        setTimeLeft(remaining);

        if (remaining <= 0) {
          setFinished(true);
          setActive(false);
          if (timerRef.current) clearInterval(timerRef.current);
        }
      }, 10);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [active, finished]);

  const cps = finished ? (clicks / 10).toFixed(2) : (active ? (clicks / (10 - timeLeft)).toFixed(1) : "0.00");

  return (
    <div className="w-full max-w-4xl mx-auto animate-in slide-in-from-bottom-4 duration-500">

      <div className="text-center mb-8">
         <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-orange-500/10 border border-orange-500/20 text-xs font-mono text-orange-400 mb-4">
            <Activity className="w-3 h-3" /> TECHNIQUE: JITTER CLICK
         </div>
         <h1 className="text-4xl md:text-6xl font-display font-black text-white mb-4 drop-shadow-2xl uppercase">
            Jitter Click Test
         </h1>
         <p className="text-slate-400 max-w-2xl mx-auto">
            Test your arm vibration speed. Jitter clicking is essential for high CPS in Minecraft and Geometry Dash spam sections.
         </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-stretch mb-12">
        <div className="relative aspect-square md:aspect-auto md:h-[400px]">
          <button
            onPointerDown={handlePointerDown}
            className={`
              w-full h-full rounded-2xl border-2 flex flex-col items-center justify-center transition-all duration-75 select-none relative overflow-hidden touch-none
              ${finished 
                ? 'bg-slate-900 border-slate-700 cursor-default opacity-50' 
                : 'bg-gradient-to-br from-orange-600 to-red-800 border-orange-500 shadow-[0_0_40px_rgba(249,115,22,0.3)] active:scale-[0.98] active:bg-orange-700 cursor-pointer'
              }
            `}
          >
            {ripples.map(r => (
               <span 
                 key={r.id}
                 className="absolute rounded-full bg-white/30 animate-ping pointer-events-none"
                 style={{ left: r.x, top: r.y, width: '20px', height: '20px', transform: 'translate(-50%, -50%)' }}
               />
            ))}

            {!active && !finished && (
              <>
                <Zap className="w-16 h-16 text-white mb-4 animate-pulse" />
                <span className="text-3xl font-display font-bold text-white tracking-widest">START JITTERING</span>
                <span className="text-orange-200 mt-2 font-mono text-sm">10 SECOND TEST</span>
              </>
            )}

            {active && (
              <>
                <span className="text-8xl font-display font-black text-white drop-shadow-lg scale-110 transition-transform">{clicks}</span>
                <span className="text-orange-200 mt-4 font-mono uppercase tracking-widest">Clicks</span>
              </>
            )}

            {finished && (
               <span className="text-2xl font-display font-bold text-slate-400">TEST COMPLETE</span>
            )}
          </button>
        </div>

        <div className="flex flex-col gap-4">
           <div className="bg-slate-900/50 backdrop-blur border border-white/10 p-6 rounded-2xl flex items-center justify-between">
              <div className="flex items-center gap-3">
                 <div className="p-3 rounded-lg bg-slate-800 text-orange-400">
                    <Timer className="w-6 h-6" />
                 </div>
                 <div>
                    <h3 className="text-slate-400 text-xs font-bold uppercase tracking-widest">Time Remaining</h3>
                    <p className="text-3xl font-mono font-bold text-white tabular-nums">{timeLeft.toFixed(2)}s</p>
                 </div>
              </div>
           </div>

           <div className="flex-grow bg-slate-900/50 backdrop-blur border border-white/10 p-8 rounded-2xl flex flex-col items-center justify-center text-center relative overflow-hidden group">
               <div className="absolute inset-0 bg-orange-600/5 group-hover:bg-orange-600/10 transition-colors"></div>
               <h3 className="text-slate-400 font-bold uppercase tracking-widest mb-2 relative z-10">Jitter Speed</h3>
               <div className="text-7xl font-display font-black text-white mb-2 text-glow relative z-10">{finished ? cps : (active ? cps : '0.00')}</div>
               <div className="text-xl text-orange-400 font-mono relative z-10 mb-6">CPS</div>

               {finished && (
                 <div className="animate-in fade-in duration-300 relative z-10 flex gap-3">
                   <button 
                    onClick={reset}
                    className="px-6 py-3 bg-white text-orange-900 font-bold rounded-lg flex items-center gap-2 hover:bg-orange-50 transition-colors shadow-lg"
                   >
                     <RotateCcw className="w-5 h-5" /> RETRY
                   </button>
                   <button 
                    onClick={shareScore}
                    className={`px-4 py-3 bg-orange-600 text-white font-bold rounded-lg flex items-center gap-2 hover:bg-orange-500 transition-colors shadow-lg ${copied ? 'bg-green-500' : ''}`}
                   >
                     {copied ? <Check className="w-5 h-5" /> : <Share2 className="w-5 h-5" />}
                   </button>
                 </div>
               )}
           </div>
        </div>
      </div>

      <section className="bg-slate-900/40 border border-white/5 rounded-2xl p-8 md:p-12">
        <h2 className="text-3xl font-display font-bold text-white mb-6 flex items-center gap-3">
             <Activity className="w-8 h-8 text-orange-500"/> What is Jitter Clicking?
        </h2>
        <div className="prose prose-invert prose-lg max-w-none text-slate-300">
             <p>
                 <strong>Jitter clicking</strong> is a technique where a player vibrates their hand and forearm muscles to click the mouse button as fast as possible. Unlike normal clicking, which uses the finger muscles, jitter clicking engages the entire arm.
             </p>
             <h4 className="text-white font-bold mt-4">How to Jitter Click:</h4>
             <ul className="list-disc pl-5 space-y-2 text-sm">
                 <li><strong>Tense your forearm:</strong> Stiffen your arm muscles until your hand starts to vibrate uncontrollably.</li>
                 <li><strong>Rest your fingertips:</strong> Place your finger lightly on the mouse button. Do not press down hard.</li>
                 <li><strong>Transfer the vibration:</strong> Let the shaking of your arm trigger the mouse switch repeatedly.</li>
             </ul>
             <div className="bg-orange-900/20 border border-orange-500/20 p-4 rounded-lg mt-6">
                 <p className="text-sm text-orange-200">
                     <strong>Warning:</strong> Jitter clicking can strain your arm muscles. Take breaks to avoid fatigue or injury (RSI).
                 </p>
             </div>
        </div>
      </section>
    </div>
  );
};

export default JitterClickTest;

