// 2. Path Mapping for Clean URLs (SEO Friendly)
const PATH_MAP: Record<string, string> = {
    game: '/',
    cps: '/cps-test',
    jitter: '/jitter-click',
    butterfly: '/butterfly-click',
    rightClick: '/right-click',
