    // Breadcrumbs
    const breadcrumbList = {
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        "itemListElement": [
            { "@type": "ListItem", "position": 1, "name": "Home", "item": baseUrl },
            { "@type": "ListItem", "position": 2, "name": meta?.title?.split('|')[0].trim() || view, "item": currentUrl }
        ]
    };

    const schemaData: any[] = [breadcrumbList];

    // FAQ Schema
    if (meta && meta.faq) {
        schemaData.push({
            "@context": "https://schema.org",
            "@type": "FAQPage",
            "mainEntity": meta.faq.map(item => ({
                "@type": "Question",
                "name": item.question,
                "acceptedAnswer": {
                    "@type": "Answer",
                    "text": item.answer
                }
            }))
        });
    }

    // Video Game Schema Upgrade (More Specific than SoftwareApplication)
    if (view === 'game' || ['cps', 'jitter', 'butterfly', 'spacebar', 'reaction'].includes(view)) {
        schemaData.push({
            "@context": "https://schema.org",
            "@type": "VideoGame",
            "name": meta?.title || "Geometry Dash Spam Test",
            "url": currentUrl,
            "description": meta?.desc,
            "genre": ["Rhythm", "Action", "Arcade"],
            "gamePlatform": ["Web Browser", "PC", "Mobile"],
            "playMode": "SinglePlayer",
            "applicationCategory": "GameApplication",
            "operatingSystem": "Any",
            "aggregateRating": {
                "@type": "AggregateRating",
                "ratingValue": "4.9",
                "ratingCount": "12580",
                "bestRating": "5",
                "worstRating": "1"
            },
            "offers": { "@type": "Offer", "price": "0", "priceCurrency": "USD" }
        });
    } else if (view === 'article' && post) {
        schemaData.push({
            "@context": "https://schema.org",
            "@type": "BlogPosting",
            "headline": post.title,
            "image": post.coverImage,
            "datePublished": new Date(post.date).toISOString().split('T')[0], 
            "dateModified": new Date(post.date).toISOString().split('T')[0], // Good for Google News
            "author": { "@type": "Organization", "name": "GD Spam Team", "url": baseUrl },
            "publisher": { "@type": "Organization", "name": "Geometry Dash Spam Test", "logo": { "@type": "ImageObject", "url": `${baseUrl}/logo.svg` } },
            "description": post.excerpt,
            "mainEntityOfPage": { "@type": "WebPage", "@id": currentUrl }
        });
    }

    return schemaData;
};

